window.I18N_LANGS=[["en","English"],["no","Norsk"],["de","Deutsch"],["dk","Dansk"],["es","Español"],["et","Eesti"],["nl","Nederlands"],["pl","Polski"],["pt","Português"],["tr","Türkçe"],["cn","简体中文"],["ta","தமிழ்"]];
window.I18N={"en":{"meta_title":"Unlimited Cloth: FiveM clothing and tattoo builder","meta_desc":"Unlimited Cloth is a free desktop program for Windows and Linux that makes GTA V freemode clothing and tattoos ready for FiveM: pack builder, studio fix tools, 3D preview with animations and a tattoo builder.","langlabel":"Language","theme_light":"Switch to light mode","theme_dark":"Switch to dark mode","nav_more":"More","skip":"Skip to content","nav_what":"Features","nav_dl":"Download","nav_install":"Install","nav_start":"Getting started","nav_clothes":"Clothing","nav_tattoos":"Tattoos","nav_studio":"Studio","nav_faq":"FAQ","nav_changelog":"Changelog","h_badge":"Free · MIT · Windows and Linux · version 1.0.0","h_title":"FiveM clothing and tattoos, ready to stream","h_sub":"Unlimited Cloth makes GTA V freemode clothing and tattoos ready for FiveM. Import garments or whole addon packs, fix them in the studio, try them on the animated freemode ped and build a finished resource and .zip. Every file it writes is read back and checked.","h_dl":"Download 1.0.0","h_start":"Getting started","h_note":"No browser tab, no network port, no Blender, Python or CodeWalker needed. Made by Unlimited Reforge.","alt_studio":"The Studio tab: the female freemode ped in a crop top and leather trousers, with the fix tools on the right","w_title":"What it does","w_sub":"One program for the whole job, from loose files to a resource you can <code>ensure</code>.","w1_t":"Clothing pack builder","w1_d":"Components and props for <code>mp_m_freemode_01</code> and <code>mp_f_freemode_01</code>, numbered for you, checked against the game's limits and written as <code>fxmanifest.lua</code>, <code>stream/</code>, <code>.ymt</code> and shop <code>.meta</code>, plus a .zip.","w2_t":"Studio fix tools","w2_d":"Copy weights from the body, push out of the body, fit and shrinkwrap, LODs, shaders, props, hair alternates, heels, cloth physics and texture tools. Every job can be undone.","w3_t":"3D preview and animations","w3_d":"The freemode ped with skin and your garments, 31 poses and animations, and <b>Show clipping</b>, which marks in red where the body comes through, how deep and at which bone.","w4_t":"Tattoo builder","w4_d":"PNG in, 512×512 DXT5 .ytd out. Place each tattoo per zone and per body in 3D or in the UV square, and get the overlay XML and ready lists for qb, esx and illenium-appearance.","w5_t":"Safe with your files","w5_d":"Fix jobs work on a copy in the project folder, so your original is never changed. Nothing is ever deleted for good: an old build goes to the system trash.","w6_t":"Projects and languages","w6_d":"Plain JSON projects (<code>.ucloth</code>) with relative paths that open on both Windows and Linux, autosave for crash recovery, undo and redo. The program speaks 12 languages.","c_clip":"Show clipping in the walk animation","c_tat":"A tattoo placed in 3D","c_build":"Build: the plan and the re-read check","d_title":"Download","d_sub":"Version 1.0.0. All files are on the GitHub release page, together with the release notes.","d_win_d":"Installer: pick a folder, get shortcuts, uninstall from Apps.","d_deb_d":"Debian, Ubuntu, Mint, Pop!_OS and other apt systems.","d_app_d":"One file that runs on most distributions, with no install.","d_all":"All releases","d_note":"The freemode peds the preview uses come with the program; nothing else has to be downloaded.","i_title":"Install","i_win_steps":"<li>Run <code>Unlimited-Cloth-Setup-1.0.0.exe</code>.</li><li>Pick the install folder. Desktop and Start menu shortcuts are made.</li><li>Uninstall later under Settings → Apps.</li>","i_win_warn":"<b>\"Windows protected your PC\" / unknown publisher.</b> The installer is signed with Unlimited Reforge's own certificate, which Windows does not know yet, so Microsoft SmartScreen may stop it the first time. Click <b>More info</b>, check that the file is the one from the release page, then click <b>Run anyway</b>.","i_deb":"<b>.deb</b> (Debian, Ubuntu and similar):","i_app":"<b>AppImage</b>: make it executable and run it.","i_fuse":"If the AppImage does not start on Ubuntu 22.04 or newer, install FUSE 2: <code>sudo apt install libfuse2</code> (<code>libfuse2t64</code> on 24.04).","i_where_t":"Where things are kept","i_where_d":"Settings, autosave and your own peds: <code>%APPDATA%\\Unlimited Cloth</code> on Windows, <code>~/.config/Unlimited Cloth</code> on Linux. Built resources go to <code>Documents/Unlimited Cloth/build</code> unless you choose another folder.","s_title":"Getting started","s1_t":"First-run setup","s1_d":"The program starts in English and walks you through language, preferences, folders, peds and the defaults for new projects. You can skip it and run it again from <b>?</b> → <b>Run setup again</b>.","s2_t":"Try it with test content","s2_d":"Press <b>Test garments</b> on the Garments tab. You get a test top for each body and a cap for both, made by the program itself, so you can try every tool before you use your own files.","s3_t":"Import your garments","s3_d":"<b>+ Import files</b> takes <code>.ydd</code>, <code>.ytd</code>, <code>.yld</code>, Sollumz/CodeWalker <code>.ydd.xml</code>, <code>.glb</code>, <code>.obj</code>, <code>.blend</code> and <code>.png</code>. <b>Folder / pack</b> takes a whole folder or an existing addon pack.","s4_t":"Body, slot and textures","s4_d":"For each garment choose the body (male, female or both), the component or prop slot and up to 26 texture variants (a–z). A <b>!</b> in the list means something is still missing.","s5_t":"Check, then build","s5_d":"On the Build tab press <b>Check (plan)</b> to see every file, number and limit before anything is written. Then press <b>Build everything</b>. The result is read back and checked.","s6_t":"On the server","s6_d":"Copy the resource folders to <code>resources/</code> and add them to <code>server.cfg</code>. Try a new pack on a test server before you put it on a live one.","cl_title":"Clothing builder","cl_sub":"The Garments tab holds the list; the Build tab writes the resource.","cl1_t":"Numbers","cl1_l":"<li>The order in the list is the number: empty means the next free number in that slot.</li><li>A fixed number keeps saved outfits pointing at the same garment. If two garments ask for the same number, the first keeps it and the other gets the next free one, and the plan says so.</li><li>Past 255 drawables of one kind the rest go into a second collection (<code>&lt;collection&gt;2</code>).</li><li>A gap below the highest number is filled with an invisible dummy, because the game reads 000 upwards.</li>","cl2_t":"Limits it checks","cl2_l":"<li>255 drawables per slot and body, 26 textures (a–z) per garment.</li><li>Ped streaming slots for the server's game build.</li><li>Shop entries, file name length (under 128 bytes), lower-case names.</li><li>A garment without a slot, a body or a texture is a fault and is never guessed.</li>","cl3_t":"What is written","cl3_d":"<code>fxmanifest.lua</code>, <code>stream/</code> with the models, textures and cloth physics, one <code>.ymt</code> and one shop <code>.meta</code> per body, first-person models (<code>_1.ydd</code>), hair swaps (<code>pedalternatevariations.meta</code>), heel heights, and a <code>.zip</code> of the folder.","cl4_t":"Rebuilding an existing pack","cl4_d":"Import a built pack with <b>Folder / pack</b> to rename its collection or join packs. Flags, audio profiles, heel heights, prop hair, hair swaps and the collection name come back from its <code>.ymt</code> and <code>.meta</code> files.","t_title":"Tattoos","t1_t":"Make and place","t1_l":"<li><b>+ Tattoo (PNG)</b>: each picture becomes a 512×512 DXT5 <code>.ytd</code>. A ready <code>.ytd</code> works too; the texture inside gets the tattoo's Id in the build.</li><li>Choose the body zone, then place the tattoo separately on the male and the female body: in 3D on the ped, or in the <b>UV square</b> (drag to move, mouse wheel to resize).</li><li>The Id is the hash name. When it is empty, the file name is used.</li>","t2_t":"What is written","t2_l":"<li>The overlay XML and <code>fxmanifest.lua</code> with <code>PED_OVERLAY_FILE</code>.</li><li>Optional <code>shop_tattoo.meta</code> (only the base game's tattoo shop reads it).</li><li>Optional Menu lists in <code>exports/</code>: qb (<code>AllTattoos.json</code>), esx (<code>Config.TattooList</code>) and illenium-appearance. Newer illenium-appearance versions find the tattoos in the overlay file by themselves, so that list is off by default.</li>","t_box":"Give the tattoo resource its own name. The program refuses to build if the tattoo and clothing resources would land in the same folder, because building one would move the other to the trash.","st_title":"Studio tools","st_sub":"Jobs work on a copy of the model in the project folder. Every job can be undone with Ctrl+Z, files included. A job that fails puts the file back as it was.","st_group":"Group","st_tools":"Tools","st_g_weights":"Weights","st_r_weights":"Copy weights from body · Smooth weights · Make weights legal · Sync seam weights","st_g_fit":"Fit and shape","st_r_fit":"Push out of body · Inflate / deflate · Fit to body · Shrinkwrap to body · Hem above floor · Mirror left/right · Align sleeves · Taper sleeves · Apply move / turn / scale","st_g_mesh":"Mesh","st_r_mesh":"Fix normals · Weld seams · Close openings · Close gaps · Solidify (inside) · Rewrite whole file","st_g_lod":"Level of detail","st_r_lod":"Make LODs · Weight the LODs · Reduce triangles","st_g_special":"Props, hair, heels, physics","st_r_special":"Make into prop · Hair alternate · Heel pose · Heel bones · Make cloth physics (.yld) · Rebind cloth physics · Crop unused texture","st_g_shader":"Shader","st_r_shader":"27 ped shaders, with a note on what each one is for.","st_g_tex":"Textures","st_r_tex":"+ From PNG (DXT1/DXT5 with mipmaps) · Recolour → new variant · Replace from PNG · Export as PNG · Normal + spec maps (PNG)","st_g_export":"Export model","st_r_export":"Sollumz / CodeWalker XML · .obj (Blender etc.)","p_intro":"The Build tab has a <code>subdir_file_mapping</code> checkbox. When it is on, the clothing resource's <code>fxmanifest.lua</code> gets this line:","p_list":"<li><b>Off is the default.</b> With the line, a server that does not have the policy refuses to start the resource at all.</li><li><b>Without the line</b>, a server that lacks the policy loads the pack and shows no clothes, with nothing in the console. A server with 10 slots or fewer gets the policy automatically; above that it comes with an Element Club Argentum (or higher) subscription.</li><li><b>Turn it on</b> when your server has more than 10 slots and has the policy, so a missing policy shows up as a clear start error instead of invisible clothes. Leave it off on a server with 10 slots or fewer.</li><li>The build plan reminds you when it is off. Whether the line is needed has not been proven in game yet, so test on your own server.</li>","q1":"Is it free?","a1":"Yes. Unlimited Cloth is free and open under the MIT licence, made by Unlimited Reforge.","q2":"Do I need GTA V, Blender or CodeWalker?","a2":"No. The program reads and writes the game formats itself, and the freemode peds for the preview come with it. On the Peds tab you can use files from your own game instead (optional).","q3":"Which clothing menus does it work with?","a3":"The clothing resource is a normal addon pack, so any menu that reads addon clothing shows it. For tattoos the program writes lists for qb, esx and illenium-appearance. Check the field names against your version of the menu.","q4":"Will it change my original files?","a4":"No. Fix jobs work on a copy in the project folder, and anything in the way (an old build, for example) goes to the system trash. Nothing is deleted for good.","q5":"My clothes do not show in game","a5":"<li>Check how many slots the server has and the <a href=\"#policy\">subdir_file_mapping</a> policy.</li><li>Make sure the resource is started (<code>ensure</code>) and that the server's game build is the one chosen on the Build tab.</li><li>Use <b>Check an existing pack…</b> on the Build tab to read the folder back.</li>","q6":"Why does Windows warn about an unknown publisher?","a6":"The installer is signed with Unlimited Reforge's own certificate, not one bought from a certificate authority, so Windows does not know the publisher yet. See <a href=\"#install\">Install</a> for how to get past SmartScreen.","q7":"Where do I get help?","a7":"Questions, bugs and ideas go to the <a href=\"https://discord.gg/uaASPkghXu\" rel=\"noopener\">Unlimited Discord</a>. The program has no e-mail address.","ch_title":"Changelog","ch_first":"first release","ch_list":"<li>Clothing pack builder: import of .ydd/.ytd/.yld, whole addon packs, .ydd.xml, .glb, .obj and .blend; numbering, limit checks, a second collection past 255, .zip.</li><li>Rebuilding a pack keeps its flags, audio, heels, prop hair, hair swaps and collection name.</li><li>Studio with fix jobs for weights, fit, mesh, LODs, props, hair, heels and cloth physics, 27 shaders, texture tools and Sollumz/.obj export; undo and redo for every job.</li><li>3D preview with 31 poses and animations and a clipping check.</li><li>Tattoo builder with 3D and UV placement, overlay XML, shop_tattoo.meta and lists for qb, esx and illenium-appearance.</li><li>Every built file is read back: models (with a round trip), textures, .ymt (components and props), shop meta, mounted data files and the engine's own pack checks.</li><li>Bundled freemode peds; your own game files are optional and fill in only what you give them.</li><li>First-run setup, 12 languages, autosave and crash recovery.</li>","ch_known":"Known limits: newly written .ydd files have only been proven in game with the test pack, importing from a GTA V install is untested, and the Windows build is new. Test on a test server first.","dc_title":"Questions? Join the Discord","dc_sub":"Support, bug reports and ideas for Unlimited Cloth and the rest of Unlimited.","dc_btn":"Open the Unlimited Discord","f_lic":"© 2026 Unlimited Reforge · MIT licence","f_rock":"The bundled freemode peds are derived from Rockstar Games assets. Unlimited Reforge is not affiliated with Rockstar Games or Cfx.re.","ss_btn":"Search the site","ss_ph":"Search the site…","ss_none":"Nothing found. Try another word.","ss_more":"{n} more results. Type more to narrow it down.","ss_close":"Close search"},"no":{"meta_title":"Unlimited Cloth: klær og tatoveringer for FiveM","meta_desc":"Unlimited Cloth er et gratis skrivebordsprogram for Windows og Linux som gjør GTA V freemode-klær og tatoveringer klare for FiveM: pakkebygger, fikseverktøy i studio, 3D-forhåndsvisning med animasjoner og tatoveringsbygger.","langlabel":"Språk","theme_light":"Bytt til lys modus","theme_dark":"Bytt til mørk modus","nav_more":"Mer","skip":"Hopp til innholdet","nav_what":"Funksjoner","nav_dl":"Last ned","nav_install":"Installer","nav_start":"Kom i gang","nav_clothes":"Klær","nav_tattoos":"Tatoveringer","nav_studio":"Studio","nav_faq":"Spørsmål og svar","nav_changelog":"Endringslogg","h_badge":"Gratis · MIT · Windows og Linux · versjon 1.0.0","h_title":"Klær og tatoveringer for FiveM, klare til streaming","h_sub":"Unlimited Cloth gjør GTA V freemode-klær og tatoveringer klare for FiveM. Importer plagg eller hele addon-pakker, fiks dem i studioet, prøv dem på den animerte freemode-peden og bygg en ferdig ressurs og .zip. Hver fil programmet skriver, blir lest inn igjen og sjekket.","h_dl":"Last ned 1.0.0","h_start":"Kom i gang","h_note":"Ingen nettleserfane, ingen nettverksport, og du trenger verken Blender, Python eller CodeWalker. Laget av Unlimited Reforge.","alt_studio":"Studio-fanen: den kvinnelige freemode-pedden i kort topp og skinnbukse, med fiksverktøyene til høyre","w_title":"Hva det gjør","w_sub":"Ett program for hele jobben, fra løse filer til en ressurs du kan kjøre <code>ensure</code> på.","w1_t":"Klespakkebygger","w1_d":"Komponenter og props for <code>mp_m_freemode_01</code> og <code>mp_f_freemode_01</code>, nummerert for deg, sjekket mot spillets grenser og skrevet som <code>fxmanifest.lua</code>, <code>stream/</code>, <code>.ymt</code> og butikk-<code>.meta</code>, pluss en .zip.","w2_t":"Fikseverktøy i studio","w2_d":"Kopier vekter fra kroppen, skyv ut av kroppen, tilpass og krymp til kroppen, LOD-er, shadere, props, alternativt hår, hæler, stoffysikk og teksturverktøy. Alle jobber kan angres.","w3_t":"3D-forhåndsvisning og animasjoner","w3_d":"Freemode-peden med hud og plaggene dine, 31 positurer og animasjoner, og <b>Vis klipping</b>, som markerer med rødt hvor kroppen stikker gjennom, hvor dypt og ved hvilket bein.","w4_t":"Tatoveringsbygger","w4_d":"PNG inn, 512×512 DXT5 .ytd ut. Plasser hver tatovering per sone og per kropp i 3D eller i UV-ruten, og få overlay-XML og ferdige lister for qb, esx og illenium-appearance.","w5_t":"Trygt for filene dine","w5_d":"Fiksejobber jobber på en kopi i prosjektmappen, så originalen din blir aldri endret. Ingenting slettes for godt: en gammel bygging havner i papirkurven.","w6_t":"Prosjekter og språk","w6_d":"Vanlige JSON-prosjekter (<code>.ucloth</code>) med relative stier som åpnes på både Windows og Linux, autolagring for gjenoppretting etter krasj, angre og gjør om. Programmet finnes på 12 språk.","c_clip":"Vis klipping i gåanimasjonen","c_tat":"En tatovering plassert i 3D","c_build":"Bygg: planen og kontrollen der alt leses inn igjen","d_title":"Last ned","d_sub":"Versjon 1.0.0. Alle filene ligger på utgivelsessiden på GitHub, sammen med utgivelsesnotatene.","d_win_d":"Installasjonsprogram: velg mappe, få snarveier, avinstaller fra Apper.","d_deb_d":"Debian, Ubuntu, Mint, Pop!_OS og andre apt-systemer.","d_app_d":"Én fil som kjører på de fleste distribusjoner, uten installasjon.","d_all":"Alle utgivelser","d_note":"Freemode-pedene som forhåndsvisningen bruker, følger med programmet; ingenting annet må lastes ned.","i_title":"Installer","i_win_steps":"<li>Kjør <code>Unlimited-Cloth-Setup-1.0.0.exe</code>.</li><li>Velg installasjonsmappe. Det lages snarveier på skrivebordet og i Start-menyen.</li><li>Avinstaller senere under Innstillinger → Apper.</li>","i_win_warn":"<b>«Windows beskyttet PC-en» / ukjent utgiver.</b> Installasjonsprogrammet er signert med Unlimited Reforges eget sertifikat, som Windows ikke kjenner ennå, så Microsoft SmartScreen kan stoppe det første gang. Klikk <b>Mer informasjon</b>, sjekk at filen er den fra utgivelsessiden, og klikk deretter <b>Kjør likevel</b>.","i_deb":"<b>.deb</b> (Debian, Ubuntu og lignende):","i_app":"<b>AppImage</b>: gjør filen kjørbar og start den.","i_fuse":"Hvis AppImage-filen ikke starter på Ubuntu 22.04 eller nyere, installer FUSE 2: <code>sudo apt install libfuse2</code> (<code>libfuse2t64</code> på 24.04).","i_where_t":"Hvor ting lagres","i_where_d":"Innstillinger, autolagring og dine egne peds: <code>%APPDATA%\\Unlimited Cloth</code> på Windows, <code>~/.config/Unlimited Cloth</code> på Linux. Bygde ressurser havner i <code>Documents/Unlimited Cloth/build</code> hvis du ikke velger en annen mappe.","s_title":"Kom i gang","s1_t":"Oppsett ved første start","s1_d":"Programmet starter på engelsk og tar deg gjennom språk, innstillinger, mapper, peds og standardverdiene for nye prosjekter. Du kan hoppe over det og kjøre det igjen fra <b>?</b> → <b>Kjør oppsett på nytt</b>.","s2_t":"Prøv med testinnhold","s2_d":"Trykk <b>Testplagg</b> på fanen Plagg. Du får en testoverdel for hver kropp og en caps for begge, laget av programmet selv, så du kan prøve alle verktøyene før du bruker dine egne filer.","s3_t":"Importer plaggene dine","s3_d":"<b>+ Importer filer</b> tar <code>.ydd</code>, <code>.ytd</code>, <code>.yld</code>, Sollumz/CodeWalker <code>.ydd.xml</code>, <code>.glb</code>, <code>.obj</code>, <code>.blend</code> og <code>.png</code>. <b>Mappe / pakke</b> tar en hel mappe eller en eksisterende addon-pakke.","s4_t":"Kropp, plass og teksturer","s4_d":"For hvert plagg velger du kropp (mann, kvinne eller begge), komponent- eller prop-plass og opptil 26 teksturvarianter (a–z). En <b>!</b> i listen betyr at noe fortsatt mangler.","s5_t":"Sjekk, og bygg så","s5_d":"På fanen Bygg trykker du <b>Sjekk (plan)</b> for å se alle filer, numre og grenser før noe blir skrevet. Trykk deretter <b>Bygg alt</b>. Resultatet leses inn igjen og sjekkes.","s6_t":"På serveren","s6_d":"Kopier ressursmappene til <code>resources/</code> og legg dem til i <code>server.cfg</code>. Prøv en ny pakke på en testserver før du legger den på en live-server.","cl_title":"Klesbygger","cl_sub":"Fanen Plagg har listen; fanen Bygg skriver ressursen.","cl1_t":"Numre","cl1_l":"<li>Rekkefølgen i listen er nummeret: tomt betyr neste ledige nummer på den plassen.</li><li>Et fast nummer gjør at lagrede antrekk fortsatt peker på samme plagg. Hvis to plagg ber om samme nummer, beholder det første det, og det andre får neste ledige, og planen sier fra om det.</li><li>Over 255 drawables av én type havner resten i en andre samling (<code>&lt;collection&gt;2</code>).</li><li>Et hull under det høyeste nummeret fylles med en usynlig dummy, fordi spillet leser fra 000 og oppover.</li>","cl2_t":"Grenser som sjekkes","cl2_l":"<li>255 drawables per plass og kropp, 26 teksturer (a–z) per plagg.</li><li>Streamingplasser for peds for serverens game build.</li><li>Butikkoppføringer, lengde på filnavn (under 128 byte), navn med små bokstaver.</li><li>Et plagg uten plass, kropp eller tekstur er en feil, og programmet gjetter aldri.</li>","cl3_t":"Hva som skrives","cl3_d":"<code>fxmanifest.lua</code>, <code>stream/</code> med modellene, teksturene og stoffysikken, én <code>.ymt</code> og én butikk-<code>.meta</code> per kropp, førstepersonsmodeller (<code>_1.ydd</code>), hårbytter (<code>pedalternatevariations.meta</code>), hælhøyder og en <code>.zip</code> av mappen.","cl4_t":"Bygge om en eksisterende pakke","cl4_d":"Importer en ferdig bygd pakke med <b>Mappe / pakke</b> for å gi samlingen nytt navn eller slå sammen pakker. Flagg, lydprofiler, hælhøyder, prop-hår, hårbytter og samlingsnavnet hentes tilbake fra <code>.ymt</code>- og <code>.meta</code>-filene.","t_title":"Tatoveringer","t1_t":"Lag og plasser","t1_l":"<li><b>+ Tatovering (PNG)</b>: hvert bilde blir en 512×512 DXT5 <code>.ytd</code>. En ferdig <code>.ytd</code> fungerer også; teksturen i den får tatoveringens Id i byggingen.</li><li>Velg kroppssonen, og plasser så tatoveringen hver for seg på mannekroppen og kvinnekroppen: i 3D på peden eller i visningen <b>UV-rute</b> (dra for å flytte, musehjulet for å endre størrelse).</li><li>Id-en er hash-navnet. Når den er tom, brukes filnavnet.</li>","t2_t":"Hva som skrives","t2_l":"<li>Overlay-XML og <code>fxmanifest.lua</code> med <code>PED_OVERLAY_FILE</code>.</li><li>Valgfri <code>shop_tattoo.meta</code> (bare tatoveringsbutikken i grunnspillet leser den).</li><li>Valgfritt: Menylister i <code>exports/</code>: qb (<code>AllTattoos.json</code>), esx (<code>Config.TattooList</code>) og illenium-appearance. Nyere versjoner av illenium-appearance finner tatoveringene i overlay-filen selv, så den listen er av som standard.</li>","t_box":"Gi tatoveringsressursen sitt eget navn. Programmet nekter å bygge hvis tatoverings- og klesressursen ville havnet i samme mappe, fordi byggingen av den ene da ville flyttet den andre til papirkurven.","st_title":"Studioverktøy","st_sub":"Jobbene jobber på en kopi av modellen i prosjektmappen. Alle jobber kan angres med Ctrl+Z, filene også. En jobb som feiler, setter filen tilbake slik den var.","st_group":"Gruppe","st_tools":"Verktøy","st_g_weights":"Vekter","st_r_weights":"Kopier vekter fra kroppen · Glatt vekter · Gjør vektene gyldige · Synkroniser sømvekter","st_g_fit":"Tilpasning og form","st_r_fit":"Skyv ut av kroppen · Blås opp / tøm · Tilpass kroppen · Krymp til kroppen · Kant over gulvet · Speil venstre/høyre · Rett inn ermer · Smalne ermer · Bruk flytt / roter / skaler","st_g_mesh":"Mesh","st_r_mesh":"Fiks normaler · Sveis sømmer · Lukk åpninger · Lukk glipper · Gi tykkelse (innside) · Skriv hele filen på nytt","st_g_lod":"Detaljnivå","st_r_lod":"Lag LOD-er · Vekt LOD-ene · Reduser trekanter","st_g_special":"Props, hår, hæler, fysikk","st_r_special":"Gjør om til prop · Alternativt hår · Hælpositur · Hælbein · Lag stoffysikk (.yld) · Bind stoffysikk på nytt · Beskjær ubrukt tekstur","st_g_shader":"Shader","st_r_shader":"27 ped-shadere, med en merknad om hva hver av dem er til.","st_g_tex":"Teksturer","st_r_tex":"+ Fra PNG (DXT1/DXT5 med mipmaps) · Farg om → ny variant · Erstatt fra PNG · Eksporter som PNG · Normal- + spec-kart (PNG)","st_g_export":"Eksporter modell","st_r_export":"Sollumz / CodeWalker XML · .obj (Blender osv.)","p_intro":"Fanen Bygg har en avkrysningsboks for <code>subdir_file_mapping</code>. Når den er på, får <code>fxmanifest.lua</code> i klesressursen denne linjen:","p_list":"<li><b>Av er standard.</b> Med linjen nekter en server som ikke har policyen, å starte ressursen i det hele tatt.</li><li><b>Uten linjen</b> laster en server som mangler policyen, pakken og viser ingen klær, uten noe i konsollen. En server med 10 plasser eller færre får policyen automatisk; over det følger den med et Element Club Argentum-abonnement (eller høyere).</li><li><b>Slå den på</b> når serveren din har mer enn 10 plasser og har policyen, så en manglende policy viser seg som en tydelig startfeil i stedet for usynlige klær. La den være av på en server med 10 plasser eller færre.</li><li>Byggeplanen minner deg på det når den er av. Det er ennå ikke bevist i spillet om linjen trengs, så test på din egen server.</li>","q1":"Er det gratis?","a1":"Ja. Unlimited Cloth er gratis og åpen kildekode under MIT-lisensen, laget av Unlimited Reforge.","q2":"Trenger jeg GTA V, Blender eller CodeWalker?","a2":"Nei. Programmet leser og skriver spillformatene selv, og freemode-pedene til forhåndsvisningen følger med. På fanen Peds kan du bruke filer fra ditt eget spill i stedet (valgfritt).","q3":"Hvilke klesmenyer fungerer det med?","a3":"Klesressursen er en vanlig addon-pakke, så alle menyer som leser addon-klær, viser den. For tatoveringer skriver programmet lister for qb, esx og illenium-appearance. Sjekk feltnavnene mot din versjon av menyen.","q4":"Endrer det originalfilene mine?","a4":"Nei. Fiksejobber jobber på en kopi i prosjektmappen, og alt som står i veien (for eksempel en gammel bygging) havner i papirkurven. Ingenting slettes for godt.","q5":"Klærne mine vises ikke i spillet","a5":"<li>Sjekk hvor mange plasser serveren har, og <a href=\"#policy\">subdir_file_mapping</a>-policyen.</li><li>Sørg for at ressursen er startet (<code>ensure</code>), og at serverens game build er den som er valgt på fanen Bygg.</li><li>Bruk <b>Sjekk en eksisterende pakke…</b> på fanen Bygg for å lese mappen inn igjen.</li>","q6":"Hvorfor advarer Windows om en ukjent utgiver?","a6":"Installasjonsprogrammet er signert med Unlimited Reforges eget sertifikat, ikke et som er kjøpt fra en sertifiseringsinstans, så Windows kjenner ikke utgiveren ennå. Se <a href=\"#install\">Installer</a> for hvordan du kommer forbi SmartScreen.","q7":"Hvor får jeg hjelp?","a7":"Spørsmål, feil og ideer tas i <a href=\"https://discord.gg/uaASPkghXu\" rel=\"noopener\">Unlimited Discord</a>. Programmet har ingen e-postadresse.","ch_title":"Endringslogg","ch_first":"første utgivelse","ch_list":"<li>Klespakkebygger: import av .ydd/.ytd/.yld, hele addon-pakker, .ydd.xml, .glb, .obj og .blend; nummerering, sjekk av grenser, en andre samling over 255, .zip.</li><li>Når en pakke bygges om, beholdes flagg, lyd, hæler, prop-hår, hårbytter og samlingsnavn.</li><li>Studio med fiksejobber for vekter, tilpasning, mesh, LOD-er, props, hår, hæler og stoffysikk, 27 shadere, teksturverktøy og eksport til Sollumz/.obj; angre og gjør om for alle jobber.</li><li>3D-forhåndsvisning med 31 positurer og animasjoner og en klippingsjekk.</li><li>Tatoveringsbygger med plassering i 3D og UV, overlay-XML, shop_tattoo.meta og lister for qb, esx og illenium-appearance.</li><li>Hver bygd fil leses inn igjen: modeller (med en rundtur), teksturer, .ymt (komponenter og props), butikk-meta, monterte datafiler og motorens egne pakkesjekker.</li><li>Freemode-peds følger med; dine egne spillfiler er valgfrie og fyller bare inn det du gir dem.</li><li>Oppsett ved første start, 12 språk, autolagring og gjenoppretting etter krasj.</li>","ch_known":"Kjente begrensninger: nyskrevne .ydd-filer er bare bevist i spillet med testpakken, import fra en GTA V-installasjon er ikke testet, og Windows-versjonen er ny. Test på en testserver først.","dc_title":"Spørsmål? Bli med på Discord","dc_sub":"Support, feilrapporter og ideer for Unlimited Cloth og resten av Unlimited.","dc_btn":"Åpne Unlimited Discord","f_lic":"© 2026 Unlimited Reforge · MIT-lisens","f_rock":"De medfølgende freemode-pedene er avledet fra materiale fra Rockstar Games. Unlimited Reforge er ikke tilknyttet Rockstar Games eller Cfx.re.","ss_btn":"Søk på siden","ss_ph":"Søk på siden…","ss_none":"Fant ingenting. Prøv et annet ord.","ss_more":"{n} treff til. Skriv mer for å snevre inn.","ss_close":"Lukk søket"},"de":{"meta_title":"Unlimited Cloth: Kleidung und Tattoos für FiveM","meta_desc":"Unlimited Cloth ist ein kostenloses Desktop-Programm für Windows und Linux, das GTA V Freemode-Kleidung und Tattoos für FiveM fertig macht: Pack-Builder, Reparaturwerkzeuge im Studio, 3D-Vorschau mit Animationen und ein Tattoo-Builder.","langlabel":"Sprache","theme_light":"Zum hellen Modus wechseln","theme_dark":"Zum dunklen Modus wechseln","nav_more":"Mehr","skip":"Zum Inhalt springen","nav_what":"Funktionen","nav_dl":"Download","nav_install":"Installation","nav_start":"Erste Schritte","nav_clothes":"Kleidung","nav_tattoos":"Tattoos","nav_studio":"Studio","nav_faq":"FAQ","nav_changelog":"Changelog","h_badge":"Kostenlos · MIT · Windows und Linux · Version 1.0.0","h_title":"Kleidung und Tattoos für FiveM, bereit zum Streamen","h_sub":"Unlimited Cloth macht GTA V Freemode-Kleidung und Tattoos fertig für FiveM. Importiere Kleidungsstücke oder ganze Addon-Packs, repariere sie im Studio, probiere sie am animierten Freemode-Ped an und baue eine fertige Resource samt .zip. Jede Datei, die das Programm schreibt, wird wieder eingelesen und geprüft.","h_dl":"1.0.0 herunterladen","h_start":"Erste Schritte","h_note":"Kein Browser-Tab, kein Netzwerkport, kein Blender, Python oder CodeWalker nötig. Von Unlimited Reforge.","alt_studio":"Der Tab Studio: der weibliche Freemode-Ped in Crop-Top und Lederhose, rechts die Reparaturwerkzeuge","w_title":"Was es kann","w_sub":"Ein Programm für die ganze Arbeit, von losen Dateien bis zur Resource, die du per <code>ensure</code> startest.","w1_t":"Kleidungs-Pack-Builder","w1_d":"Komponenten und Props für <code>mp_m_freemode_01</code> und <code>mp_f_freemode_01</code>, automatisch nummeriert, gegen die Grenzen des Spiels geprüft und geschrieben als <code>fxmanifest.lua</code>, <code>stream/</code>, <code>.ymt</code> und Shop-<code>.meta</code>, dazu eine .zip.","w2_t":"Reparaturwerkzeuge im Studio","w2_d":"Gewichte vom Körper kopieren, aus dem Körper schieben, anpassen und anschmiegen, LODs, Shader, Props, alternatives Haar, Absätze, Stoffphysik und Texturwerkzeuge. Jeder Vorgang lässt sich rückgängig machen.","w3_t":"3D-Vorschau und Animationen","w3_d":"Der Freemode-Ped mit Haut und deiner Kleidung, 31 Posen und Animationen und <b>Clipping anzeigen</b>: Das markiert rot, wo der Körper durchkommt, wie tief und an welchem Bone.","w4_t":"Tattoo-Builder","w4_d":"PNG rein, 512×512 DXT5 .ytd raus. Platziere jedes Tattoo pro Zone und pro Körper in 3D oder im UV-Quadrat und erhalte das Overlay-XML sowie fertige Listen für qb, esx und illenium-appearance.","w5_t":"Sicher für deine Dateien","w5_d":"Reparaturvorgänge arbeiten an einer Kopie im Projektordner, dein Original wird also nie verändert. Nichts wird endgültig gelöscht: Ein alter Build landet im Papierkorb.","w6_t":"Projekte und Sprachen","w6_d":"Einfache JSON-Projekte (<code>.ucloth</code>) mit relativen Pfaden, die sich unter Windows und Linux öffnen lassen, Autosave zur Wiederherstellung nach Abstürzen, Rückgängig und Wiederholen. Das Programm gibt es in 12 Sprachen.","c_clip":"Clipping anzeigen in der Laufanimation","c_tat":"Ein in 3D platziertes Tattoo","c_build":"Build: der Plan und die Prüfung nach dem erneuten Einlesen","d_title":"Download","d_sub":"Version 1.0.0. Alle Dateien liegen auf der Release-Seite bei GitHub, zusammen mit den Release Notes.","d_win_d":"Installer: Ordner wählen, Verknüpfungen erhalten, über Apps deinstallieren.","d_deb_d":"Debian, Ubuntu, Mint, Pop!_OS und andere apt-Systeme.","d_app_d":"Eine Datei, die auf den meisten Distributionen ohne Installation läuft.","d_all":"Alle Releases","d_note":"Die Freemode-Peds für die Vorschau sind im Programm enthalten; sonst muss nichts heruntergeladen werden.","i_title":"Installation","i_win_steps":"<li>Starte <code>Unlimited-Cloth-Setup-1.0.0.exe</code>.</li><li>Wähle den Installationsordner. Es werden Verknüpfungen auf dem Desktop und im Startmenü angelegt.</li><li>Deinstallieren kannst du später unter Einstellungen → Apps.</li>","i_win_warn":"<b>„Der Computer wurde durch Windows geschützt“ / unbekannter Herausgeber.</b> Der Installer ist mit dem eigenen Zertifikat von Unlimited Reforge signiert, das Windows noch nicht kennt, daher kann Microsoft SmartScreen ihn beim ersten Mal stoppen. Klicke auf <b>Weitere Informationen</b>, prüfe, ob die Datei die von der Release-Seite ist, und klicke dann auf <b>Trotzdem ausführen</b>.","i_deb":"<b>.deb</b> (Debian, Ubuntu und ähnliche):","i_app":"<b>AppImage</b>: ausführbar machen und starten.","i_fuse":"Wenn das AppImage unter Ubuntu 22.04 oder neuer nicht startet, installiere FUSE 2: <code>sudo apt install libfuse2</code> (<code>libfuse2t64</code> unter 24.04).","i_where_t":"Wo alles gespeichert wird","i_where_d":"Einstellungen, Autosave und deine eigenen Peds: <code>%APPDATA%\\Unlimited Cloth</code> unter Windows, <code>~/.config/Unlimited Cloth</code> unter Linux. Gebaute Resources landen in <code>Documents/Unlimited Cloth/build</code>, sofern du keinen anderen Ordner wählst.","s_title":"Erste Schritte","s1_t":"Einrichtung beim ersten Start","s1_d":"Das Programm startet auf Englisch und führt dich durch Sprache, Einstellungen, Ordner, Peds und die Standardwerte für neue Projekte. Du kannst das überspringen und später über <b>?</b> → <b>Einrichtung erneut ausführen</b> nachholen.","s2_t":"Mit Testinhalten ausprobieren","s2_d":"Klicke im Tab Kleidung auf <b>Testkleidung</b>. Du bekommst ein Testoberteil für jeden Körper und eine Cap für beide, vom Programm selbst erzeugt, sodass du jedes Werkzeug ausprobieren kannst, bevor du deine eigenen Dateien nimmst.","s3_t":"Deine Kleidung importieren","s3_d":"<b>+ Dateien importieren</b> nimmt <code>.ydd</code>, <code>.ytd</code>, <code>.yld</code>, Sollumz/CodeWalker <code>.ydd.xml</code>, <code>.glb</code>, <code>.obj</code>, <code>.blend</code> und <code>.png</code>. <b>Ordner / Pack</b> nimmt einen ganzen Ordner oder ein bestehendes Addon-Pack.","s4_t":"Körper, Slot und Texturen","s4_d":"Wähle für jedes Kleidungsstück den Körper (männlich, weiblich oder beide), den Komponenten- oder Prop-Slot und bis zu 26 Texturvarianten (a–z). Ein <b>!</b> in der Liste bedeutet, dass noch etwas fehlt.","s5_t":"Erst prüfen, dann bauen","s5_d":"Klicke im Tab Build auf <b>Prüfen (Plan)</b>, um alle Dateien, Nummern und Grenzen zu sehen, bevor irgendetwas geschrieben wird. Klicke dann auf <b>Alles bauen</b>. Das Ergebnis wird wieder eingelesen und geprüft.","s6_t":"Auf dem Server","s6_d":"Kopiere die Resource-Ordner nach <code>resources/</code> und trage sie in die <code>server.cfg</code> ein. Teste ein neues Pack auf einem Testserver, bevor du es auf einen Live-Server bringst.","cl_title":"Kleidungs-Builder","cl_sub":"Der Tab Kleidung enthält die Liste; der Tab Build schreibt die Resource.","cl1_t":"Nummern","cl1_l":"<li>Die Reihenfolge in der Liste ist die Nummer: Leer bedeutet die nächste freie Nummer in diesem Slot.</li><li>Eine feste Nummer sorgt dafür, dass gespeicherte Outfits auf dasselbe Kleidungsstück zeigen. Wollen zwei Kleidungsstücke dieselbe Nummer, behält das erste sie, das andere bekommt die nächste freie, und der Plan weist darauf hin.</li><li>Über 255 Drawables einer Art kommt der Rest in eine zweite Sammlung (<code>&lt;collection&gt;2</code>).</li><li>Eine Lücke unter der höchsten Nummer wird mit einem unsichtbaren Dummy gefüllt, weil das Spiel ab 000 aufwärts liest.</li>","cl2_t":"Geprüfte Grenzen","cl2_l":"<li>255 Drawables pro Slot und Körper, 26 Texturen (a–z) pro Kleidungsstück.</li><li>Ped-Streaming-Slots für den Game Build des Servers.</li><li>Shop-Einträge, Länge der Dateinamen (unter 128 Bytes), kleingeschriebene Namen.</li><li>Ein Kleidungsstück ohne Slot, Körper oder Textur ist ein Fehler, und es wird nie geraten.</li>","cl3_t":"Was geschrieben wird","cl3_d":"<code>fxmanifest.lua</code>, <code>stream/</code> mit den Modellen, Texturen und der Stoffphysik, eine <code>.ymt</code> und eine Shop-<code>.meta</code> pro Körper, First-Person-Modelle (<code>_1.ydd</code>), Haartausch (<code>pedalternatevariations.meta</code>), Absatzhöhen und eine <code>.zip</code> des Ordners.","cl4_t":"Ein bestehendes Pack neu bauen","cl4_d":"Importiere ein gebautes Pack mit <b>Ordner / Pack</b>, um seine Sammlung umzubenennen oder Packs zusammenzuführen. Flags, Audioprofile, Absatzhöhen, Prop-Haar, Haartausch und der Name der Sammlung werden aus seinen <code>.ymt</code>- und <code>.meta</code>-Dateien übernommen.","t_title":"Tattoos","t1_t":"Erstellen und platzieren","t1_l":"<li><b>+ Tattoo (PNG)</b>: Jedes Bild wird zu einer 512×512 DXT5 <code>.ytd</code>. Eine fertige <code>.ytd</code> geht auch; die Textur darin bekommt beim Build die Id des Tattoos.</li><li>Wähle die Körperzone und platziere das Tattoo dann getrennt auf dem männlichen und dem weiblichen Körper: in 3D am Ped oder im <b>UV-Quadrat</b> (ziehen zum Verschieben, Mausrad zum Skalieren).</li><li>Die Id ist der Hash-Name. Ist sie leer, wird der Dateiname verwendet.</li>","t2_t":"Was geschrieben wird","t2_l":"<li>Das Overlay-XML und <code>fxmanifest.lua</code> mit <code>PED_OVERLAY_FILE</code>.</li><li>Optional <code>shop_tattoo.meta</code> (die liest nur der Tattoo-Shop des Basisspiels).</li><li>Optional Menülisten in <code>exports/</code>: qb (<code>AllTattoos.json</code>), esx (<code>Config.TattooList</code>) und illenium-appearance. Neuere Versionen von illenium-appearance finden die Tattoos selbst in der Overlay-Datei, deshalb ist diese Liste standardmäßig aus.</li>","t_box":"Gib der Tattoo-Resource einen eigenen Namen. Das Programm verweigert den Build, wenn Tattoo- und Kleidungs-Resource im selben Ordner landen würden, denn dann würde der Build der einen die andere in den Papierkorb verschieben.","st_title":"Studio-Werkzeuge","st_sub":"Die Vorgänge arbeiten an einer Kopie des Modells im Projektordner. Jeder Vorgang lässt sich mit Ctrl+Z rückgängig machen, Dateien eingeschlossen. Schlägt ein Vorgang fehl, wird die Datei wieder in den vorherigen Zustand versetzt.","st_group":"Gruppe","st_tools":"Werkzeuge","st_g_weights":"Gewichte","st_r_weights":"Gewichte vom Körper kopieren · Gewichte glätten · Gewichte gültig machen · Nahtgewichte angleichen","st_g_fit":"Passform und Form","st_r_fit":"Aus dem Körper schieben · Aufblähen / schrumpfen · An Körper anpassen · An Körper anschmiegen · Saum über dem Boden · Links/rechts spiegeln · Ärmel ausrichten · Ärmel verjüngen · Verschieben / Drehen / Skalieren anwenden","st_g_mesh":"Mesh","st_r_mesh":"Normalen reparieren · Nähte verschweißen · Öffnungen schließen · Lücken schließen · Verdicken (innen) · Ganze Datei neu schreiben","st_g_lod":"Detailstufe","st_r_lod":"LODs erstellen · LODs gewichten · Dreiecke reduzieren","st_g_special":"Props, Haare, Absätze, Physik","st_r_special":"In Prop umwandeln · Alternatives Haar · Absatz-Pose · Absatz-Bones · Stoffphysik erstellen (.yld) · Stoffphysik neu binden · Ungenutzte Textur zuschneiden","st_g_shader":"Shader","st_r_shader":"27 Ped-Shader, jeweils mit einem Hinweis, wofür sie gedacht sind.","st_g_tex":"Texturen","st_r_tex":"+ Aus PNG (DXT1/DXT5 mit Mipmaps) · Umfärben → neue Variante · Aus PNG ersetzen · Als PNG exportieren · Normal- + Spec-Maps (PNG)","st_g_export":"Modell exportieren","st_r_export":"Sollumz / CodeWalker XML · .obj (Blender usw.)","p_intro":"Der Tab Build hat ein Kontrollkästchen <code>subdir_file_mapping</code>. Ist es aktiviert, bekommt die <code>fxmanifest.lua</code> der Kleidungs-Resource diese Zeile:","p_list":"<li><b>Standardmäßig ist es aus.</b> Mit der Zeile verweigert ein Server, der die Policy nicht hat, den Start der Resource komplett.</li><li><b>Ohne die Zeile</b> lädt ein Server ohne die Policy das Pack und zeigt keine Kleidung, ohne jede Meldung in der Konsole. Ein Server mit 10 Slots oder weniger bekommt die Policy automatisch; darüber gibt es sie mit einem Element Club Argentum-Abo (oder höher).</li><li><b>Aktiviere es</b>, wenn dein Server mehr als 10 Slots und die Policy hat, damit eine fehlende Policy als klarer Startfehler auffällt statt als unsichtbare Kleidung. Lass es auf einem Server mit 10 Slots oder weniger aus.</li><li>Der Build-Plan erinnert dich daran, wenn es aus ist. Ob die Zeile nötig ist, wurde im Spiel noch nicht nachgewiesen, also teste auf deinem eigenen Server.</li>","q1":"Ist es kostenlos?","a1":"Ja. Unlimited Cloth ist kostenlos und Open Source unter der MIT-Lizenz, entwickelt von Unlimited Reforge.","q2":"Brauche ich GTA V, Blender oder CodeWalker?","a2":"Nein. Das Programm liest und schreibt die Spielformate selbst, und die Freemode-Peds für die Vorschau sind enthalten. Im Tab Peds kannst du stattdessen Dateien aus deinem eigenen Spiel verwenden (optional).","q3":"Mit welchen Kleidungsmenüs funktioniert es?","a3":"Die Kleidungs-Resource ist ein normales Addon-Pack, also zeigt jedes Menü sie an, das Addon-Kleidung liest. Für Tattoos schreibt das Programm Listen für qb, esx und illenium-appearance. Prüfe die Feldnamen mit deiner Version des Menüs.","q4":"Verändert es meine Originaldateien?","a4":"Nein. Reparaturvorgänge arbeiten an einer Kopie im Projektordner, und alles, was im Weg ist (etwa ein alter Build), landet im Papierkorb. Nichts wird endgültig gelöscht.","q5":"Meine Kleidung wird im Spiel nicht angezeigt","a5":"<li>Prüfe, wie viele Slots der Server hat, und die <a href=\"#policy\">subdir_file_mapping</a>-Policy.</li><li>Stelle sicher, dass die Resource gestartet ist (<code>ensure</code>) und dass der Game Build des Servers der im Tab Build gewählte ist.</li><li>Nutze <b>Bestehendes Pack prüfen…</b> im Tab Build, um den Ordner wieder einzulesen.</li>","q6":"Warum warnt Windows vor einem unbekannten Herausgeber?","a6":"Der Installer ist mit dem eigenen Zertifikat von Unlimited Reforge signiert, nicht mit einem, das bei einer Zertifizierungsstelle gekauft wurde, deshalb kennt Windows den Herausgeber noch nicht. Unter <a href=\"#install\">Installation</a> steht, wie du an SmartScreen vorbeikommst.","q7":"Wo bekomme ich Hilfe?","a7":"Fragen, Bugs und Ideen gehören in den <a href=\"https://discord.gg/uaASPkghXu\" rel=\"noopener\">Unlimited Discord</a>. Das Programm hat keine E-Mail-Adresse.","ch_title":"Changelog","ch_first":"erstes Release","ch_list":"<li>Kleidungs-Pack-Builder: Import von .ydd/.ytd/.yld, ganzen Addon-Packs, .ydd.xml, .glb, .obj und .blend; Nummerierung, Prüfung der Grenzen, eine zweite Sammlung über 255, .zip.</li><li>Beim Neubau eines Packs bleiben Flags, Audio, Absätze, Prop-Haar, Haartausch und Sammlungsname erhalten.</li><li>Studio mit Reparaturvorgängen für Gewichte, Passform, Mesh, LODs, Props, Haare, Absätze und Stoffphysik, 27 Shader, Texturwerkzeuge und Export nach Sollumz/.obj; Rückgängig und Wiederholen für jeden Vorgang.</li><li>3D-Vorschau mit 31 Posen und Animationen und einer Clipping-Prüfung.</li><li>Tattoo-Builder mit Platzierung in 3D und UV, Overlay-XML, shop_tattoo.meta und Listen für qb, esx und illenium-appearance.</li><li>Jede gebaute Datei wird wieder eingelesen: Modelle (mit Round Trip), Texturen, .ymt (Komponenten und Props), Shop-Meta, eingebundene Datendateien und die eigenen Pack-Prüfungen der Engine.</li><li>Mitgelieferte Freemode-Peds; deine eigenen Spieldateien sind optional und ergänzen nur das, was du ihnen gibst.</li><li>Einrichtung beim ersten Start, 12 Sprachen, Autosave und Wiederherstellung nach Abstürzen.</li>","ch_known":"Bekannte Einschränkungen: Neu geschriebene .ydd-Dateien sind im Spiel bisher nur mit dem Test-Pack nachgewiesen, der Import aus einer GTA V-Installation ist ungetestet, und der Windows-Build ist neu. Teste zuerst auf einem Testserver.","dc_title":"Fragen? Komm in den Discord","dc_sub":"Support, Bug-Reports und Ideen für Unlimited Cloth und den Rest von Unlimited.","dc_btn":"Unlimited Discord öffnen","f_lic":"© 2026 Unlimited Reforge · MIT-Lizenz","f_rock":"Die mitgelieferten Freemode-Peds basieren auf Assets von Rockstar Games. Unlimited Reforge steht in keiner Verbindung zu Rockstar Games oder Cfx.re.","ss_btn":"Seite durchsuchen","ss_ph":"Seite durchsuchen…","ss_none":"Nichts gefunden. Versuch ein anderes Wort.","ss_more":"{n} weitere Treffer. Tippe mehr, um einzugrenzen.","ss_close":"Suche schließen"},"dk":{"meta_title":"Unlimited Cloth: tøj og tatoveringer til FiveM","meta_desc":"Unlimited Cloth er et gratis program til Windows og Linux, der gør GTA V freemode-tøj og tatoveringer klar til FiveM: pakkebygger, reparationsværktøjer i studiet, 3D-forhåndsvisning med animationer og en tatoveringsbygger.","langlabel":"Sprog","theme_light":"Skift til lys tilstand","theme_dark":"Skift til mørk tilstand","nav_more":"Mere","skip":"Spring til indholdet","nav_what":"Funktioner","nav_dl":"Download","nav_install":"Installation","nav_start":"Kom i gang","nav_clothes":"Tøj","nav_tattoos":"Tatoveringer","nav_studio":"Studio","nav_faq":"FAQ","nav_changelog":"Ændringslog","h_badge":"Gratis · MIT · Windows og Linux · version 1.0.0","h_title":"Tøj og tatoveringer til FiveM, klar til streaming","h_sub":"Unlimited Cloth gør GTA V freemode-tøj og tatoveringer klar til FiveM. Importér tøj eller hele addon-pakker, ret dem til i studiet, prøv dem på den animerede freemode-ped og byg en færdig ressource og .zip. Hver fil, programmet skriver, bliver læst igen og tjekket.","h_dl":"Download 1.0.0","h_start":"Kom i gang","h_note":"Ingen browserfane, ingen netværksport, og du skal hverken bruge Blender, Python eller CodeWalker. Lavet af Unlimited Reforge.","alt_studio":"Studio-fanen: den kvindelige freemode-ped i kort top og læderbukser med reparationsværktøjerne til højre","w_title":"Hvad det gør","w_sub":"Ét program til hele opgaven, fra løse filer til en ressource, du kan køre <code>ensure</code> på.","w1_t":"Tøjpakkebygger","w1_d":"Komponenter og props til <code>mp_m_freemode_01</code> og <code>mp_f_freemode_01</code>, nummereret for dig, tjekket mod spillets grænser og skrevet som <code>fxmanifest.lua</code>, <code>stream/</code>, <code>.ymt</code> og butiks-<code>.meta</code>, plus en .zip.","w2_t":"Reparationsværktøjer i studiet","w2_d":"Kopiér vægte fra kroppen, skub ud af kroppen, tilpas og krymp til kroppen, LOD'er, shadere, props, alternativt hår, hæle, stoffysik og teksturværktøjer. Alle opgaver kan fortrydes.","w3_t":"3D-forhåndsvisning og animationer","w3_d":"Freemode-peden med hud og dit tøj, 31 positurer og animationer, og <b>Vis clipping</b>, som markerer med rødt, hvor kroppen stikker igennem, hvor dybt og ved hvilken knogle.","w4_t":"Tatoveringsbygger","w4_d":"PNG ind, 512×512 DXT5 .ytd ud. Placér hver tatovering pr. zone og pr. krop i 3D eller i UV-feltet, og få overlay-XML og færdige lister til qb, esx og illenium-appearance.","w5_t":"Sikkert for dine filer","w5_d":"Reparationsopgaver arbejder på en kopi i projektmappen, så din original bliver aldrig ændret. Intet slettes for altid: et gammelt build flyttes til papirkurven.","w6_t":"Projekter og sprog","w6_d":"Almindelige JSON-projekter (<code>.ucloth</code>) med relative stier, der kan åbnes på både Windows og Linux, autogem til gendannelse efter nedbrud, fortryd og annullér fortryd. Programmet findes på 12 sprog.","c_clip":"Vis clipping i gå-animationen","c_tat":"En tatovering placeret i 3D","c_build":"Byg: planen og kontrollen, hvor alt læses igen","d_title":"Download","d_sub":"Version 1.0.0. Alle filer ligger på udgivelsessiden på GitHub sammen med udgivelsesnoterne.","d_win_d":"Installationsprogram: vælg en mappe, få genveje, afinstallér fra Apps.","d_deb_d":"Debian, Ubuntu, Mint, Pop!_OS og andre apt-systemer.","d_app_d":"Én fil, der kører på de fleste distributioner, uden installation.","d_all":"Alle udgivelser","d_note":"De freemode-peds, som forhåndsvisningen bruger, følger med programmet; intet andet skal downloades.","i_title":"Installation","i_win_steps":"<li>Kør <code>Unlimited-Cloth-Setup-1.0.0.exe</code>.</li><li>Vælg installationsmappen. Der oprettes genveje på skrivebordet og i menuen Start.</li><li>Afinstallér senere under Indstillinger → Apps.</li>","i_win_warn":"<b>»Windows beskyttede din pc« / ukendt udgiver.</b> Installationsprogrammet er signeret med Unlimited Reforges eget certifikat, som Windows endnu ikke kender, så Microsoft SmartScreen kan stoppe det første gang. Klik på <b>Flere oplysninger</b>, tjek at filen er den fra udgivelsessiden, og klik så på <b>Kør alligevel</b>.","i_deb":"<b>.deb</b> (Debian, Ubuntu og lignende):","i_app":"<b>AppImage</b>: gør filen eksekverbar, og kør den.","i_fuse":"Hvis AppImage-filen ikke starter på Ubuntu 22.04 eller nyere, så installér FUSE 2: <code>sudo apt install libfuse2</code> (<code>libfuse2t64</code> på 24.04).","i_where_t":"Hvor tingene gemmes","i_where_d":"Indstillinger, autogem og dine egne peds: <code>%APPDATA%\\Unlimited Cloth</code> på Windows, <code>~/.config/Unlimited Cloth</code> på Linux. Byggede ressourcer gemmes i <code>Documents/Unlimited Cloth/build</code>, medmindre du vælger en anden mappe.","s_title":"Kom i gang","s1_t":"Opsætning ved første start","s1_d":"Programmet starter på engelsk og fører dig gennem sprog, indstillinger, mapper, peds og standardværdierne for nye projekter. Du kan springe det over og køre det igen fra <b>?</b> → <b>Kør opsætning igen</b>.","s2_t":"Prøv med testindhold","s2_d":"Tryk på <b>Testtøj</b> på fanen Tøj. Du får en testtrøje til hver krop og en kasket til begge, lavet af programmet selv, så du kan prøve alle værktøjerne, før du bruger dine egne filer.","s3_t":"Importér dit tøj","s3_d":"<b>+ Importér filer</b> tager <code>.ydd</code>, <code>.ytd</code>, <code>.yld</code>, Sollumz/CodeWalker <code>.ydd.xml</code>, <code>.glb</code>, <code>.obj</code>, <code>.blend</code> og <code>.png</code>. <b>Mappe / pakke</b> tager en hel mappe eller en eksisterende addon-pakke.","s4_t":"Krop, plads og teksturer","s4_d":"Vælg for hvert stykke tøj kroppen (mand, kvinde eller begge), komponent- eller prop-pladsen og op til 26 teksturvarianter (a–z). Et <b>!</b> i listen betyder, at der stadig mangler noget.","s5_t":"Tjek, og byg så","s5_d":"På fanen Byg trykker du på <b>Tjek (plan)</b> for at se alle filer, numre og grænser, før noget bliver skrevet. Tryk derefter på <b>Byg alt</b>. Resultatet læses igen og tjekkes.","s6_t":"På serveren","s6_d":"Kopiér ressourcemapperne til <code>resources/</code>, og tilføj dem i <code>server.cfg</code>. Prøv en ny pakke på en testserver, før du lægger den på en live-server.","cl_title":"Tøjbygger","cl_sub":"Fanen Tøj indeholder listen; fanen Byg skriver ressourcen.","cl1_t":"Numre","cl1_l":"<li>Rækkefølgen i listen er nummeret: tomt betyder det næste ledige nummer på den plads.</li><li>Et fast nummer sørger for, at gemte outfits stadig peger på det samme stykke tøj. Hvis to stykker tøj beder om samme nummer, beholder det første det, og det andet får det næste ledige, og planen siger det.</li><li>Ud over 255 drawables af én slags kommer resten i en anden samling (<code>&lt;collection&gt;2</code>).</li><li>Et hul under det højeste nummer udfyldes med en usynlig dummy, fordi spillet læser fra 000 og opad.</li>","cl2_t":"Grænser, der tjekkes","cl2_l":"<li>255 drawables pr. plads og krop, 26 teksturer (a–z) pr. stykke tøj.</li><li>Streamingpladser til peds for serverens game build.</li><li>Butiksposter, længden af filnavne (under 128 bytes), navne med små bogstaver.</li><li>Tøj uden plads, krop eller tekstur er en fejl, og der gættes aldrig.</li>","cl3_t":"Hvad der skrives","cl3_d":"<code>fxmanifest.lua</code>, <code>stream/</code> med modellerne, teksturerne og stoffysikken, én <code>.ymt</code> og én butiks-<code>.meta</code> pr. krop, førstepersonsmodeller (<code>_1.ydd</code>), hårskift (<code>pedalternatevariations.meta</code>), hælhøjder og en <code>.zip</code> af mappen.","cl4_t":"Genopbyg en eksisterende pakke","cl4_d":"Importér en færdigbygget pakke med <b>Mappe / pakke</b> for at omdøbe dens samling eller slå pakker sammen. Flag, lydprofiler, hælhøjder, prop-hår, hårskift og samlingens navn hentes tilbage fra dens <code>.ymt</code>- og <code>.meta</code>-filer.","t_title":"Tatoveringer","t1_t":"Lav og placér","t1_l":"<li><b>+ Tatovering (PNG)</b>: hvert billede bliver til en 512×512 DXT5 <code>.ytd</code>. En færdig <code>.ytd</code> virker også; teksturen i den får tatoveringens Id i buildet.</li><li>Vælg kropszonen, og placér så tatoveringen hver for sig på den mandlige og den kvindelige krop: i 3D på peden eller i visningen <b>UV-felt</b> (træk for at flytte, musehjul for at ændre størrelse).</li><li>Id'et er hash-navnet. Når det er tomt, bruges filnavnet.</li>","t2_t":"Hvad der skrives","t2_l":"<li>Overlay-XML'en og <code>fxmanifest.lua</code> med <code>PED_OVERLAY_FILE</code>.</li><li>Valgfri <code>shop_tattoo.meta</code> (kun grundspillets tatoveringsbutik læser den).</li><li>Valgfrit: Menulister i <code>exports/</code>: qb (<code>AllTattoos.json</code>), esx (<code>Config.TattooList</code>) og illenium-appearance. Nyere versioner af illenium-appearance finder selv tatoveringerne i overlay-filen, så den liste er slået fra som standard.</li>","t_box":"Giv tatoveringsressourcen sit eget navn. Programmet nægter at bygge, hvis tatoverings- og tøjressourcen ville havne i samme mappe, fordi et build af den ene så ville flytte den anden til papirkurven.","st_title":"Studieværktøjer","st_sub":"Opgaverne arbejder på en kopi af modellen i projektmappen. Alle opgaver kan fortrydes med Ctrl+Z, også filerne. En opgave, der fejler, sætter filen tilbage, som den var.","st_group":"Gruppe","st_tools":"Værktøjer","st_g_weights":"Vægte","st_r_weights":"Kopiér vægte fra kroppen · Udglat vægte · Gør vægte gyldige · Synkronisér sømvægte","st_g_fit":"Tilpasning og form","st_r_fit":"Skub ud af kroppen · Pust op / tøm · Tilpas til kroppen · Krymp til kroppen · Kant over gulvet · Spejl venstre/højre · Justér ærmer · Gør ærmer smallere · Anvend flyt / drej / skalér","st_g_mesh":"Mesh","st_r_mesh":"Ret normaler · Svejs sømme · Luk åbninger · Luk huller · Giv tykkelse (inderside) · Omskriv hele filen","st_g_lod":"Detaljeniveau","st_r_lod":"Lav LOD'er · Vægt LOD'erne · Reducér trekanter","st_g_special":"Props, hår, hæle, fysik","st_r_special":"Lav om til prop · Alternativt hår · Hælpositur · Hælknogler · Lav stoffysik (.yld) · Bind stoffysik igen · Beskær ubrugt tekstur","st_g_shader":"Shader","st_r_shader":"27 ped-shadere med en note om, hvad hver enkelt bruges til.","st_g_tex":"Teksturer","st_r_tex":"+ Fra PNG (DXT1/DXT5 med mipmaps) · Farv om → ny variant · Erstat fra PNG · Eksportér som PNG · Normal- + spec-maps (PNG)","st_g_export":"Eksportér model","st_r_export":"Sollumz / CodeWalker XML · .obj (Blender osv.)","p_intro":"Fanen Byg har et afkrydsningsfelt til <code>subdir_file_mapping</code>. Når det er slået til, får tøjressourcens <code>fxmanifest.lua</code> denne linje:","p_list":"<li><b>Fra er standard.</b> Med linjen nægter en server, der ikke har politikken, overhovedet at starte ressourcen.</li><li><b>Uden linjen</b> indlæser en server, der mangler politikken, pakken og viser intet tøj, uden noget i konsollen. En server med 10 pladser eller færre får politikken automatisk; derover følger den med et Element Club Argentum-abonnement (eller højere).</li><li><b>Slå det til</b>, når din server har mere end 10 pladser og har politikken, så en manglende politik viser sig som en tydelig startfejl i stedet for usynligt tøj. Lad det være slået fra på en server med 10 pladser eller færre.</li><li>Byggeplanen minder dig om det, når det er slået fra. Det er endnu ikke bevist i spillet, om linjen er nødvendig, så test på din egen server.</li>","q1":"Er det gratis?","a1":"Ja. Unlimited Cloth er gratis og open source under MIT-licensen, lavet af Unlimited Reforge.","q2":"Skal jeg bruge GTA V, Blender eller CodeWalker?","a2":"Nej. Programmet læser og skriver selv spillets formater, og freemode-peds til forhåndsvisningen følger med. På fanen Peds kan du i stedet bruge filer fra dit eget spil (valgfrit).","q3":"Hvilke tøjmenuer virker det med?","a3":"Tøjressourcen er en almindelig addon-pakke, så enhver menu, der læser addon-tøj, viser den. Til tatoveringer skriver programmet lister til qb, esx og illenium-appearance. Tjek feltnavnene mod din version af menuen.","q4":"Ændrer det mine originale filer?","a4":"Nej. Reparationsopgaver arbejder på en kopi i projektmappen, og alt, der står i vejen (for eksempel et gammelt build), flyttes til papirkurven. Intet slettes for altid.","q5":"Mit tøj vises ikke i spillet","a5":"<li>Tjek, hvor mange pladser serveren har, og <a href=\"#policy\">subdir_file_mapping</a>-politikken.</li><li>Sørg for, at ressourcen er startet (<code>ensure</code>), og at serverens game build er det, der er valgt på fanen Byg.</li><li>Brug <b>Tjek en eksisterende pakke…</b> på fanen Byg til at læse mappen igen.</li>","q6":"Hvorfor advarer Windows om en ukendt udgiver?","a6":"Installationsprogrammet er signeret med Unlimited Reforges eget certifikat, ikke et købt hos en certifikatudsteder, så Windows kender endnu ikke udgiveren. Se <a href=\"#install\">Installation</a> for, hvordan du kommer forbi SmartScreen.","q7":"Hvor får jeg hjælp?","a7":"Spørgsmål, fejl og idéer hører hjemme på <a href=\"https://discord.gg/uaASPkghXu\" rel=\"noopener\">Unlimited Discord</a>. Programmet har ingen e-mailadresse.","ch_title":"Ændringslog","ch_first":"første udgivelse","ch_list":"<li>Tøjpakkebygger: import af .ydd/.ytd/.yld, hele addon-pakker, .ydd.xml, .glb, .obj og .blend; nummerering, tjek af grænser, en anden samling ud over 255, .zip.</li><li>Når en pakke genopbygges, bevares dens flag, lyd, hæle, prop-hår, hårskift og samlingsnavn.</li><li>Studio med reparationsopgaver til vægte, tilpasning, mesh, LOD'er, props, hår, hæle og stoffysik, 27 shadere, teksturværktøjer og eksport til Sollumz/.obj; fortryd og annullér fortryd for alle opgaver.</li><li>3D-forhåndsvisning med 31 positurer og animationer og et clipping-tjek.</li><li>Tatoveringsbygger med placering i 3D og UV, overlay-XML, shop_tattoo.meta og lister til qb, esx og illenium-appearance.</li><li>Hver bygget fil læses igen: modeller (med en rundtur), teksturer, .ymt (komponenter og props), butiks-meta, monterede datafiler og motorens egne pakketjek.</li><li>Medfølgende freemode-peds; dine egne spilfiler er valgfrie og udfylder kun det, du giver dem.</li><li>Opsætning ved første start, 12 sprog, autogem og gendannelse efter nedbrud.</li>","ch_known":"Kendte begrænsninger: nyskrevne .ydd-filer er kun bevist i spillet med testpakken, import fra en GTA V-installation er ikke testet, og Windows-versionen er ny. Test på en testserver først.","dc_title":"Spørgsmål? Kom med på Discord","dc_sub":"Support, fejlrapporter og idéer til Unlimited Cloth og resten af Unlimited.","dc_btn":"Åbn Unlimited Discord","f_lic":"© 2026 Unlimited Reforge · MIT-licens","f_rock":"De medfølgende freemode-peds er afledt af materiale fra Rockstar Games. Unlimited Reforge er ikke tilknyttet Rockstar Games eller Cfx.re.","ss_btn":"Søg på siden","ss_ph":"Søg på siden…","ss_none":"Intet fundet. Prøv et andet ord.","ss_more":"{n} resultater mere. Skriv mere for at indsnævre.","ss_close":"Luk søgning"},"es":{"meta_title":"Unlimited Cloth: creador de ropa y tatuajes para FiveM","meta_desc":"Unlimited Cloth es un programa de escritorio gratuito para Windows y Linux que prepara ropa y tatuajes freemode de GTA V para FiveM: creador de packs, herramientas de corrección en el estudio, vista previa 3D con animaciones y creador de tatuajes.","langlabel":"Idioma","theme_light":"Cambiar a modo claro","theme_dark":"Cambiar a modo oscuro","nav_more":"Más","skip":"Saltar al contenido","nav_what":"Funciones","nav_dl":"Descargar","nav_install":"Instalar","nav_start":"Primeros pasos","nav_clothes":"Ropa","nav_tattoos":"Tatuajes","nav_studio":"Estudio","nav_faq":"Preguntas frecuentes","nav_changelog":"Cambios","h_badge":"Gratis · MIT · Windows y Linux · versión 1.0.0","h_title":"Ropa y tatuajes para FiveM, listos para streaming","h_sub":"Unlimited Cloth prepara ropa y tatuajes freemode de GTA V para FiveM. Importa prendas o packs addon completos, corrígelas en el estudio, pruébalas en el ped freemode animado y genera un recurso terminado y un .zip. Cada archivo que escribe se vuelve a leer y se comprueba.","h_dl":"Descargar 1.0.0","h_start":"Primeros pasos","h_note":"Sin pestaña del navegador, sin puerto de red y sin necesidad de Blender, Python ni CodeWalker. Hecho por Unlimited Reforge.","alt_studio":"La pestaña Studio: el ped freemode femenino con top corto y pantalón de cuero, con las herramientas de corrección a la derecha","w_title":"Qué hace","w_sub":"Un solo programa para todo el trabajo, desde archivos sueltos hasta un recurso al que puedes hacer <code>ensure</code>.","w1_t":"Creador de packs de ropa","w1_d":"Componentes y props para <code>mp_m_freemode_01</code> y <code>mp_f_freemode_01</code>, numerados automáticamente, comprobados contra los límites del juego y escritos como <code>fxmanifest.lua</code>, <code>stream/</code>, <code>.ymt</code> y <code>.meta</code> de tienda, además de un .zip.","w2_t":"Herramientas de corrección del estudio","w2_d":"Copiar pesos del cuerpo, sacar la prenda del cuerpo, ajustar y shrinkwrap, LOD, shaders, props, pelo alternativo, tacones, física de tela y herramientas de texturas. Todo se puede deshacer.","w3_t":"Vista previa 3D y animaciones","w3_d":"El ped freemode con piel y tus prendas, 31 poses y animaciones, y <b>Mostrar clipping</b>, que marca en rojo dónde atraviesa el cuerpo la prenda, a qué profundidad y en qué hueso.","w4_t":"Creador de tatuajes","w4_d":"Entra un PNG, sale un .ytd DXT5 de 512×512. Coloca cada tatuaje por zona y por cuerpo en 3D o en el cuadro UV, y obtén el XML de overlays y listas listas para qb, esx e illenium-appearance.","w5_t":"Seguro con tus archivos","w5_d":"Las correcciones trabajan sobre una copia en la carpeta del proyecto, así que tu original nunca se modifica. Nunca se borra nada definitivamente: una compilación antigua va a la papelera del sistema.","w6_t":"Proyectos e idiomas","w6_d":"Proyectos en JSON simple (<code>.ucloth</code>) con rutas relativas que se abren tanto en Windows como en Linux, guardado automático para recuperarse de cierres inesperados, deshacer y rehacer. El programa está disponible en 12 idiomas.","c_clip":"Mostrar clipping en la animación de caminar","c_tat":"Un tatuaje colocado en 3D","c_build":"Compilar: el plan y la comprobación de relectura","d_title":"Descargar","d_sub":"Versión 1.0.0. Todos los archivos están en la página de la release en GitHub, junto con las notas de la versión.","d_win_d":"Instalador: elige una carpeta, crea accesos directos y se desinstala desde Aplicaciones.","d_deb_d":"Debian, Ubuntu, Mint, Pop!_OS y otros sistemas con apt.","d_app_d":"Un solo archivo que funciona en la mayoría de las distribuciones, sin instalación.","d_all":"Todas las versiones","d_note":"Los peds freemode que usa la vista previa vienen con el programa; no hace falta descargar nada más.","i_title":"Instalar","i_win_steps":"<li>Ejecuta <code>Unlimited-Cloth-Setup-1.0.0.exe</code>.</li><li>Elige la carpeta de instalación. Se crean accesos directos en el escritorio y en el menú Inicio.</li><li>Para desinstalarlo, ve a Configuración → Aplicaciones.</li>","i_win_warn":"<b>\"Windows protegió su PC\" / editor desconocido.</b> El instalador está firmado con el certificado propio de Unlimited Reforge, que Windows todavía no conoce, así que Microsoft SmartScreen puede bloquearlo la primera vez. Haz clic en <b>Más información</b>, comprueba que el archivo es el de la página de la release y luego haz clic en <b>Ejecutar de todas formas</b>.","i_deb":"<b>.deb</b> (Debian, Ubuntu y similares):","i_app":"<b>AppImage</b>: hazlo ejecutable y ábrelo.","i_fuse":"Si el AppImage no arranca en Ubuntu 22.04 o posterior, instala FUSE 2: <code>sudo apt install libfuse2</code> (<code>libfuse2t64</code> en 24.04).","i_where_t":"Dónde se guarda todo","i_where_d":"Ajustes, guardado automático y tus propios peds: <code>%APPDATA%\\Unlimited Cloth</code> en Windows, <code>~/.config/Unlimited Cloth</code> en Linux. Los recursos compilados van a <code>Documents/Unlimited Cloth/build</code> salvo que elijas otra carpeta.","s_title":"Primeros pasos","s1_t":"Configuración inicial","s1_d":"El programa arranca en inglés y te guía por el idioma, las preferencias, las carpetas, los peds y los valores por defecto para proyectos nuevos. Puedes saltarla y volver a ejecutarla desde <b>?</b> → <b>Repetir la configuración</b>.","s2_t":"Pruébalo con contenido de prueba","s2_d":"Pulsa <b>Prendas de prueba</b> en la pestaña Prendas. Obtienes una camiseta de prueba para cada cuerpo y una gorra para ambos, creadas por el propio programa, para que puedas probar todas las herramientas antes de usar tus propios archivos.","s3_t":"Importa tus prendas","s3_d":"<b>+ Importar archivos</b> admite <code>.ydd</code>, <code>.ytd</code>, <code>.yld</code>, <code>.ydd.xml</code> de Sollumz/CodeWalker, <code>.glb</code>, <code>.obj</code>, <code>.blend</code> y <code>.png</code>. <b>Carpeta / pack</b> admite una carpeta entera o un pack addon existente.","s4_t":"Cuerpo, slot y texturas","s4_d":"Para cada prenda elige el cuerpo (masculino, femenino o ambos), el slot de componente o de prop y hasta 26 variantes de textura (a–z). Un <b>!</b> en la lista significa que aún falta algo.","s5_t":"Comprueba y luego compila","s5_d":"En la pestaña Compilar pulsa <b>Comprobar (plan)</b> para ver cada archivo, número y límite antes de que se escriba nada. Después pulsa <b>Compilar todo</b>. El resultado se vuelve a leer y se comprueba.","s6_t":"En el servidor","s6_d":"Copia las carpetas de los recursos a <code>resources/</code> y añádelas a <code>server.cfg</code>. Prueba cada pack nuevo en un servidor de pruebas antes de ponerlo en uno en producción.","cl_title":"Creador de ropa","cl_sub":"La pestaña Prendas contiene la lista; la pestaña Compilar escribe el recurso.","cl1_t":"Números","cl1_l":"<li>El orden en la lista es el número: vacío significa el siguiente número libre en ese slot.</li><li>Un número fijo hace que los atuendos guardados sigan apuntando a la misma prenda. Si dos prendas piden el mismo número, la primera se lo queda y la otra recibe el siguiente libre, y el plan lo indica.</li><li>A partir de 255 drawables de un mismo tipo, el resto va a una segunda colección (<code>&lt;collection&gt;2</code>).</li><li>Un hueco por debajo del número más alto se rellena con un dummy invisible, porque el juego lee desde 000 hacia arriba.</li>","cl2_t":"Límites que comprueba","cl2_l":"<li>255 drawables por slot y cuerpo, 26 texturas (a–z) por prenda.</li><li>Slots de streaming de peds para la build del juego del servidor.</li><li>Entradas de tienda, longitud del nombre de archivo (menos de 128 bytes), nombres en minúsculas.</li><li>Una prenda sin slot, sin cuerpo o sin textura es un error y nunca se adivina.</li>","cl3_t":"Qué se escribe","cl3_d":"<code>fxmanifest.lua</code>, <code>stream/</code> con los modelos, las texturas y la física de tela, un <code>.ymt</code> y un <code>.meta</code> de tienda por cuerpo, modelos en primera persona (<code>_1.ydd</code>), cambios de pelo (<code>pedalternatevariations.meta</code>), alturas de tacón y un <code>.zip</code> de la carpeta.","cl4_t":"Recompilar un pack existente","cl4_d":"Importa un pack ya compilado con <b>Carpeta / pack</b> para cambiar el nombre de su colección o unir packs. Los flags, los perfiles de audio, las alturas de tacón, el pelo de los props, los cambios de pelo y el nombre de la colección se recuperan de sus archivos <code>.ymt</code> y <code>.meta</code>.","t_title":"Tatuajes","t1_t":"Crear y colocar","t1_l":"<li><b>+ Tatuaje (PNG)</b>: cada imagen se convierte en un <code>.ytd</code> DXT5 de 512×512. También sirve un <code>.ytd</code> ya hecho; la textura que contiene recibe el Id del tatuaje en la compilación.</li><li>Elige la zona del cuerpo y luego coloca el tatuaje por separado en el cuerpo masculino y en el femenino: en 3D sobre el ped o en el <b>Cuadro UV</b> (arrastra para mover, rueda del ratón para cambiar el tamaño).</li><li>El Id es el nombre del hash. Si está vacío, se usa el nombre del archivo.</li>","t2_t":"Qué se escribe","t2_l":"<li>El XML de overlays y <code>fxmanifest.lua</code> con <code>PED_OVERLAY_FILE</code>.</li><li><code>shop_tattoo.meta</code> opcional (solo lo lee la tienda de tatuajes del juego base).</li><li>Listas de menú opcionales en <code>exports/</code>: qb (<code>AllTattoos.json</code>), esx (<code>Config.TattooList</code>) e illenium-appearance. Las versiones más recientes de illenium-appearance encuentran los tatuajes en el archivo de overlays por sí solas, así que esa lista está desactivada por defecto.</li>","t_box":"Dale al recurso de tatuajes su propio nombre. El programa se niega a compilar si los recursos de tatuajes y de ropa fueran a acabar en la misma carpeta, porque compilar uno movería el otro a la papelera.","st_title":"Herramientas del estudio","st_sub":"Las tareas trabajan sobre una copia del modelo en la carpeta del proyecto. Todas se pueden deshacer con Ctrl+Z, archivos incluidos. Si una tarea falla, el archivo vuelve a quedar como estaba.","st_group":"Grupo","st_tools":"Herramientas","st_g_weights":"Pesos","st_r_weights":"Copiar pesos del cuerpo · Suavizar pesos · Legalizar pesos · Sincronizar pesos de costuras","st_g_fit":"Ajuste y forma","st_r_fit":"Sacar del cuerpo · Inflar / desinflar · Adaptar al cuerpo · Ajustar al cuerpo (shrinkwrap) · Dobladillo sobre el suelo · Reflejar izquierda/derecha · Alinear mangas · Estrechar mangas · Aplicar mover / rotar / escalar","st_g_mesh":"Malla","st_r_mesh":"Corregir normales · Soldar costuras · Cerrar aberturas · Cerrar huecos · Solidificar (interior) · Reescribir archivo entero","st_g_lod":"Nivel de detalle","st_r_lod":"Crear LOD · Pesar los LOD · Reducir triángulos","st_g_special":"Props, pelo, tacones, física","st_r_special":"Convertir en prop · Pelo alternativo · Pose de tacón · Huesos de tacón · Crear física de tela (.yld) · Revincular física de tela · Recortar textura no usada","st_g_shader":"Shader","st_r_shader":"27 shaders de ped, con una nota sobre para qué sirve cada uno.","st_g_tex":"Texturas","st_r_tex":"+ Desde PNG (DXT1/DXT5 con mipmaps) · Recolorear → nueva variante · Reemplazar desde PNG · Exportar como PNG · Mapas normal + spec (PNG)","st_g_export":"Exportar modelo","st_r_export":"XML de Sollumz / CodeWalker · .obj (Blender etc.)","p_intro":"La pestaña Compilar tiene una casilla <code>subdir_file_mapping</code>. Cuando está activada, el <code>fxmanifest.lua</code> del recurso de ropa recibe esta línea:","p_list":"<li><b>Desactivada por defecto.</b> Con la línea, un servidor que no tiene la policy se niega a iniciar el recurso.</li><li><b>Sin la línea</b>, un servidor al que le falta la policy carga el pack y no muestra ninguna ropa, sin nada en la consola. Un servidor con 10 slots o menos recibe la policy automáticamente; por encima de eso viene con una suscripción Element Club Argentum (o superior).</li><li><b>Actívala</b> cuando tu servidor tenga más de 10 slots y tenga la policy, para que una policy que falta aparezca como un error claro al iniciar en lugar de ropa invisible. Déjala desactivada en un servidor con 10 slots o menos.</li><li>El plan de compilación te lo recuerda cuando está desactivada. Todavía no se ha comprobado en el juego si la línea es necesaria, así que pruébalo en tu propio servidor.</li>","q1":"¿Es gratis?","a1":"Sí. Unlimited Cloth es gratuito y de código abierto bajo la licencia MIT, hecho por Unlimited Reforge.","q2":"¿Necesito GTA V, Blender o CodeWalker?","a2":"No. El programa lee y escribe los formatos del juego por sí mismo, y los peds freemode para la vista previa vienen incluidos. En la pestaña Peds puedes usar en su lugar archivos de tu propio juego (opcional).","q3":"¿Con qué menús de ropa funciona?","a3":"El recurso de ropa es un pack addon normal, así que cualquier menú que lea ropa addon la muestra. Para los tatuajes, el programa escribe listas para qb, esx e illenium-appearance. Comprueba los nombres de los campos con tu versión del menú.","q4":"¿Modificará mis archivos originales?","a4":"No. Las correcciones trabajan sobre una copia en la carpeta del proyecto, y todo lo que estorbe (una compilación antigua, por ejemplo) va a la papelera del sistema. Nunca se borra nada definitivamente.","q5":"Mi ropa no aparece en el juego","a5":"<li>Comprueba cuántos slots tiene el servidor y la policy <a href=\"#policy\">subdir_file_mapping</a>.</li><li>Asegúrate de que el recurso está iniciado (<code>ensure</code>) y de que la build del juego del servidor es la elegida en la pestaña Compilar.</li><li>Usa <b>Comprobar un pack existente…</b> en la pestaña Compilar para volver a leer la carpeta.</li>","q6":"¿Por qué Windows avisa de un editor desconocido?","a6":"El instalador está firmado con el certificado propio de Unlimited Reforge, no con uno comprado a una autoridad de certificación, así que Windows todavía no conoce al editor. Consulta <a href=\"#install\">Instalar</a> para saber cómo pasar SmartScreen.","q7":"¿Dónde consigo ayuda?","a7":"Las preguntas, los errores y las ideas van al <a href=\"https://discord.gg/uaASPkghXu\" rel=\"noopener\">Unlimited Discord</a>. El programa no tiene dirección de correo electrónico.","ch_title":"Cambios","ch_first":"primera versión","ch_list":"<li>Creador de packs de ropa: importación de .ydd/.ytd/.yld, packs addon completos, .ydd.xml, .glb, .obj y .blend; numeración, comprobación de límites, una segunda colección a partir de 255, .zip.</li><li>Al recompilar un pack se conservan sus flags, audio, tacones, pelo de props, cambios de pelo y nombre de colección.</li><li>Estudio con tareas de corrección para pesos, ajuste, malla, LOD, props, pelo, tacones y física de tela, 27 shaders, herramientas de texturas y exportación a Sollumz/.obj; deshacer y rehacer para cada tarea.</li><li>Vista previa 3D con 31 poses y animaciones y una comprobación de clipping.</li><li>Creador de tatuajes con colocación en 3D y UV, XML de overlays, shop_tattoo.meta y listas para qb, esx e illenium-appearance.</li><li>Cada archivo compilado se vuelve a leer: modelos (con ida y vuelta), texturas, .ymt (componentes y props), meta de tienda, archivos de datos montados y las propias comprobaciones de packs del motor.</li><li>Peds freemode incluidos; tus propios archivos del juego son opcionales y solo completan lo que tú les des.</li><li>Configuración inicial, 12 idiomas, guardado automático y recuperación tras cierres inesperados.</li>","ch_known":"Límites conocidos: los archivos .ydd recién escritos solo se han probado en el juego con el pack de prueba, la importación desde una instalación de GTA V no se ha probado y la build de Windows es nueva. Prueba primero en un servidor de pruebas.","dc_title":"¿Preguntas? Únete al Discord","dc_sub":"Soporte, informes de errores e ideas para Unlimited Cloth y el resto de Unlimited.","dc_btn":"Abrir el Unlimited Discord","f_lic":"© 2026 Unlimited Reforge · Licencia MIT","f_rock":"Los peds freemode incluidos derivan de recursos de Rockstar Games. Unlimited Reforge no está afiliado a Rockstar Games ni a Cfx.re.","ss_btn":"Buscar en la página","ss_ph":"Buscar en la página…","ss_none":"No se encontró nada. Prueba otra palabra.","ss_more":"{n} resultados más. Escribe más para afinar.","ss_close":"Cerrar búsqueda"},"et":{"meta_title":"Unlimited Cloth: FiveM-i riiete ja tätoveeringute looja","meta_desc":"Unlimited Cloth on tasuta töölauaprogramm Windowsile ja Linuxile, mis teeb GTA V freemode'i riided ja tätoveeringud FiveM-i jaoks valmis: pakkide ehitaja, stuudio parandustööriistad, 3D-eelvaade animatsioonidega ja tätoveeringute ehitaja.","langlabel":"Keel","theme_light":"Lülita heledale režiimile","theme_dark":"Lülita tumedale režiimile","nav_more":"Veel","skip":"Liigu sisu juurde","nav_what":"Võimalused","nav_dl":"Allalaadimine","nav_install":"Paigaldamine","nav_start":"Alustamine","nav_clothes":"Riided","nav_tattoos":"Tätoveeringud","nav_studio":"Stuudio","nav_faq":"KKK","nav_changelog":"Muudatuste logi","h_badge":"Tasuta · MIT · Windows ja Linux · versioon 1.0.0","h_title":"FiveM-i riided ja tätoveeringud, valmis streamimiseks","h_sub":"Unlimited Cloth teeb GTA V freemode'i riided ja tätoveeringud FiveM-i jaoks valmis. Impordi riideesemeid või terveid addon-pakke, paranda neid stuudios, proovi neid animeeritud freemode'i pedi seljas ja ehita valmis ressurss ning .zip. Iga kirjutatud fail loetakse tagasi ja kontrollitakse.","h_dl":"Laadi alla 1.0.0","h_start":"Alustamine","h_note":"Pole vaja brauserikaarti, võrguporti, Blenderit, Pythonit ega CodeWalkerit. Tegija: Unlimited Reforge.","alt_studio":"Studio vahekaart: naissoost freemode-ped lühikese topi ja nahkpükstega, parandustööriistad paremal","w_title":"Mida see teeb","w_sub":"Üks programm kogu töö jaoks, lahtistest failidest kuni ressursini, mida saad käivitada käsuga <code>ensure</code>.","w1_t":"Riidepakkide ehitaja","w1_d":"Komponendid ja propid mudelitele <code>mp_m_freemode_01</code> ja <code>mp_f_freemode_01</code>, sinu eest nummerdatud, mängu piirangute vastu kontrollitud ning kirjutatud failidena <code>fxmanifest.lua</code>, <code>stream/</code>, <code>.ymt</code> ja poe <code>.meta</code>, lisaks .zip.","w2_t":"Stuudio parandustööriistad","w2_d":"Kaalude kopeerimine kehalt, kehast välja lükkamine, sobitamine ja shrinkwrap, LOD-id, shaderid, propid, alternatiivsed juuksed, kontsad, riide füüsika ja tekstuuritööriistad. Iga toimingu saab tagasi võtta.","w3_t":"3D-eelvaade ja animatsioonid","w3_d":"Freemode'i ped naha ja sinu riideesemetega, 31 poosi ja animatsiooni ning <b>Näita läbitungimist</b>, mis märgib punasega, kust keha läbi tuleb, kui sügavalt ja millise luu juures.","w4_t":"Tätoveeringute ehitaja","w4_d":"Sisse PNG, välja 512×512 DXT5 .ytd. Paiguta iga tätoveering tsooni ja keha kaupa 3D-s või UV-ruudus ning saa overlay-XML ja valmis loendid qb, esx ja illenium-appearance jaoks.","w5_t":"Sinu failidega ohutu","w5_d":"Parandustoimingud töötavad koopiaga projektikaustas, nii et sinu originaal ei muutu kunagi. Midagi ei kustutata lõplikult: vana build läheb süsteemi prügikasti.","w6_t":"Projektid ja keeled","w6_d":"Lihtsad JSON-projektid (<code>.ucloth</code>) suhteliste radadega, mis avanevad nii Windowsis kui ka Linuxis, automaatne salvestamine krahhist taastumiseks, tagasivõtmine ja uuestitegemine. Programm räägib 12 keelt.","c_clip":"Näita läbitungimist kõnnianimatsioonis","c_tat":"3D-s paigutatud tätoveering","c_build":"Ehitus: plaan ja tagasilugemise kontroll","d_title":"Allalaadimine","d_sub":"Versioon 1.0.0. Kõik failid on GitHubi väljalaske lehel koos väljalaskemärkmetega.","d_win_d":"Paigaldaja: vali kaust, saa otseteed, eemalda rakenduste alt.","d_deb_d":"Debian, Ubuntu, Mint, Pop!_OS ja teised apt-iga süsteemid.","d_app_d":"Üks fail, mis töötab enamikus distributsioonides ilma paigaldamata.","d_all":"Kõik väljalasked","d_note":"Eelvaates kasutatavad freemode'i pedid tulevad programmiga kaasa; midagi muud pole vaja alla laadida.","i_title":"Paigaldamine","i_win_steps":"<li>Käivita <code>Unlimited-Cloth-Setup-1.0.0.exe</code>.</li><li>Vali paigalduskaust. Töölauale ja menüüsse Start luuakse otseteed.</li><li>Hiljem saad programmi eemaldada jaotises Sätted → Rakendused.</li>","i_win_warn":"<b>„Windows kaitses teie arvutit” / tundmatu väljaandja.</b> Paigaldaja on allkirjastatud Unlimited Reforge'i enda sertifikaadiga, mida Windows veel ei tunne, seega võib Microsoft SmartScreen selle esimesel korral peatada. Klõpsa <b>Lisateave</b>, kontrolli, et fail on väljalaske lehelt pärit, ja klõpsa siis <b>Käivita ikkagi</b>.","i_deb":"<b>.deb</b> (Debian, Ubuntu ja sarnased):","i_app":"<b>AppImage</b>: tee see käivitatavaks ja käivita.","i_fuse":"Kui AppImage ei käivitu Ubuntu 22.04 või uuema versiooniga, paigalda FUSE 2: <code>sudo apt install libfuse2</code> (24.04 puhul <code>libfuse2t64</code>).","i_where_t":"Kus asju hoitakse","i_where_d":"Seaded, automaatsalvestus ja sinu enda pedid: Windowsis <code>%APPDATA%\\Unlimited Cloth</code>, Linuxis <code>~/.config/Unlimited Cloth</code>. Ehitatud ressursid lähevad kausta <code>Documents/Unlimited Cloth/build</code>, kui sa ei vali teist kausta.","s_title":"Alustamine","s1_t":"Esmakäivituse seadistus","s1_d":"Programm käivitub inglise keeles ja juhatab sind läbi keele, eelistuste, kaustade, pedide ja uute projektide vaikeväärtuste. Võid selle vahele jätta ja hiljem uuesti käivitada: <b>?</b> → <b>Käivita seadistus uuesti</b>.","s2_t":"Proovi testsisuga","s2_d":"Vajuta vahekaardil Riideesemed nuppu <b>Testriided</b>. Saad testpluusi kummalegi kehale ja nokamütsi mõlemale, mille programm on ise teinud, nii et saad iga tööriista proovida enne oma failide kasutamist.","s3_t":"Impordi oma riideesemed","s3_d":"<b>+ Impordi failid</b> võtab vastu <code>.ydd</code>, <code>.ytd</code>, <code>.yld</code>, Sollumzi/CodeWalkeri <code>.ydd.xml</code>, <code>.glb</code>, <code>.obj</code>, <code>.blend</code> ja <code>.png</code> failid. <b>Kaust / pakk</b> võtab vastu terve kausta või olemasoleva addon-paki.","s4_t":"Keha, pesa ja tekstuurid","s4_d":"Vali iga riideeseme jaoks keha (mees, naine või mõlemad), komponendi või propi pesa ja kuni 26 tekstuurivarianti (a–z). <b>!</b> loendis tähendab, et midagi on veel puudu.","s5_t":"Kontrolli, siis ehita","s5_d":"Vajuta vahekaardil Ehitus nuppu <b>Kontrolli (plaan)</b>, et näha iga faili, numbrit ja piirangut enne, kui midagi kirjutatakse. Seejärel vajuta <b>Ehita kõik</b>. Tulemus loetakse tagasi ja kontrollitakse.","s6_t":"Serveris","s6_d":"Kopeeri ressursikaustad kausta <code>resources/</code> ja lisa need faili <code>server.cfg</code>. Proovi uut pakki enne testserveris, kui paned selle päris serverisse.","cl_title":"Riiete ehitaja","cl_sub":"Vahekaardil Riideesemed on loend; vahekaart Ehitus kirjutab ressursi.","cl1_t":"Numbrid","cl1_l":"<li>Järjekord loendis on number: tühi tähendab selle pesa järgmist vaba numbrit.</li><li>Fikseeritud number hoiab salvestatud riietused sama riideeseme küljes. Kui kaks riideeset küsivad sama numbrit, jääb see esimesele ja teine saab järgmise vaba numbri ning plaan ütleb seda.</li><li>Üle 255 sama liigi drawable'i lähevad ülejäänud teise kollektsiooni (<code>&lt;collection&gt;2</code>).</li><li>Tühimik kõrgeimast numbrist allpool täidetakse nähtamatu asendajaga, sest mäng loeb alates 000 ülespoole.</li>","cl2_t":"Kontrollitavad piirangud","cl2_l":"<li>255 drawable'it pesa ja keha kohta, 26 tekstuuri (a–z) riideeseme kohta.</li><li>Pedi streamingu pesad serveri mänguversiooni jaoks.</li><li>Poe kirjed, failinimede pikkus (alla 128 baidi), väiketähtedega nimed.</li><li>Pesa, keha või tekstuurita riideese on viga ja seda ei arvata kunagi.</li>","cl3_t":"Mida kirjutatakse","cl3_d":"<code>fxmanifest.lua</code>, <code>stream/</code> mudelite, tekstuuride ja riide füüsikaga, üks <code>.ymt</code> ja üks poe <code>.meta</code> keha kohta, esimese isiku mudelid (<code>_1.ydd</code>), juuste vahetused (<code>pedalternatevariations.meta</code>), kontsa kõrgused ja kausta <code>.zip</code>.","cl4_t":"Olemasoleva paki ümberehitamine","cl4_d":"Impordi ehitatud pakk nupuga <b>Kaust / pakk</b>, et nimetada selle kollektsioon ümber või ühendada pakke. Lipud, heliprofiilid, kontsa kõrgused, propi juuksed, juuste vahetused ja kollektsiooni nimi loetakse selle <code>.ymt</code> ja <code>.meta</code> failidest.","t_title":"Tätoveeringud","t1_t":"Loo ja paiguta","t1_l":"<li><b>+ Tätoveering (PNG)</b>: igast pildist saab 512×512 DXT5 <code>.ytd</code>. Sobib ka valmis <code>.ytd</code>; selles olev tekstuur saab buildis tätoveeringu Id.</li><li>Vali kehatsoon ja paiguta tätoveering eraldi mehe ja naise kehale: 3D-s pedil või vaates <b>UV-ruut</b> (lohista liigutamiseks, hiireratas suuruse muutmiseks).</li><li>Id on räsinimi. Kui see on tühi, kasutatakse failinime.</li>","t2_t":"Mida kirjutatakse","t2_l":"<li>Overlay-XML ja <code>fxmanifest.lua</code> koos <code>PED_OVERLAY_FILE</code>-iga.</li><li>Valikuliselt <code>shop_tattoo.meta</code> (seda loeb ainult põhimängu tätoveerimissalong).</li><li>Valikuliselt Menüüloendid kaustas <code>exports/</code>: qb (<code>AllTattoos.json</code>), esx (<code>Config.TattooList</code>) ja illenium-appearance. Uuemad illenium-appearance'i versioonid leiavad tätoveeringud overlay-failist ise, seega on see loend vaikimisi välja lülitatud.</li>","t_box":"Anna tätoveeringute ressursile oma nimi. Programm keeldub ehitamast, kui tätoveeringute ja riiete ressurss satuksid samasse kausta, sest ühe ehitamine viiks teise prügikasti.","st_title":"Stuudio tööriistad","st_sub":"Toimingud töötavad mudeli koopiaga projektikaustas. Iga toimingu saab tagasi võtta klahvidega Ctrl+Z, kaasa arvatud failid. Ebaõnnestunud toiming taastab faili endisel kujul.","st_group":"Rühm","st_tools":"Tööriistad","st_g_weights":"Kaalud","st_r_weights":"Kopeeri kaalud kehalt · Silu kaalud · Tee kaalud korrektseks · Sünkrooni õmbluste kaalud","st_g_fit":"Sobitus ja kuju","st_r_fit":"Lükka kehast välja · Paisuta / kahanda · Sobita kehale · Tõmba vastu keha (shrinkwrap) · Äär põrandast kõrgemale · Peegelda vasak/parem · Joonda varrukad · Ahenda varrukad · Rakenda liigutus / pööre / mõõtkava","st_g_mesh":"Võrgustik","st_r_mesh":"Paranda normaalid · Keevita õmblused · Sulge avad · Sulge vahed · Paksenda (sissepoole) · Kirjuta kogu fail ümber","st_g_lod":"Detailsuse tase","st_r_lod":"Loo LOD-id · Kaalu LOD-id · Vähenda kolmnurki","st_g_special":"Propid, juuksed, kontsad, füüsika","st_r_special":"Tee propiks · Alternatiivsed juuksed · Kontsa poos · Kontsa luud · Loo riide füüsika (.yld) · Seo riide füüsika uuesti · Kärbi kasutamata tekstuur","st_g_shader":"Shader","st_r_shader":"27 pedi shaderit, igaühel märkus, milleks see on mõeldud.","st_g_tex":"Tekstuurid","st_r_tex":"+ PNG-st (DXT1/DXT5 mipmapidega) · Värvi ümber → uus variant · Asenda PNG-st · Ekspordi PNG-na · Normal + spec kaardid (PNG)","st_g_export":"Ekspordi mudel","st_r_export":"Sollumz / CodeWalker XML · .obj (Blender jne)","p_intro":"Vahekaardil Ehitus on märkeruut <code>subdir_file_mapping</code>. Kui see on sees, saab riiete ressursi <code>fxmanifest.lua</code> selle rea:","p_list":"<li><b>Vaikimisi on see väljas.</b> Selle reaga keeldub server, millel seda policy't pole, ressurssi üldse käivitamast.</li><li><b>Ilma reata</b> laadib policy'ta server paki, kuid ei näita ühtegi riideeset ja konsoolis pole midagi. Server, millel on 10 kohta või vähem, saab policy automaatselt; sellest suuremad saavad selle Element Club Argentumi (või kõrgema) tellimusega.</li><li><b>Lülita see sisse</b>, kui sinu serveris on üle 10 koha ja policy on olemas, et puuduv policy ilmuks selge käivitusveana, mitte nähtamatute riietena. Jäta see välja serveris, kus on 10 kohta või vähem.</li><li>Buildi plaan tuletab meelde, kui see on väljas. Seda, kas rida on vajalik, pole mängus veel tõestatud, seega testi oma serveris.</li>","q1":"Kas see on tasuta?","a1":"Jah. Unlimited Cloth on tasuta ja avatud MIT-litsentsi all, tegija on Unlimited Reforge.","q2":"Kas mul on vaja GTA V-d, Blenderit või CodeWalkerit?","a2":"Ei. Programm loeb ja kirjutab mängu vorminguid ise ning eelvaate freemode'i pedid tulevad kaasa. Vahekaardil Pedid saad selle asemel kasutada oma mängu faile (valikuline).","q3":"Milliste riidemenüüdega see töötab?","a3":"Riiete ressurss on tavaline addon-pakk, nii et seda näitab iga menüü, mis loeb addon-riideid. Tätoveeringute jaoks kirjutab programm loendid qb, esx ja illenium-appearance jaoks. Kontrolli väljade nimesid oma menüü versiooniga.","q4":"Kas see muudab minu originaalfaile?","a4":"Ei. Parandustoimingud töötavad koopiaga projektikaustas ja kõik, mis ees on (näiteks vana build), läheb süsteemi prügikasti. Midagi ei kustutata lõplikult.","q5":"Minu riided ei ilmu mängus","a5":"<li>Kontrolli, mitu kohta serveris on, ja <a href=\"#policy\">subdir_file_mapping</a> policy't.</li><li>Veendu, et ressurss on käivitatud (<code>ensure</code>) ja et serveri mänguversioon on sama, mis on valitud vahekaardil Ehitus.</li><li>Kasuta vahekaardil Ehitus nuppu <b>Kontrolli olemasolevat paki…</b>, et kaust tagasi lugeda.</li>","q6":"Miks Windows hoiatab tundmatu väljaandja eest?","a6":"Paigaldaja on allkirjastatud Unlimited Reforge'i enda sertifikaadiga, mitte sertifitseerimiskeskuselt ostetud sertifikaadiga, seega ei tunne Windows väljaandjat veel. Vaata jaotisest <a href=\"#install\">Paigaldamine</a>, kuidas SmartScreenist mööda saada.","q7":"Kust ma abi saan?","a7":"Küsimused, vead ja ideed käivad <a href=\"https://discord.gg/uaASPkghXu\" rel=\"noopener\">Unlimited Discordi</a>. Programmil pole e-posti aadressi.","ch_title":"Muudatuste logi","ch_first":"esimene väljalase","ch_list":"<li>Riidepakkide ehitaja: .ydd/.ytd/.yld, tervete addon-pakkide, .ydd.xml, .glb, .obj ja .blend import; nummerdamine, piirangute kontroll, teine kollektsioon üle 255, .zip.</li><li>Paki ümberehitamisel säilivad selle lipud, heli, kontsad, propi juuksed, juuste vahetused ja kollektsiooni nimi.</li><li>Stuudio parandustoimingutega kaalude, sobituse, võrgustiku, LOD-ide, propide, juuste, kontsade ja riide füüsika jaoks, 27 shaderit, tekstuuritööriistad ja eksport Sollumzi/.obj vormingusse; iga toimingu tagasivõtmine ja uuestitegemine.</li><li>3D-eelvaade 31 poosi ja animatsiooniga ning läbitungimise kontrolliga.</li><li>Tätoveeringute ehitaja 3D- ja UV-paigutusega, overlay-XML, shop_tattoo.meta ja loendid qb, esx ja illenium-appearance jaoks.</li><li>Iga ehitatud fail loetakse tagasi: mudelid (edasi-tagasi teisendusega), tekstuurid, .ymt (komponendid ja propid), poe meta, ühendatud andmefailid ja mootori enda pakikontrollid.</li><li>Kaasas freemode'i pedid; sinu enda mängufailid on valikulised ja täidavad ainult seda, mida neile annad.</li><li>Esmakäivituse seadistus, 12 keelt, automaatsalvestus ja krahhist taastumine.</li>","ch_known":"Teadaolevad piirangud: uued kirjutatud .ydd failid on mängus tõestatud ainult testpakiga, importimine GTA V paigaldusest on testimata ja Windowsi versioon on uus. Testi kõigepealt testserveris.","dc_title":"Küsimusi? Liitu Discordiga","dc_sub":"Tugi, veateated ja ideed Unlimited Cloth'i ja ülejäänud Unlimitedi kohta.","dc_btn":"Ava Unlimited Discord","f_lic":"© 2026 Unlimited Reforge · MIT-litsents","f_rock":"Kaasasolevad freemode'i pedid põhinevad Rockstar Gamesi varadel. Unlimited Reforge ei ole seotud Rockstar Gamesi ega Cfx.re-ga.","ss_btn":"Otsi lehelt","ss_ph":"Otsi lehelt…","ss_none":"Midagi ei leitud. Proovi muud sõna.","ss_more":"Veel {n} tulemust. Kirjuta rohkem, et kitsendada.","ss_close":"Sulge otsing"},"nl":{"meta_title":"Unlimited Cloth: FiveM-kleding en -tattoos maken","meta_desc":"Unlimited Cloth is een gratis desktopprogramma voor Windows en Linux dat GTA V freemode-kleding en -tattoos klaarmaakt voor FiveM: packbouwer, studiotools om te repareren, 3D-voorbeeld met animaties en een tattoobouwer.","langlabel":"Taal","theme_light":"Lichte modus inschakelen","theme_dark":"Donkere modus inschakelen","nav_more":"Meer","skip":"Naar de inhoud","nav_what":"Functies","nav_dl":"Downloaden","nav_install":"Installeren","nav_start":"Aan de slag","nav_clothes":"Kleding","nav_tattoos":"Tattoos","nav_studio":"Studio","nav_faq":"FAQ","nav_changelog":"Wijzigingen","h_badge":"Gratis · MIT · Windows en Linux · versie 1.0.0","h_title":"FiveM-kleding en -tattoos, klaar om te streamen","h_sub":"Unlimited Cloth maakt GTA V freemode-kleding en -tattoos klaar voor FiveM. Importeer kledingstukken of complete addon-packs, repareer ze in de studio, pas ze aan op de geanimeerde freemode-ped en bouw een kant-en-klare resource en .zip. Elk bestand dat het programma schrijft, wordt opnieuw ingelezen en gecontroleerd.","h_dl":"Download 1.0.0","h_start":"Aan de slag","h_note":"Geen browsertabblad, geen netwerkpoort, geen Blender, Python of CodeWalker nodig. Gemaakt door Unlimited Reforge.","alt_studio":"Het tabblad Studio: de vrouwelijke freemode-ped in een croptop en leren broek, met de reparatietools rechts","w_title":"Wat het doet","w_sub":"Eén programma voor het hele werk, van losse bestanden tot een resource die je kunt <code>ensure</code>-en.","w1_t":"Kledingpackbouwer","w1_d":"Components en props voor <code>mp_m_freemode_01</code> en <code>mp_f_freemode_01</code>, automatisch genummerd, gecontroleerd op de limieten van de game en weggeschreven als <code>fxmanifest.lua</code>, <code>stream/</code>, <code>.ymt</code> en shop-<code>.meta</code>, plus een .zip.","w2_t":"Studiotools om te repareren","w2_d":"Gewichten van het lichaam kopiëren, uit het lichaam duwen, passen en shrinkwrap, LOD's, shaders, props, alternatief haar, hakken, stoffysica en textuurtools. Elke bewerking kan ongedaan worden gemaakt.","w3_t":"3D-voorbeeld en animaties","w3_d":"De freemode-ped met huid en jouw kledingstukken, 31 poses en animaties, en <b>Clipping tonen</b>, dat in rood laat zien waar het lichaam erdoorheen komt, hoe diep en bij welk bot.","w4_t":"Tattoobouwer","w4_d":"PNG erin, 512×512 DXT5 .ytd eruit. Plaats elke tattoo per zone en per lichaam in 3D of in het UV-vierkant, en krijg de overlay-XML en kant-en-klare lijsten voor qb, esx en illenium-appearance.","w5_t":"Veilig met je bestanden","w5_d":"Reparaties werken op een kopie in de projectmap, dus je origineel wordt nooit gewijzigd. Er wordt nooit iets definitief verwijderd: een oude build gaat naar de prullenbak van het systeem.","w6_t":"Projecten en talen","w6_d":"Gewone JSON-projecten (<code>.ucloth</code>) met relatieve paden die zowel op Windows als op Linux openen, automatisch opslaan voor herstel na een crash, ongedaan maken en opnieuw uitvoeren. Het programma is beschikbaar in 12 talen.","c_clip":"Clipping tonen in de loopanimatie","c_tat":"Een tattoo geplaatst in 3D","c_build":"Bouwen: het plan en de controle na het inlezen","d_title":"Downloaden","d_sub":"Versie 1.0.0. Alle bestanden staan op de releasepagina op GitHub, samen met de release notes.","d_win_d":"Installatieprogramma: kies een map, krijg snelkoppelingen, verwijder via Apps.","d_deb_d":"Debian, Ubuntu, Mint, Pop!_OS en andere systemen met apt.","d_app_d":"Eén bestand dat op de meeste distributies draait, zonder installatie.","d_all":"Alle releases","d_note":"De freemode-peds die het voorbeeld gebruikt, worden met het programma meegeleverd; je hoeft verder niets te downloaden.","i_title":"Installeren","i_win_steps":"<li>Start <code>Unlimited-Cloth-Setup-1.0.0.exe</code>.</li><li>Kies de installatiemap. Er worden snelkoppelingen op het bureaublad en in het Startmenu gemaakt.</li><li>Later verwijderen doe je via Instellingen → Apps.</li>","i_win_warn":"<b>\"Windows heeft uw pc beveiligd\" / onbekende uitgever.</b> Het installatieprogramma is ondertekend met het eigen certificaat van Unlimited Reforge, dat Windows nog niet kent, dus Microsoft SmartScreen kan het de eerste keer tegenhouden. Klik op <b>Meer informatie</b>, controleer of het bestand het bestand van de releasepagina is en klik dan op <b>Toch uitvoeren</b>.","i_deb":"<b>.deb</b> (Debian, Ubuntu en vergelijkbaar):","i_app":"<b>AppImage</b>: maak het uitvoerbaar en start het.","i_fuse":"Als de AppImage niet start op Ubuntu 22.04 of nieuwer, installeer dan FUSE 2: <code>sudo apt install libfuse2</code> (<code>libfuse2t64</code> op 24.04).","i_where_t":"Waar alles wordt bewaard","i_where_d":"Instellingen, automatisch opgeslagen bestanden en je eigen peds: <code>%APPDATA%\\Unlimited Cloth</code> op Windows, <code>~/.config/Unlimited Cloth</code> op Linux. Gebouwde resources komen in <code>Documents/Unlimited Cloth/build</code>, tenzij je een andere map kiest.","s_title":"Aan de slag","s1_t":"Eerste installatie","s1_d":"Het programma start in het Engels en leidt je door taal, voorkeuren, mappen, peds en de standaardinstellingen voor nieuwe projecten. Je kunt dit overslaan en later opnieuw starten via <b>?</b> → <b>Installatie opnieuw uitvoeren</b>.","s2_t":"Probeer het met testinhoud","s2_d":"Klik op <b>Testkleding</b> op het tabblad Kleding. Je krijgt een testshirt voor elk lichaam en een pet voor beide, door het programma zelf gemaakt, zodat je elke tool kunt proberen voordat je je eigen bestanden gebruikt.","s3_t":"Importeer je kledingstukken","s3_d":"<b>+ Bestanden importeren</b> accepteert <code>.ydd</code>, <code>.ytd</code>, <code>.yld</code>, Sollumz/CodeWalker <code>.ydd.xml</code>, <code>.glb</code>, <code>.obj</code>, <code>.blend</code> en <code>.png</code>. <b>Map / pack</b> accepteert een hele map of een bestaand addon-pack.","s4_t":"Lichaam, slot en texturen","s4_d":"Kies voor elk kledingstuk het lichaam (man, vrouw of beide), het component- of prop-slot en maximaal 26 textuurvarianten (a–z). Een <b>!</b> in de lijst betekent dat er nog iets ontbreekt.","s5_t":"Eerst controleren, dan bouwen","s5_d":"Klik op het tabblad Bouwen op <b>Controleren (plan)</b> om elk bestand, elk nummer en elke limiet te zien voordat er iets wordt geschreven. Klik daarna op <b>Alles bouwen</b>. Het resultaat wordt opnieuw ingelezen en gecontroleerd.","s6_t":"Op de server","s6_d":"Kopieer de resourcemappen naar <code>resources/</code> en voeg ze toe aan <code>server.cfg</code>. Probeer een nieuw pack op een testserver voordat je het op een live server zet.","cl_title":"Kledingbouwer","cl_sub":"Het tabblad Kleding bevat de lijst; het tabblad Bouwen schrijft de resource.","cl1_t":"Nummers","cl1_l":"<li>De volgorde in de lijst is het nummer: leeg betekent het volgende vrije nummer in dat slot.</li><li>Met een vast nummer blijven opgeslagen outfits naar hetzelfde kledingstuk wijzen. Als twee kledingstukken hetzelfde nummer vragen, houdt het eerste het en krijgt het andere het volgende vrije nummer, en dat staat in het plan.</li><li>Boven 255 drawables van één soort gaat de rest naar een tweede collectie (<code>&lt;collection&gt;2</code>).</li><li>Een gat onder het hoogste nummer wordt opgevuld met een onzichtbare dummy, omdat de game vanaf 000 omhoog leest.</li>","cl2_t":"Limieten die het controleert","cl2_l":"<li>255 drawables per slot en lichaam, 26 texturen (a–z) per kledingstuk.</li><li>Ped-streamingslots voor de gamebuild van de server.</li><li>Shopvermeldingen, lengte van bestandsnamen (onder 128 bytes), namen in kleine letters.</li><li>Een kledingstuk zonder slot, lichaam of textuur is een fout en wordt nooit geraden.</li>","cl3_t":"Wat er wordt geschreven","cl3_d":"<code>fxmanifest.lua</code>, <code>stream/</code> met de modellen, texturen en stoffysica, één <code>.ymt</code> en één shop-<code>.meta</code> per lichaam, first-person-modellen (<code>_1.ydd</code>), haarwissels (<code>pedalternatevariations.meta</code>), hakhoogtes en een <code>.zip</code> van de map.","cl4_t":"Een bestaand pack opnieuw bouwen","cl4_d":"Importeer een gebouwd pack met <b>Map / pack</b> om de collectie te hernoemen of packs samen te voegen. Flags, audioprofielen, hakhoogtes, prop-haar, haarwissels en de collectienaam worden uit de <code>.ymt</code>- en <code>.meta</code>-bestanden gehaald.","t_title":"Tattoos","t1_t":"Maken en plaatsen","t1_l":"<li><b>+ Tattoo (PNG)</b>: elke afbeelding wordt een 512×512 DXT5 <code>.ytd</code>. Een kant-en-klare <code>.ytd</code> werkt ook; de textuur erin krijgt in de build het Id van de tattoo.</li><li>Kies de lichaamszone en plaats de tattoo dan apart op het mannelijke en het vrouwelijke lichaam: in 3D op de ped, of in het <b>UV-vierkant</b> (slepen om te verplaatsen, muiswiel om de grootte te wijzigen).</li><li>Het Id is de hashnaam. Als het leeg is, wordt de bestandsnaam gebruikt.</li>","t2_t":"Wat er wordt geschreven","t2_l":"<li>De overlay-XML en <code>fxmanifest.lua</code> met <code>PED_OVERLAY_FILE</code>.</li><li>Optioneel <code>shop_tattoo.meta</code> (alleen de tattooshop van de basisgame leest dit).</li><li>Optioneel Menulijsten in <code>exports/</code>: qb (<code>AllTattoos.json</code>), esx (<code>Config.TattooList</code>) en illenium-appearance. Nieuwere versies van illenium-appearance vinden de tattoos zelf in het overlaybestand, dus die lijst staat standaard uit.</li>","t_box":"Geef de tattoo-resource een eigen naam. Het programma weigert te bouwen als de tattoo- en kledingresource in dezelfde map zouden komen, omdat het bouwen van de ene de andere naar de prullenbak zou verplaatsen.","st_title":"Studiotools","st_sub":"Bewerkingen werken op een kopie van het model in de projectmap. Elke bewerking kan met Ctrl+Z ongedaan worden gemaakt, inclusief bestanden. Een bewerking die mislukt, zet het bestand terug zoals het was.","st_group":"Groep","st_tools":"Tools","st_g_weights":"Gewichten","st_r_weights":"Gewichten van lichaam kopiëren · Gewichten gladstrijken · Gewichten geldig maken · Naadgewichten gelijktrekken","st_g_fit":"Pasvorm en vorm","st_r_fit":"Uit het lichaam duwen · Opblazen / laten slinken · Aan lichaam aanpassen · Strak om lichaam trekken · Zoom boven de vloer · Links/rechts spiegelen · Mouwen uitlijnen · Mouwen versmallen · Verplaatsen / draaien / schalen toepassen","st_g_mesh":"Mesh","st_r_mesh":"Normals herstellen · Naden lassen · Openingen dichten · Gaten dichten · Verdikken (binnenkant) · Hele bestand herschrijven","st_g_lod":"Detailniveau","st_r_lod":"LOD's maken · LOD's wegen · Driehoeken verminderen","st_g_special":"Props, haar, hakken, fysica","st_r_special":"Omzetten naar prop · Alternatief haar · Hak-pose · Hak-bones · Stoffysica maken (.yld) · Stoffysica opnieuw binden · Ongebruikte textuur bijsnijden","st_g_shader":"Shader","st_r_shader":"27 ped-shaders, elk met een korte uitleg waarvoor hij dient.","st_g_tex":"Texturen","st_r_tex":"+ Uit PNG (DXT1/DXT5 met mipmaps) · Herkleuren → nieuwe variant · Vervangen uit PNG · Exporteren als PNG · Normal- + spec-maps (PNG)","st_g_export":"Model exporteren","st_r_export":"Sollumz / CodeWalker XML · .obj (Blender enz.)","p_intro":"Het tabblad Bouwen heeft een selectievakje <code>subdir_file_mapping</code>. Als het aan staat, krijgt de <code>fxmanifest.lua</code> van de kledingresource deze regel:","p_list":"<li><b>Standaard staat het uit.</b> Met de regel weigert een server zonder de policy de resource helemaal te starten.</li><li><b>Zonder de regel</b> laadt een server zonder de policy het pack wel, maar toont hij geen kleding, en staat er niets in de console. Een server met 10 slots of minder krijgt de policy automatisch; daarboven krijg je hem bij een abonnement op Element Club Argentum (of hoger).</li><li><b>Zet het aan</b> als je server meer dan 10 slots heeft en de policy heeft, zodat een ontbrekende policy als duidelijke startfout verschijnt in plaats van als onzichtbare kleding. Laat het uit op een server met 10 slots of minder.</li><li>Het buildplan herinnert je eraan als het uit staat. Of de regel nodig is, is nog niet in de game bewezen, dus test het op je eigen server.</li>","q1":"Is het gratis?","a1":"Ja. Unlimited Cloth is gratis en open source onder de MIT-licentie, gemaakt door Unlimited Reforge.","q2":"Heb ik GTA V, Blender of CodeWalker nodig?","a2":"Nee. Het programma leest en schrijft de gameformaten zelf, en de freemode-peds voor het voorbeeld worden meegeleverd. Op het tabblad Peds kun je in plaats daarvan bestanden uit je eigen game gebruiken (optioneel).","q3":"Met welke kledingmenu's werkt het?","a3":"De kledingresource is een normaal addon-pack, dus elk menu dat addon-kleding leest, toont het. Voor tattoos schrijft het programma lijsten voor qb, esx en illenium-appearance. Controleer de veldnamen tegen jouw versie van het menu.","q4":"Verandert het mijn originele bestanden?","a4":"Nee. Reparaties werken op een kopie in de projectmap, en alles wat in de weg staat (bijvoorbeeld een oude build) gaat naar de prullenbak van het systeem. Er wordt niets definitief verwijderd.","q5":"Mijn kleding verschijnt niet in de game","a5":"<li>Controleer hoeveel slots de server heeft en de <a href=\"#policy\">subdir_file_mapping</a>-policy.</li><li>Zorg dat de resource gestart is (<code>ensure</code>) en dat de gamebuild van de server dezelfde is als die op het tabblad Bouwen is gekozen.</li><li>Gebruik <b>Bestaand pack controleren…</b> op het tabblad Bouwen om de map opnieuw in te lezen.</li>","q6":"Waarom waarschuwt Windows voor een onbekende uitgever?","a6":"Het installatieprogramma is ondertekend met het eigen certificaat van Unlimited Reforge, niet met een certificaat dat bij een certificeringsinstantie is gekocht, dus Windows kent de uitgever nog niet. Zie <a href=\"#install\">Installeren</a> voor hoe je langs SmartScreen komt.","q7":"Waar krijg ik hulp?","a7":"Vragen, bugs en ideeën kun je kwijt in de <a href=\"https://discord.gg/uaASPkghXu\" rel=\"noopener\">Unlimited Discord</a>. Het programma heeft geen e-mailadres.","ch_title":"Wijzigingen","ch_first":"eerste release","ch_list":"<li>Kledingpackbouwer: import van .ydd/.ytd/.yld, complete addon-packs, .ydd.xml, .glb, .obj en .blend; nummering, limietcontroles, een tweede collectie boven 255, .zip.</li><li>Bij het opnieuw bouwen van een pack blijven flags, audio, hakken, prop-haar, haarwissels en de collectienaam behouden.</li><li>Studio met reparaties voor gewichten, pasvorm, mesh, LOD's, props, haar, hakken en stoffysica, 27 shaders, textuurtools en export naar Sollumz/.obj; ongedaan maken en opnieuw uitvoeren voor elke bewerking.</li><li>3D-voorbeeld met 31 poses en animaties en een clippingcontrole.</li><li>Tattoobouwer met plaatsing in 3D en UV, overlay-XML, shop_tattoo.meta en lijsten voor qb, esx en illenium-appearance.</li><li>Elk gebouwd bestand wordt opnieuw ingelezen: modellen (met een round trip), texturen, .ymt (components en props), shop-meta, gekoppelde databestanden en de eigen packcontroles van de engine.</li><li>Meegeleverde freemode-peds; je eigen gamebestanden zijn optioneel en vullen alleen aan wat je ze geeft.</li><li>Eerste installatie, 12 talen, automatisch opslaan en herstel na een crash.</li>","ch_known":"Bekende beperkingen: nieuw geschreven .ydd-bestanden zijn alleen met het testpack in de game bewezen, importeren vanuit een GTA V-installatie is niet getest, en de Windows-build is nieuw. Test eerst op een testserver.","dc_title":"Vragen? Kom naar de Discord","dc_sub":"Ondersteuning, bugmeldingen en ideeën voor Unlimited Cloth en de rest van Unlimited.","dc_btn":"Open de Unlimited Discord","f_lic":"© 2026 Unlimited Reforge · MIT-licentie","f_rock":"De meegeleverde freemode-peds zijn afgeleid van assets van Rockstar Games. Unlimited Reforge is niet verbonden aan Rockstar Games of Cfx.re.","ss_btn":"Zoeken op de site","ss_ph":"Zoeken op de site…","ss_none":"Niets gevonden. Probeer een ander woord.","ss_more":"Nog {n} resultaten. Typ meer om te verfijnen.","ss_close":"Zoeken sluiten"},"pl":{"meta_title":"Unlimited Cloth: kreator ubrań i tatuaży do FiveM","meta_desc":"Unlimited Cloth to darmowy program na Windows i Linux, który przygotowuje ubrania i tatuaże freemode z GTA V do FiveM: kreator paczek, narzędzia naprawcze w studiu, podgląd 3D z animacjami i kreator tatuaży.","langlabel":"Język","theme_light":"Włącz tryb jasny","theme_dark":"Włącz tryb ciemny","nav_more":"Więcej","skip":"Przejdź do treści","nav_what":"Funkcje","nav_dl":"Pobierz","nav_install":"Instalacja","nav_start":"Pierwsze kroki","nav_clothes":"Ubrania","nav_tattoos":"Tatuaże","nav_studio":"Studio","nav_faq":"FAQ","nav_changelog":"Lista zmian","h_badge":"Za darmo · MIT · Windows i Linux · wersja 1.0.0","h_title":"Ubrania i tatuaże do FiveM, gotowe do streamowania","h_sub":"Unlimited Cloth przygotowuje ubrania i tatuaże freemode z GTA V do FiveM. Zaimportuj ubrania lub całe paczki addon, popraw je w studiu, przymierz na animowanym pedzie freemode i zbuduj gotowy zasób oraz plik .zip. Każdy zapisany plik jest ponownie wczytywany i sprawdzany.","h_dl":"Pobierz 1.0.0","h_start":"Pierwsze kroki","h_note":"Bez karty przeglądarki, bez portu sieciowego, bez Blendera, Pythona i CodeWalkera. Stworzone przez Unlimited Reforge.","alt_studio":"Karta Studio: kobiecy ped freemode w krótkim topie i skórzanych spodniach, z narzędziami naprawczymi po prawej","w_title":"Co potrafi","w_sub":"Jeden program do całej pracy, od luźnych plików po zasób, który możesz uruchomić przez <code>ensure</code>.","w1_t":"Kreator paczek ubrań","w1_d":"Komponenty i propy dla <code>mp_m_freemode_01</code> i <code>mp_f_freemode_01</code>, numerowane automatycznie, sprawdzane pod kątem limitów gry i zapisywane jako <code>fxmanifest.lua</code>, <code>stream/</code>, <code>.ymt</code> i sklepowy <code>.meta</code>, plus plik .zip.","w2_t":"Narzędzia naprawcze w studiu","w2_d":"Kopiowanie wag z ciała, wypychanie z ciała, dopasowanie i shrinkwrap, LOD, shadery, propy, alternatywne włosy, obcasy, fizyka materiału i narzędzia do tekstur. Każdą operację można cofnąć.","w3_t":"Podgląd 3D i animacje","w3_d":"Ped freemode ze skórą i Twoimi ubraniami, 31 póz i animacji oraz funkcja <b>Pokaż przenikanie</b>, która zaznacza na czerwono, gdzie ciało przebija przez ubranie, jak głęboko i przy której kości.","w4_t":"Kreator tatuaży","w4_d":"Na wejściu PNG, na wyjściu .ytd 512×512 DXT5. Umieść każdy tatuaż osobno dla każdej strefy i każdego ciała, w 3D albo w kwadracie UV, i otrzymaj overlay XML oraz gotowe listy dla qb, esx i illenium-appearance.","w5_t":"Bezpieczny dla Twoich plików","w5_d":"Operacje naprawcze działają na kopii w folderze projektu, więc oryginał nigdy się nie zmienia. Nic nie jest usuwane na stałe: stary build trafia do systemowego kosza.","w6_t":"Projekty i języki","w6_d":"Zwykłe projekty JSON (<code>.ucloth</code>) ze ścieżkami względnymi, które otwierają się zarówno na Windows, jak i na Linuksie, autozapis na wypadek awarii, cofanie i ponawianie. Program jest dostępny w 12 językach.","c_clip":"Pokaż przenikanie w animacji chodu","c_tat":"Tatuaż umieszczony w 3D","c_build":"Budowanie: plan i kontrola po ponownym wczytaniu","d_title":"Pobierz","d_sub":"Wersja 1.0.0. Wszystkie pliki znajdziesz na stronie wydania na GitHubie, razem z informacjami o wydaniu.","d_win_d":"Instalator: wybierz folder, dostaniesz skróty, odinstalujesz w Aplikacjach.","d_deb_d":"Debian, Ubuntu, Mint, Pop!_OS i inne systemy z apt.","d_app_d":"Jeden plik, który działa na większości dystrybucji, bez instalacji.","d_all":"Wszystkie wydania","d_note":"Pedy freemode używane w podglądzie są dołączone do programu; nic więcej nie trzeba pobierać.","i_title":"Instalacja","i_win_steps":"<li>Uruchom <code>Unlimited-Cloth-Setup-1.0.0.exe</code>.</li><li>Wybierz folder instalacji. Zostaną utworzone skróty na pulpicie i w menu Start.</li><li>Później odinstalujesz program w Ustawienia → Aplikacje.</li>","i_win_warn":"<b>„System Windows ochronił ten komputer” / nieznany wydawca.</b> Instalator jest podpisany własnym certyfikatem Unlimited Reforge, którego Windows jeszcze nie zna, więc Microsoft SmartScreen może go zatrzymać przy pierwszym uruchomieniu. Kliknij <b>Więcej informacji</b>, sprawdź, czy plik pochodzi ze strony wydania, a potem kliknij <b>Uruchom mimo to</b>.","i_deb":"<b>.deb</b> (Debian, Ubuntu i podobne):","i_app":"<b>AppImage</b>: nadaj plikowi prawo do wykonywania i uruchom go.","i_fuse":"Jeśli AppImage nie uruchamia się na Ubuntu 22.04 lub nowszym, zainstaluj FUSE 2: <code>sudo apt install libfuse2</code> (<code>libfuse2t64</code> na 24.04).","i_where_t":"Gdzie są przechowywane dane","i_where_d":"Ustawienia, autozapis i Twoje własne pedy: <code>%APPDATA%\\Unlimited Cloth</code> na Windows, <code>~/.config/Unlimited Cloth</code> na Linuksie. Zbudowane zasoby trafiają do <code>Documents/Unlimited Cloth/build</code>, chyba że wybierzesz inny folder.","s_title":"Pierwsze kroki","s1_t":"Konfiguracja przy pierwszym uruchomieniu","s1_d":"Program startuje po angielsku i prowadzi Cię przez wybór języka, preferencje, foldery, pedy i ustawienia domyślne nowych projektów. Możesz to pominąć i uruchomić ponownie przez <b>?</b> → <b>Uruchom konfigurację ponownie</b>.","s2_t":"Wypróbuj na zawartości testowej","s2_d":"Kliknij <b>Ubrania testowe</b> na karcie Ubrania. Dostaniesz testową koszulkę dla każdego ciała i czapkę dla obu, stworzone przez sam program, więc możesz wypróbować każde narzędzie, zanim użyjesz własnych plików.","s3_t":"Zaimportuj swoje ubrania","s3_d":"<b>+ Importuj pliki</b> przyjmuje <code>.ydd</code>, <code>.ytd</code>, <code>.yld</code>, <code>.ydd.xml</code> z Sollumz/CodeWalkera, <code>.glb</code>, <code>.obj</code>, <code>.blend</code> i <code>.png</code>. <b>Folder / paczka</b> przyjmuje cały folder lub istniejącą paczkę addon.","s4_t":"Ciało, slot i tekstury","s4_d":"Dla każdego ubrania wybierz ciało (męskie, żeńskie lub oba), slot komponentu lub propa i do 26 wariantów tekstur (a–z). <b>!</b> na liście oznacza, że czegoś jeszcze brakuje.","s5_t":"Najpierw sprawdź, potem zbuduj","s5_d":"Na karcie Budowanie kliknij <b>Sprawdź (plan)</b>, aby zobaczyć każdy plik, numer i limit, zanim cokolwiek zostanie zapisane. Potem kliknij <b>Zbuduj wszystko</b>. Wynik jest ponownie wczytywany i sprawdzany.","s6_t":"Na serwerze","s6_d":"Skopiuj foldery zasobów do <code>resources/</code> i dodaj je do <code>server.cfg</code>. Wypróbuj nową paczkę na serwerze testowym, zanim wrzucisz ją na serwer produkcyjny.","cl_title":"Kreator ubrań","cl_sub":"Na karcie Ubrania jest lista; karta Budowanie zapisuje zasób.","cl1_t":"Numery","cl1_l":"<li>Kolejność na liście to numer: puste pole oznacza następny wolny numer w danym slocie.</li><li>Stały numer sprawia, że zapisane stroje nadal wskazują na to samo ubranie. Jeśli dwa ubrania chcą ten sam numer, pierwsze go zachowuje, a drugie dostaje następny wolny, i plan to pokazuje.</li><li>Powyżej 255 drawable jednego rodzaju reszta trafia do drugiej kolekcji (<code>&lt;collection&gt;2</code>).</li><li>Luka poniżej najwyższego numeru jest wypełniana niewidzialnym dummy, ponieważ gra czyta od 000 w górę.</li>","cl2_t":"Sprawdzane limity","cl2_l":"<li>255 drawable na slot i ciało, 26 tekstur (a–z) na ubranie.</li><li>Sloty streamingu peda dla buildu gry na serwerze.</li><li>Pozycje w sklepie, długość nazw plików (poniżej 128 bajtów), nazwy małymi literami.</li><li>Ubranie bez slotu, ciała lub tekstury to błąd i nic nie jest zgadywane.</li>","cl3_t":"Co jest zapisywane","cl3_d":"<code>fxmanifest.lua</code>, <code>stream/</code> z modelami, teksturami i fizyką materiału, jeden <code>.ymt</code> i jeden sklepowy <code>.meta</code> na ciało, modele pierwszoosobowe (<code>_1.ydd</code>), zamiany włosów (<code>pedalternatevariations.meta</code>), wysokości obcasów i <code>.zip</code> folderu.","cl4_t":"Przebudowa istniejącej paczki","cl4_d":"Zaimportuj zbudowaną paczkę przez <b>Folder / paczka</b>, aby zmienić nazwę jej kolekcji lub połączyć paczki. Flagi, profile audio, wysokości obcasów, włosy propów, zamiany włosów i nazwa kolekcji są odczytywane z jej plików <code>.ymt</code> i <code>.meta</code>.","t_title":"Tatuaże","t1_t":"Tworzenie i umieszczanie","t1_l":"<li><b>+ Tatuaż (PNG)</b>: każdy obraz staje się plikiem <code>.ytd</code> 512×512 DXT5. Gotowy <code>.ytd</code> też działa; tekstura w środku dostaje w buildzie Id tatuażu.</li><li>Wybierz strefę ciała, a potem umieść tatuaż osobno na ciele męskim i żeńskim: w 3D na pedzie albo w polu <b>Kwadrat UV</b> (przeciągnij, aby przesunąć, kółko myszy zmienia rozmiar).</li><li>Id to nazwa hasha. Gdy jest puste, używana jest nazwa pliku.</li>","t2_t":"Co jest zapisywane","t2_l":"<li>Overlay XML i <code>fxmanifest.lua</code> z <code>PED_OVERLAY_FILE</code>.</li><li>Opcjonalnie <code>shop_tattoo.meta</code> (czyta go tylko salon tatuażu z podstawowej gry).</li><li>Opcjonalnie Listy menu w <code>exports/</code>: qb (<code>AllTattoos.json</code>), esx (<code>Config.TattooList</code>) i illenium-appearance. Nowsze wersje illenium-appearance same znajdują tatuaże w pliku overlay, więc ta lista jest domyślnie wyłączona.</li>","t_box":"Nadaj zasobowi z tatuażami własną nazwę. Program odmówi budowania, jeśli zasób z tatuażami i zasób z ubraniami trafiłyby do tego samego folderu, bo zbudowanie jednego przeniosłoby drugi do kosza.","st_title":"Narzędzia studia","st_sub":"Operacje działają na kopii modelu w folderze projektu. Każdą operację można cofnąć przez Ctrl+Z, łącznie z plikami. Operacja, która się nie powiedzie, przywraca plik do poprzedniego stanu.","st_group":"Grupa","st_tools":"Narzędzia","st_g_weights":"Wagi","st_r_weights":"Skopiuj wagi z ciała · Wygładź wagi · Popraw wagi · Synchronizuj wagi szwów","st_g_fit":"Dopasowanie i kształt","st_r_fit":"Wypchnij z ciała · Napompuj / zmniejsz · Dopasuj do ciała · Dopasuj do ciała (shrinkwrap) · Brzeg nad podłogą · Odbij lewo/prawo · Wyrównaj rękawy · Zwęź rękawy · Zastosuj przesunięcie / obrót / skalę","st_g_mesh":"Siatka","st_r_mesh":"Napraw normalne · Zespawaj szwy · Zamknij otwory · Zamknij szczeliny · Pogrubienie (do środka) · Zapisz cały plik od nowa","st_g_lod":"Poziom szczegółów","st_r_lod":"Utwórz LOD · Wagi dla LOD · Zmniejsz liczbę trójkątów","st_g_special":"Propy, włosy, obcasy, fizyka","st_r_special":"Zamień w prop · Alternatywne włosy · Poza na obcasach · Kości obcasa · Utwórz fizykę materiału (.yld) · Ponownie powiąż fizykę materiału · Przytnij nieużywaną teksturę","st_g_shader":"Shader","st_r_shader":"27 shaderów pedów, każdy z opisem, do czego służy.","st_g_tex":"Tekstury","st_r_tex":"+ Z PNG (DXT1/DXT5 z mipmapami) · Zmień kolor → nowy wariant · Zastąp z PNG · Eksportuj jako PNG · Mapy normal + spec (PNG)","st_g_export":"Eksportuj model","st_r_export":"XML Sollumz / CodeWalker · .obj (Blender itp.)","p_intro":"Na karcie Budowanie jest pole wyboru <code>subdir_file_mapping</code>. Gdy jest włączone, <code>fxmanifest.lua</code> zasobu z ubraniami dostaje tę linię:","p_list":"<li><b>Domyślnie jest wyłączone.</b> Z tą linią serwer bez tej polityki w ogóle odmówi uruchomienia zasobu.</li><li><b>Bez tej linii</b> serwer bez polityki wczyta paczkę, ale nie pokaże żadnych ubrań i nic nie pojawi się w konsoli. Serwer z 10 slotami lub mniej dostaje politykę automatycznie; powyżej tego jest ona dostępna z subskrypcją Element Club Argentum (lub wyższą).</li><li><b>Włącz je</b>, gdy Twój serwer ma więcej niż 10 slotów i ma tę politykę, żeby brak polityki objawił się wyraźnym błędem przy starcie zamiast niewidocznych ubrań. Na serwerze z 10 slotami lub mniej zostaw je wyłączone.</li><li>Plan buildu przypomina o tym, gdy opcja jest wyłączona. Nie zostało jeszcze potwierdzone w grze, czy ta linia jest potrzebna, więc przetestuj to na własnym serwerze.</li>","q1":"Czy jest darmowy?","a1":"Tak. Unlimited Cloth jest darmowy i otwarty na licencji MIT, stworzony przez Unlimited Reforge.","q2":"Czy potrzebuję GTA V, Blendera lub CodeWalkera?","a2":"Nie. Program sam czyta i zapisuje formaty gry, a pedy freemode do podglądu są do niego dołączone. Na karcie Pedy możesz zamiast nich użyć plików z własnej gry (opcjonalnie).","q3":"Z jakimi menu ubrań działa?","a3":"Zasób z ubraniami to zwykła paczka addon, więc pokaże go każde menu, które czyta ubrania addon. Dla tatuaży program zapisuje listy dla qb, esx i illenium-appearance. Sprawdź nazwy pól z Twoją wersją menu.","q4":"Czy zmieni moje oryginalne pliki?","a4":"Nie. Operacje naprawcze działają na kopii w folderze projektu, a wszystko, co stoi na przeszkodzie (na przykład stary build), trafia do systemowego kosza. Nic nie jest usuwane na stałe.","q5":"Moje ubrania nie pokazują się w grze","a5":"<li>Sprawdź, ile slotów ma serwer, i politykę <a href=\"#policy\">subdir_file_mapping</a>.</li><li>Upewnij się, że zasób jest uruchomiony (<code>ensure</code>) i że build gry na serwerze jest tym wybranym na karcie Budowanie.</li><li>Użyj opcji <b>Sprawdź istniejącą paczkę…</b> na karcie Budowanie, aby ponownie wczytać folder.</li>","q6":"Dlaczego Windows ostrzega przed nieznanym wydawcą?","a6":"Instalator jest podpisany własnym certyfikatem Unlimited Reforge, a nie certyfikatem kupionym od urzędu certyfikacji, więc Windows jeszcze nie zna wydawcy. W sekcji <a href=\"#install\">Instalacja</a> opisano, jak przejść przez SmartScreen.","q7":"Gdzie znajdę pomoc?","a7":"Pytania, błędy i pomysły zgłaszaj na <a href=\"https://discord.gg/uaASPkghXu\" rel=\"noopener\">Unlimited Discord</a>. Program nie ma adresu e-mail.","ch_title":"Lista zmian","ch_first":"pierwsze wydanie","ch_list":"<li>Kreator paczek ubrań: import .ydd/.ytd/.yld, całych paczek addon, .ydd.xml, .glb, .obj i .blend; numerowanie, kontrola limitów, druga kolekcja powyżej 255, .zip.</li><li>Przebudowa paczki zachowuje jej flagi, audio, obcasy, włosy propów, zamiany włosów i nazwę kolekcji.</li><li>Studio z operacjami naprawczymi dla wag, dopasowania, siatki, LOD, propów, włosów, obcasów i fizyki materiału, 27 shaderów, narzędzia do tekstur i eksport do Sollumz/.obj; cofanie i ponawianie każdej operacji.</li><li>Podgląd 3D z 31 pozami i animacjami oraz kontrolą przenikania.</li><li>Kreator tatuaży z umieszczaniem w 3D i UV, overlay XML, shop_tattoo.meta i listami dla qb, esx i illenium-appearance.</li><li>Każdy zbudowany plik jest ponownie wczytywany: modele (z pełnym cyklem zapisu i odczytu), tekstury, .ymt (komponenty i propy), sklepowy meta, zamontowane pliki danych i własne kontrole paczek silnika.</li><li>Dołączone pedy freemode; Twoje własne pliki gry są opcjonalne i uzupełniają tylko to, co im podasz.</li><li>Konfiguracja przy pierwszym uruchomieniu, 12 języków, autozapis i odzyskiwanie po awarii.</li>","ch_known":"Znane ograniczenia: nowo zapisane pliki .ydd zostały potwierdzone w grze tylko z paczką testową, import z instalacji GTA V nie był testowany, a wersja na Windows jest nowa. Najpierw testuj na serwerze testowym.","dc_title":"Pytania? Dołącz do Discorda","dc_sub":"Pomoc, zgłoszenia błędów i pomysły dotyczące Unlimited Cloth i reszty Unlimited.","dc_btn":"Otwórz Unlimited Discord","f_lic":"© 2026 Unlimited Reforge · licencja MIT","f_rock":"Dołączone pedy freemode pochodzą z zasobów Rockstar Games. Unlimited Reforge nie jest powiązane z Rockstar Games ani Cfx.re.","ss_btn":"Szukaj na stronie","ss_ph":"Szukaj na stronie…","ss_none":"Nic nie znaleziono. Spróbuj innego słowa.","ss_more":"Jeszcze {n} wyników. Wpisz więcej, aby zawęzić.","ss_close":"Zamknij wyszukiwanie"},"pt":{"meta_title":"Unlimited Cloth: criador de roupas e tatuagens para FiveM","meta_desc":"O Unlimited Cloth é um programa de computador gratuito para Windows e Linux que prepara roupas e tatuagens freemode do GTA V para o FiveM: construtor de packs, ferramentas de correção no estúdio, pré-visualização 3D com animações e construtor de tatuagens.","langlabel":"Idioma","theme_light":"Mudar para o modo claro","theme_dark":"Mudar para o modo escuro","nav_more":"Mais","skip":"Saltar para o conteúdo","nav_what":"Funcionalidades","nav_dl":"Transferir","nav_install":"Instalar","nav_start":"Primeiros passos","nav_clothes":"Roupas","nav_tattoos":"Tatuagens","nav_studio":"Estúdio","nav_faq":"Perguntas frequentes","nav_changelog":"Alterações","h_badge":"Gratuito · MIT · Windows e Linux · versão 1.0.0","h_title":"Roupas e tatuagens para FiveM, prontas para streaming","h_sub":"O Unlimited Cloth prepara roupas e tatuagens freemode do GTA V para o FiveM. Importa peças ou packs addon inteiros, corrige-os no estúdio, experimenta-os no ped freemode animado e compila um recurso pronto e um .zip. Cada ficheiro que escreve é lido de novo e verificado.","h_dl":"Transferir 1.0.0","h_start":"Primeiros passos","h_note":"Sem separador no navegador, sem porta de rede e sem precisar de Blender, Python ou CodeWalker. Feito pela Unlimited Reforge.","alt_studio":"A aba Studio: o ped freemode feminino de cropped e calça de couro, com as ferramentas de correção à direita","w_title":"O que faz","w_sub":"Um só programa para o trabalho todo, desde ficheiros soltos até um recurso a que podes fazer <code>ensure</code>.","w1_t":"Construtor de packs de roupa","w1_d":"Componentes e props para <code>mp_m_freemode_01</code> e <code>mp_f_freemode_01</code>, numerados automaticamente, verificados contra os limites do jogo e escritos como <code>fxmanifest.lua</code>, <code>stream/</code>, <code>.ymt</code> e <code>.meta</code> de loja, mais um .zip.","w2_t":"Ferramentas de correção do estúdio","w2_d":"Copiar pesos do corpo, empurrar para fora do corpo, encaixar e shrinkwrap, LOD, shaders, props, cabelo alternativo, saltos, física de tecido e ferramentas de texturas. Tudo pode ser desfeito.","w3_t":"Pré-visualização 3D e animações","w3_d":"O ped freemode com pele e as tuas peças, 31 poses e animações, e <b>Mostrar clipping</b>, que marca a vermelho onde o corpo atravessa a roupa, a que profundidade e em que osso.","w4_t":"Construtor de tatuagens","w4_d":"Entra um PNG, sai um .ytd DXT5 de 512×512. Coloca cada tatuagem por zona e por corpo em 3D ou no quadrado UV, e obtém o XML de overlays e listas prontas para qb, esx e illenium-appearance.","w5_t":"Seguro com os teus ficheiros","w5_d":"As correções trabalham numa cópia na pasta do projeto, por isso o teu original nunca é alterado. Nada é apagado de vez: uma compilação antiga vai para o lixo do sistema.","w6_t":"Projetos e idiomas","w6_d":"Projetos em JSON simples (<code>.ucloth</code>) com caminhos relativos que abrem tanto no Windows como no Linux, gravação automática para recuperar de falhas, desfazer e refazer. O programa está disponível em 12 idiomas.","c_clip":"Mostrar clipping na animação de andar","c_tat":"Uma tatuagem colocada em 3D","c_build":"Compilar: o plano e a verificação por releitura","d_title":"Transferir","d_sub":"Versão 1.0.0. Todos os ficheiros estão na página da release no GitHub, juntamente com as notas da versão.","d_win_d":"Instalador: escolhe uma pasta, cria atalhos e desinstala-se em Aplicações.","d_deb_d":"Debian, Ubuntu, Mint, Pop!_OS e outros sistemas com apt.","d_app_d":"Um único ficheiro que funciona na maioria das distribuições, sem instalação.","d_all":"Todas as versões","d_note":"Os peds freemode usados na pré-visualização vêm com o programa; não é preciso transferir mais nada.","i_title":"Instalar","i_win_steps":"<li>Executa <code>Unlimited-Cloth-Setup-1.0.0.exe</code>.</li><li>Escolhe a pasta de instalação. São criados atalhos no ambiente de trabalho e no menu Iniciar.</li><li>Para desinstalar mais tarde, vai a Definições → Aplicações.</li>","i_win_warn":"<b>\"O Windows protegeu o seu PC\" / editor desconhecido.</b> O instalador está assinado com o certificado próprio da Unlimited Reforge, que o Windows ainda não conhece, por isso o Microsoft SmartScreen pode bloqueá-lo da primeira vez. Clica em <b>Mais informações</b>, confirma que o ficheiro é o da página da release e depois clica em <b>Executar mesmo assim</b>.","i_deb":"<b>.deb</b> (Debian, Ubuntu e semelhantes):","i_app":"<b>AppImage</b>: torna-o executável e abre-o.","i_fuse":"Se o AppImage não arrancar no Ubuntu 22.04 ou mais recente, instala o FUSE 2: <code>sudo apt install libfuse2</code> (<code>libfuse2t64</code> no 24.04).","i_where_t":"Onde fica tudo guardado","i_where_d":"Definições, gravação automática e os teus próprios peds: <code>%APPDATA%\\Unlimited Cloth</code> no Windows, <code>~/.config/Unlimited Cloth</code> no Linux. Os recursos compilados vão para <code>Documents/Unlimited Cloth/build</code>, a menos que escolhas outra pasta.","s_title":"Primeiros passos","s1_t":"Configuração inicial","s1_d":"O programa arranca em inglês e guia-te pelo idioma, pelas preferências, pelas pastas, pelos peds e pelos padrões para novos projetos. Podes saltá-la e voltar a executá-la em <b>?</b> → <b>Executar configuração novamente</b>.","s2_t":"Experimenta com conteúdo de teste","s2_d":"Carrega em <b>Roupas de teste</b> no separador Roupas. Recebes uma camisola de teste para cada corpo e um boné para ambos, feitos pelo próprio programa, para poderes experimentar todas as ferramentas antes de usares os teus próprios ficheiros.","s3_t":"Importa as tuas peças","s3_d":"<b>+ Importar ficheiros</b> aceita <code>.ydd</code>, <code>.ytd</code>, <code>.yld</code>, <code>.ydd.xml</code> do Sollumz/CodeWalker, <code>.glb</code>, <code>.obj</code>, <code>.blend</code> e <code>.png</code>. <b>Pasta / pack</b> aceita uma pasta inteira ou um pack addon existente.","s4_t":"Corpo, slot e texturas","s4_d":"Para cada peça escolhe o corpo (masculino, feminino ou ambos), o slot de componente ou de prop e até 26 variantes de textura (a–z). Um <b>!</b> na lista significa que ainda falta alguma coisa.","s5_t":"Verifica e depois compila","s5_d":"No separador Compilar carrega em <b>Verificar (plano)</b> para ver cada ficheiro, número e limite antes de ser escrito o que quer que seja. Depois carrega em <b>Compilar tudo</b>. O resultado é lido de novo e verificado.","s6_t":"No servidor","s6_d":"Copia as pastas dos recursos para <code>resources/</code> e adiciona-as ao <code>server.cfg</code>. Experimenta um pack novo num servidor de testes antes de o pores num servidor em produção.","cl_title":"Construtor de roupas","cl_sub":"O separador Roupas contém a lista; o separador Compilar escreve o recurso.","cl1_t":"Números","cl1_l":"<li>A ordem na lista é o número: vazio significa o próximo número livre nesse slot.</li><li>Um número fixo faz com que as roupas guardadas continuem a apontar para a mesma peça. Se duas peças pedirem o mesmo número, a primeira fica com ele e a outra recebe o próximo livre, e o plano indica-o.</li><li>Acima de 255 drawables do mesmo tipo, o resto vai para uma segunda coleção (<code>&lt;collection&gt;2</code>).</li><li>Uma lacuna abaixo do número mais alto é preenchida com um dummy invisível, porque o jogo lê a partir de 000 para cima.</li>","cl2_t":"Limites que verifica","cl2_l":"<li>255 drawables por slot e corpo, 26 texturas (a–z) por peça.</li><li>Slots de streaming de peds para a build do jogo do servidor.</li><li>Entradas de loja, comprimento do nome de ficheiro (menos de 128 bytes), nomes em minúsculas.</li><li>Uma peça sem slot, sem corpo ou sem textura é um erro e nunca é adivinhada.</li>","cl3_t":"O que é escrito","cl3_d":"<code>fxmanifest.lua</code>, <code>stream/</code> com os modelos, as texturas e a física de tecido, um <code>.ymt</code> e um <code>.meta</code> de loja por corpo, modelos na primeira pessoa (<code>_1.ydd</code>), trocas de cabelo (<code>pedalternatevariations.meta</code>), alturas de salto e um <code>.zip</code> da pasta.","cl4_t":"Recompilar um pack existente","cl4_d":"Importa um pack já compilado com <b>Pasta / pack</b> para mudar o nome da coleção ou juntar packs. As flags, os perfis de áudio, as alturas de salto, o cabelo dos props, as trocas de cabelo e o nome da coleção são recuperados dos seus ficheiros <code>.ymt</code> e <code>.meta</code>.","t_title":"Tatuagens","t1_t":"Criar e colocar","t1_l":"<li><b>+ Tatuagem (PNG)</b>: cada imagem passa a ser um <code>.ytd</code> DXT5 de 512×512. Um <code>.ytd</code> já feito também serve; a textura lá dentro recebe o Id da tatuagem na compilação.</li><li>Escolhe a zona do corpo e depois coloca a tatuagem separadamente no corpo masculino e no feminino: em 3D sobre o ped ou no <b>Quadrado UV</b> (arrasta para mover, roda do rato para redimensionar).</li><li>O Id é o nome do hash. Quando está vazio, é usado o nome do ficheiro.</li>","t2_t":"O que é escrito","t2_l":"<li>O XML de overlays e o <code>fxmanifest.lua</code> com <code>PED_OVERLAY_FILE</code>.</li><li><code>shop_tattoo.meta</code> opcional (só a loja de tatuagens do jogo base o lê).</li><li>Listas de menu opcionais em <code>exports/</code>: qb (<code>AllTattoos.json</code>), esx (<code>Config.TattooList</code>) e illenium-appearance. As versões mais recentes do illenium-appearance encontram as tatuagens no ficheiro de overlays sozinhas, por isso essa lista está desligada por padrão.</li>","t_box":"Dá ao recurso de tatuagens um nome próprio. O programa recusa-se a compilar se os recursos de tatuagens e de roupa forem parar à mesma pasta, porque compilar um moveria o outro para o lixo.","st_title":"Ferramentas do estúdio","st_sub":"As tarefas trabalham numa cópia do modelo na pasta do projeto. Todas podem ser desfeitas com Ctrl+Z, ficheiros incluídos. Uma tarefa que falhe repõe o ficheiro tal como estava.","st_group":"Grupo","st_tools":"Ferramentas","st_g_weights":"Pesos","st_r_weights":"Copiar pesos do corpo · Suavizar pesos · Legalizar pesos · Sincronizar pesos das costuras","st_g_fit":"Ajuste e forma","st_r_fit":"Empurrar para fora do corpo · Inflar / desinflar · Encaixar no corpo · Ajustar ao corpo (shrinkwrap) · Bainha acima do chão · Espelhar esquerda/direita · Alinhar mangas · Afunilar mangas · Aplicar mover / rodar / escalar","st_g_mesh":"Malha","st_r_mesh":"Corrigir normais · Soldar costuras · Fechar aberturas · Fechar buracos · Solidificar (interior) · Reescrever ficheiro inteiro","st_g_lod":"Nível de detalhe","st_r_lod":"Criar LOD · Aplicar pesos aos LOD · Reduzir triângulos","st_g_special":"Props, cabelo, saltos, física","st_r_special":"Converter em prop · Cabelo alternativo · Pose do salto · Ossos do salto · Criar física de tecido (.yld) · Religar física de tecido · Recortar textura não usada","st_g_shader":"Shader","st_r_shader":"27 shaders de ped, com uma nota sobre a utilidade de cada um.","st_g_tex":"Texturas","st_r_tex":"+ A partir de PNG (DXT1/DXT5 com mipmaps) · Recolorir → nova variante · Substituir a partir de PNG · Exportar como PNG · Mapas normal + spec (PNG)","st_g_export":"Exportar modelo","st_r_export":"XML do Sollumz / CodeWalker · .obj (Blender etc.)","p_intro":"O separador Compilar tem uma caixa <code>subdir_file_mapping</code>. Quando está ligada, o <code>fxmanifest.lua</code> do recurso de roupa recebe esta linha:","p_list":"<li><b>Desligada por padrão.</b> Com a linha, um servidor que não tenha a policy recusa-se a iniciar o recurso.</li><li><b>Sem a linha</b>, um servidor sem a policy carrega o pack e não mostra roupa nenhuma, sem nada na consola. Um servidor com 10 slots ou menos recebe a policy automaticamente; acima disso, vem com uma subscrição Element Club Argentum (ou superior).</li><li><b>Liga-a</b> quando o teu servidor tiver mais de 10 slots e tiver a policy, para que a falta da policy apareça como um erro claro ao iniciar em vez de roupa invisível. Deixa-a desligada num servidor com 10 slots ou menos.</li><li>O plano de compilação lembra-te quando está desligada. Ainda não foi comprovado no jogo se a linha é necessária, por isso testa no teu próprio servidor.</li>","q1":"É gratuito?","a1":"Sim. O Unlimited Cloth é gratuito e de código aberto sob a licença MIT, feito pela Unlimited Reforge.","q2":"Preciso do GTA V, do Blender ou do CodeWalker?","a2":"Não. O programa lê e escreve os formatos do jogo sozinho, e os peds freemode para a pré-visualização vêm incluídos. No separador Peds podes usar ficheiros do teu próprio jogo em vez disso (opcional).","q3":"Com que menus de roupa funciona?","a3":"O recurso de roupa é um pack addon normal, por isso qualquer menu que leia roupa addon mostra-o. Para as tatuagens, o programa escreve listas para qb, esx e illenium-appearance. Confirma os nomes dos campos com a tua versão do menu.","q4":"Vai alterar os meus ficheiros originais?","a4":"Não. As correções trabalham numa cópia na pasta do projeto, e tudo o que estiver no caminho (uma compilação antiga, por exemplo) vai para o lixo do sistema. Nada é apagado de vez.","q5":"A minha roupa não aparece no jogo","a5":"<li>Verifica quantos slots o servidor tem e a policy <a href=\"#policy\">subdir_file_mapping</a>.</li><li>Confirma que o recurso está iniciado (<code>ensure</code>) e que a build do jogo do servidor é a escolhida no separador Compilar.</li><li>Usa <b>Verificar um pack existente…</b> no separador Compilar para voltar a ler a pasta.</li>","q6":"Porque é que o Windows avisa de um editor desconhecido?","a6":"O instalador está assinado com o certificado próprio da Unlimited Reforge, e não com um comprado a uma autoridade de certificação, por isso o Windows ainda não conhece o editor. Vê em <a href=\"#install\">Instalar</a> como passar pelo SmartScreen.","q7":"Onde obtenho ajuda?","a7":"Dúvidas, erros e ideias vão para o <a href=\"https://discord.gg/uaASPkghXu\" rel=\"noopener\">Unlimited Discord</a>. O programa não tem endereço de e-mail.","ch_title":"Alterações","ch_first":"primeira versão","ch_list":"<li>Construtor de packs de roupa: importação de .ydd/.ytd/.yld, packs addon inteiros, .ydd.xml, .glb, .obj e .blend; numeração, verificação de limites, uma segunda coleção acima de 255, .zip.</li><li>Recompilar um pack mantém as flags, o áudio, os saltos, o cabelo dos props, as trocas de cabelo e o nome da coleção.</li><li>Estúdio com tarefas de correção para pesos, ajuste, malha, LOD, props, cabelo, saltos e física de tecido, 27 shaders, ferramentas de texturas e exportação para Sollumz/.obj; desfazer e refazer para cada tarefa.</li><li>Pré-visualização 3D com 31 poses e animações e uma verificação de clipping.</li><li>Construtor de tatuagens com colocação em 3D e UV, XML de overlays, shop_tattoo.meta e listas para qb, esx e illenium-appearance.</li><li>Cada ficheiro compilado é lido de novo: modelos (com ida e volta), texturas, .ymt (componentes e props), meta de loja, ficheiros de dados montados e as próprias verificações de packs do motor.</li><li>Peds freemode incluídos; os teus próprios ficheiros do jogo são opcionais e só completam o que lhes deres.</li><li>Configuração inicial, 12 idiomas, gravação automática e recuperação de falhas.</li>","ch_known":"Limites conhecidos: os ficheiros .ydd escritos de novo só foram comprovados no jogo com o pack de teste, a importação a partir de uma instalação do GTA V não foi testada e a build para Windows é nova. Testa primeiro num servidor de testes.","dc_title":"Dúvidas? Junta-te ao Discord","dc_sub":"Suporte, relatórios de erros e ideias para o Unlimited Cloth e o resto do Unlimited.","dc_btn":"Abrir o Unlimited Discord","f_lic":"© 2026 Unlimited Reforge · Licença MIT","f_rock":"Os peds freemode incluídos derivam de recursos da Rockstar Games. A Unlimited Reforge não tem qualquer ligação à Rockstar Games nem à Cfx.re.","ss_btn":"Pesquisar no site","ss_ph":"Pesquisar no site…","ss_none":"Nada encontrado. Experimenta outra palavra.","ss_more":"Mais {n} resultados. Escreve mais para afinar.","ss_close":"Fechar pesquisa"},"tr":{"meta_title":"Unlimited Cloth: FiveM kıyafet ve dövme oluşturucu","meta_desc":"Unlimited Cloth, GTA V freemode kıyafetlerini ve dövmelerini FiveM için hazırlayan, Windows ve Linux için ücretsiz bir masaüstü programıdır: paket oluşturucu, stüdyo düzeltme araçları, animasyonlu 3D önizleme ve dövme oluşturucu.","langlabel":"Dil","theme_light":"Açık moda geç","theme_dark":"Koyu moda geç","nav_more":"Daha fazla","skip":"İçeriğe geç","nav_what":"Özellikler","nav_dl":"İndir","nav_install":"Kurulum","nav_start":"Başlarken","nav_clothes":"Kıyafetler","nav_tattoos":"Dövmeler","nav_studio":"Stüdyo","nav_faq":"SSS","nav_changelog":"Değişiklikler","h_badge":"Ücretsiz · MIT · Windows ve Linux · sürüm 1.0.0","h_title":"FiveM kıyafetleri ve dövmeleri, stream'e hazır","h_sub":"Unlimited Cloth, GTA V freemode kıyafetlerini ve dövmelerini FiveM için hazırlar. Kıyafetleri ya da bütün addon paketlerini içe aktar, stüdyoda düzelt, animasyonlu freemode ped üzerinde dene ve hazır bir kaynak ile .zip derle. Yazdığı her dosya tekrar okunur ve kontrol edilir.","h_dl":"1.0.0'ı indir","h_start":"Başlarken","h_note":"Tarayıcı sekmesi yok, ağ portu yok; Blender, Python veya CodeWalker gerekmez. Unlimited Reforge tarafından yapıldı.","alt_studio":"Studio sekmesi: kısa üst ve deri pantolonlu kadın freemode ped, sağda düzeltme araçları","w_title":"Ne yapar","w_sub":"Dağınık dosyalardan <code>ensure</code> edebileceğin bir kaynağa kadar bütün iş için tek program.","w1_t":"Kıyafet paketi oluşturucu","w1_d":"<code>mp_m_freemode_01</code> ve <code>mp_f_freemode_01</code> için bileşenler ve prop'lar; senin yerine numaralandırılır, oyunun sınırlarına göre kontrol edilir ve <code>fxmanifest.lua</code>, <code>stream/</code>, <code>.ymt</code> ve mağaza <code>.meta</code> dosyaları olarak yazılır, ayrıca bir .zip.","w2_t":"Stüdyo düzeltme araçları","w2_d":"Ağırlıkları vücuttan kopyalama, vücuttan dışarı itme, oturtma ve shrinkwrap, LOD'lar, shader'lar, prop'lar, saç alternatifleri, topuklar, kumaş fiziği ve texture araçları. Her işlem geri alınabilir.","w3_t":"3D önizleme ve animasyonlar","w3_d":"Cildi ve senin kıyafetlerinle freemode ped, 31 poz ve animasyon, ayrıca vücudun kıyafetten nerede dışarı taştığını, ne kadar derin ve hangi kemikte olduğunu kırmızıyla işaretleyen <b>Clipping'i göster</b> seçeneği.","w4_t":"Dövme oluşturucu","w4_d":"PNG girer, 512×512 DXT5 .ytd çıkar. Her dövmeyi bölgeye ve vücuda göre 3D'de veya UV karesinde yerleştir; overlay XML'ini ve qb, esx ve illenium-appearance için hazır listeleri al.","w5_t":"Dosyaların güvende","w5_d":"Düzeltme işlemleri proje klasöründeki bir kopya üzerinde çalışır, bu yüzden orijinal dosyan asla değişmez. Hiçbir şey kalıcı olarak silinmez: eski bir derleme sistemin çöp kutusuna gider.","w6_t":"Projeler ve diller","w6_d":"Hem Windows'ta hem Linux'ta açılan, göreli yollar içeren düz JSON projeleri (<code>.ucloth</code>), çökmeden kurtarma için otomatik kaydetme, geri al ve yinele. Program 12 dilde kullanılabilir.","c_clip":"Yürüme animasyonunda Clipping'i göster","c_tat":"3D'de yerleştirilmiş bir dövme","c_build":"Derle: plan ve tekrar okuma kontrolü","d_title":"İndir","d_sub":"Sürüm 1.0.0. Tüm dosyalar, sürüm notlarıyla birlikte GitHub'daki release sayfasında.","d_win_d":"Kurulum programı: bir klasör seç, kısayollar oluşturulsun, Uygulamalar'dan kaldır.","d_deb_d":"Debian, Ubuntu, Mint, Pop!_OS ve apt kullanan diğer sistemler.","d_app_d":"Kurulum gerektirmeden çoğu dağıtımda çalışan tek bir dosya.","d_all":"Tüm sürümler","d_note":"Önizlemenin kullandığı freemode ped'ler programla birlikte gelir; başka hiçbir şey indirmen gerekmez.","i_title":"Kurulum","i_win_steps":"<li><code>Unlimited-Cloth-Setup-1.0.0.exe</code> dosyasını çalıştır.</li><li>Kurulum klasörünü seç. Masaüstü ve Başlat menüsü kısayolları oluşturulur.</li><li>Daha sonra Ayarlar → Uygulamalar'dan kaldırabilirsin.</li>","i_win_warn":"<b>\"Windows bilgisayarınızı korudu\" / bilinmeyen yayımcı.</b> Kurulum programı, Unlimited Reforge'un Windows'un henüz tanımadığı kendi sertifikasıyla imzalanmıştır; bu yüzden Microsoft SmartScreen onu ilk seferde durdurabilir. <b>Ek bilgi</b>'ye tıkla, dosyanın release sayfasındaki dosya olduğunu kontrol et, ardından <b>Yine de çalıştır</b>'a tıkla.","i_deb":"<b>.deb</b> (Debian, Ubuntu ve benzerleri):","i_app":"<b>AppImage</b>: çalıştırılabilir yap ve çalıştır.","i_fuse":"AppImage, Ubuntu 22.04 veya daha yeni bir sürümde açılmazsa FUSE 2'yi kur: <code>sudo apt install libfuse2</code> (24.04'te <code>libfuse2t64</code>).","i_where_t":"Dosyalar nerede tutulur","i_where_d":"Ayarlar, otomatik kayıt ve kendi ped'lerin: Windows'ta <code>%APPDATA%\\Unlimited Cloth</code>, Linux'ta <code>~/.config/Unlimited Cloth</code>. Derlenen kaynaklar, başka bir klasör seçmediğin sürece <code>Documents/Unlimited Cloth/build</code> klasörüne gider.","s_title":"Başlarken","s1_t":"İlk çalıştırma kurulumu","s1_d":"Program İngilizce açılır ve seni dil, tercihler, klasörler, ped'ler ve yeni projeler için varsayılanlar boyunca yönlendirir. Bu adımı atlayıp daha sonra <b>?</b> → <b>Kurulumu yeniden çalıştır</b> ile yeniden başlatabilirsin.","s2_t":"Test içeriğiyle dene","s2_d":"Kıyafetler sekmesinde <b>Test kıyafetleri</b> düğmesine bas. Programın kendisinin yaptığı, her vücut için bir test üstü ve ikisi için bir şapka alırsın; böylece kendi dosyalarını kullanmadan önce her aracı deneyebilirsin.","s3_t":"Kıyafetlerini içe aktar","s3_d":"<b>+ Dosya içe aktar</b>; <code>.ydd</code>, <code>.ytd</code>, <code>.yld</code>, Sollumz/CodeWalker <code>.ydd.xml</code>, <code>.glb</code>, <code>.obj</code>, <code>.blend</code> ve <code>.png</code> dosyalarını alır. <b>Klasör / paket</b> ise bütün bir klasörü veya mevcut bir addon paketini alır.","s4_t":"Vücut, slot ve texture'lar","s4_d":"Her kıyafet için vücudu (erkek, kadın veya ikisi), bileşen ya da prop slotunu ve en fazla 26 texture varyantını (a–z) seç. Listedeki <b>!</b> işareti hâlâ bir şeyin eksik olduğu anlamına gelir.","s5_t":"Kontrol et, sonra derle","s5_d":"Derle sekmesinde, herhangi bir şey yazılmadan önce her dosyayı, numarayı ve sınırı görmek için <b>Kontrol et (plan)</b> düğmesine bas. Ardından <b>Hepsini derle</b> düğmesine bas. Sonuç tekrar okunur ve kontrol edilir.","s6_t":"Sunucuda","s6_d":"Kaynak klasörlerini <code>resources/</code> içine kopyala ve <code>server.cfg</code> dosyasına ekle. Yeni bir paketi canlı sunucuya koymadan önce bir test sunucusunda dene.","cl_title":"Kıyafet oluşturucu","cl_sub":"Kıyafetler sekmesi listeyi tutar; Derle sekmesi kaynağı yazar.","cl1_t":"Numaralar","cl1_l":"<li>Listedeki sıra numaradır: boş bırakmak, o slottaki bir sonraki boş numara demektir.</li><li>Sabit bir numara, kayıtlı kıyafet kombinlerinin aynı kıyafeti göstermeye devam etmesini sağlar. İki kıyafet aynı numarayı isterse ilki onu alır, diğeri bir sonraki boş numarayı alır ve plan bunu belirtir.</li><li>Aynı türden 255 drawable'ı aşınca geri kalanlar ikinci bir koleksiyona gider (<code>&lt;collection&gt;2</code>).</li><li>En yüksek numaranın altındaki bir boşluk görünmez bir dummy ile doldurulur, çünkü oyun 000'dan yukarı doğru okur.</li>","cl2_t":"Kontrol ettiği sınırlar","cl2_l":"<li>Slot ve vücut başına 255 drawable, kıyafet başına 26 texture (a–z).</li><li>Sunucunun oyun build'i için ped streaming slotları.</li><li>Mağaza girdileri, dosya adı uzunluğu (128 bayttan kısa), küçük harfli adlar.</li><li>Slotu, vücudu veya texture'ı olmayan bir kıyafet hatadır ve asla tahmin edilmez.</li>","cl3_t":"Neler yazılır","cl3_d":"<code>fxmanifest.lua</code>, modelleri, texture'ları ve kumaş fiziğini içeren <code>stream/</code>, vücut başına bir <code>.ymt</code> ve bir mağaza <code>.meta</code>, birinci şahıs modelleri (<code>_1.ydd</code>), saç değişimleri (<code>pedalternatevariations.meta</code>), topuk yükseklikleri ve klasörün bir <code>.zip</code> dosyası.","cl4_t":"Mevcut bir paketi yeniden derleme","cl4_d":"Koleksiyonunu yeniden adlandırmak veya paketleri birleştirmek için derlenmiş bir paketi <b>Klasör / paket</b> ile içe aktar. Bayraklar, ses profilleri, topuk yükseklikleri, prop saçı, saç değişimleri ve koleksiyon adı paketin <code>.ymt</code> ve <code>.meta</code> dosyalarından geri gelir.","t_title":"Dövmeler","t1_t":"Oluştur ve yerleştir","t1_l":"<li><b>+ Dövme (PNG)</b>: her resim 512×512 DXT5 bir <code>.ytd</code> olur. Hazır bir <code>.ytd</code> da kullanılabilir; içindeki texture, derlemede dövmenin Id'sini alır.</li><li>Vücut bölgesini seç, sonra dövmeyi erkek ve kadın vücuduna ayrı ayrı yerleştir: ped üzerinde 3D'de veya <b>UV karesi</b> içinde (taşımak için sürükle, boyutlandırmak için fare tekerleğini kullan).</li><li>Id, hash adıdır. Boş olduğunda dosya adı kullanılır.</li>","t2_t":"Neler yazılır","t2_l":"<li>Overlay XML'i ve <code>PED_OVERLAY_FILE</code> içeren <code>fxmanifest.lua</code>.</li><li>İsteğe bağlı <code>shop_tattoo.meta</code> (yalnızca temel oyunun dövme mağazası okur).</li><li><code>exports/</code> içinde isteğe bağlı Menü listeleri: qb (<code>AllTattoos.json</code>), esx (<code>Config.TattooList</code>) ve illenium-appearance. Yeni illenium-appearance sürümleri dövmeleri overlay dosyasında kendileri bulur, bu yüzden o liste varsayılan olarak kapalıdır.</li>","t_box":"Dövme kaynağına kendi adını ver. Dövme ve kıyafet kaynakları aynı klasöre düşecekse program derlemeyi reddeder, çünkü birini derlemek diğerini çöp kutusuna taşır.","st_title":"Stüdyo araçları","st_sub":"İşlemler, proje klasöründeki modelin bir kopyası üzerinde çalışır. Her işlem, dosyalar dahil, Ctrl+Z ile geri alınabilir. Başarısız olan bir işlem dosyayı eski haline geri getirir.","st_group":"Grup","st_tools":"Araçlar","st_g_weights":"Ağırlıklar","st_r_weights":"Ağırlıkları vücuttan kopyala · Ağırlıkları yumuşat · Ağırlıkları geçerli yap · Dikiş ağırlıklarını eşitle","st_g_fit":"Oturtma ve şekil","st_r_fit":"Vücuttan dışarı it · Şişir / söndür · Vücuda oturt · Vücuda shrinkwrap · Etek ucu yerden yukarı · Sol/sağ aynala · Kolları hizala · Kolları daralt · Taşı / döndür / ölçekle uygula","st_g_mesh":"Mesh","st_r_mesh":"Normalleri düzelt · Dikişleri birleştir · Açıklıkları kapat · Boşlukları kapat · Solidify (iç) · Tüm dosyayı yeniden yaz","st_g_lod":"Detay seviyesi","st_r_lod":"LOD oluştur · LOD'ları ağırlıklandır · Üçgenleri azalt","st_g_special":"Prop'lar, saç, topuk, fizik","st_r_special":"Prop'a dönüştür · Saç alternatifi · Topuk pozu · Topuk kemikleri · Kumaş fiziği oluştur (.yld) · Kumaş fiziğini yeniden bağla · Kullanılmayan texture'ı kırp","st_g_shader":"Shader","st_r_shader":"Her birinin ne işe yaradığına dair notla birlikte 27 ped shader'ı.","st_g_tex":"Texture'lar","st_r_tex":"+ PNG'den (mipmap'li DXT1/DXT5) · Yeniden renklendir → yeni varyant · PNG'den değiştir · PNG olarak dışa aktar · Normal + spec map'leri (PNG)","st_g_export":"Modeli dışa aktar","st_r_export":"Sollumz / CodeWalker XML · .obj (Blender vb.)","p_intro":"Derle sekmesinde bir <code>subdir_file_mapping</code> onay kutusu vardır. Açık olduğunda, kıyafet kaynağının <code>fxmanifest.lua</code> dosyasına şu satır eklenir:","p_list":"<li><b>Varsayılan olarak kapalıdır.</b> Bu satır varken, policy'si olmayan bir sunucu kaynağı hiç başlatmaz.</li><li><b>Bu satır yokken</b>, policy'si olmayan bir sunucu paketi yükler ama hiçbir kıyafet göstermez ve konsolda da hiçbir şey çıkmaz. 10 veya daha az slotu olan bir sunucu policy'yi otomatik olarak alır; bunun üzerinde policy, Element Club Argentum (veya daha yüksek) aboneliğiyle gelir.</li><li>Sunucunun 10'dan fazla slotu varsa ve policy'ye sahipse <b>bunu aç</b>; böylece eksik bir policy görünmez kıyafetler yerine açık bir başlatma hatası olarak ortaya çıkar. 10 veya daha az slotu olan bir sunucuda kapalı bırak.</li><li>Kapalı olduğunda derleme planı sana bunu hatırlatır. Satırın gerekli olup olmadığı henüz oyunda kanıtlanmadı, bu yüzden kendi sunucunda test et.</li>","q1":"Ücretsiz mi?","a1":"Evet. Unlimited Cloth, MIT lisansı altında ücretsiz ve açık kaynaklıdır; Unlimited Reforge tarafından yapılmıştır.","q2":"GTA V, Blender veya CodeWalker gerekir mi?","a2":"Hayır. Program oyun formatlarını kendisi okur ve yazar, önizleme için freemode ped'ler de programla birlikte gelir. İstersen Ped'ler sekmesinde bunların yerine kendi oyununun dosyalarını kullanabilirsin (isteğe bağlı).","q3":"Hangi kıyafet menüleriyle çalışır?","a3":"Kıyafet kaynağı normal bir addon paketidir, bu yüzden addon kıyafetleri okuyan her menü onu gösterir. Dövmeler için program qb, esx ve illenium-appearance listeleri yazar. Alan adlarını kullandığın menü sürümüyle karşılaştır.","q4":"Orijinal dosyalarımı değiştirir mi?","a4":"Hayır. Düzeltme işlemleri proje klasöründeki bir kopya üzerinde çalışır ve yolda olan her şey (örneğin eski bir derleme) sistemin çöp kutusuna gider. Hiçbir şey kalıcı olarak silinmez.","q5":"Kıyafetlerim oyunda görünmüyor","a5":"<li>Sunucunun kaç slotu olduğunu ve <a href=\"#policy\">subdir_file_mapping</a> policy'sini kontrol et.</li><li>Kaynağın başlatıldığından (<code>ensure</code>) ve sunucunun oyun build'inin Derle sekmesinde seçilenle aynı olduğundan emin ol.</li><li>Klasörü tekrar okumak için Derle sekmesindeki <b>Mevcut bir paketi kontrol et…</b> seçeneğini kullan.</li>","q6":"Windows neden bilinmeyen yayımcı uyarısı veriyor?","a6":"Kurulum programı bir sertifika yetkilisinden satın alınmış bir sertifikayla değil, Unlimited Reforge'un kendi sertifikasıyla imzalanmıştır; bu yüzden Windows yayımcıyı henüz tanımıyor. SmartScreen'i nasıl geçeceğin için <a href=\"#install\">Kurulum</a> bölümüne bak.","q7":"Nereden yardım alabilirim?","a7":"Sorular, hatalar ve fikirler için <a href=\"https://discord.gg/uaASPkghXu\" rel=\"noopener\">Unlimited Discord</a> sunucusuna gel. Programın e-posta adresi yoktur.","ch_title":"Değişiklikler","ch_first":"ilk sürüm","ch_list":"<li>Kıyafet paketi oluşturucu: .ydd/.ytd/.yld, bütün addon paketleri, .ydd.xml, .glb, .obj ve .blend içe aktarma; numaralandırma, sınır kontrolleri, 255'i aşınca ikinci bir koleksiyon, .zip.</li><li>Bir paketi yeniden derlemek bayraklarını, sesini, topuklarını, prop saçını, saç değişimlerini ve koleksiyon adını korur.</li><li>Ağırlık, oturtma, mesh, LOD, prop, saç, topuk ve kumaş fiziği için düzeltme işlemleri, 27 shader, texture araçları ve Sollumz/.obj dışa aktarma içeren stüdyo; her işlem için geri al ve yinele.</li><li>31 poz ve animasyon ile clipping kontrolü içeren 3D önizleme.</li><li>3D ve UV yerleştirme, overlay XML, shop_tattoo.meta ve qb, esx ve illenium-appearance listeleri içeren dövme oluşturucu.</li><li>Derlenen her dosya tekrar okunur: modeller (gidiş-dönüş ile), texture'lar, .ymt (bileşenler ve prop'lar), mağaza meta'sı, bağlanan veri dosyaları ve motorun kendi paket kontrolleri.</li><li>Programla birlikte gelen freemode ped'ler; kendi oyun dosyaların isteğe bağlıdır ve yalnızca verdiğin kısmı doldurur.</li><li>İlk çalıştırma kurulumu, 12 dil, otomatik kaydetme ve çökmeden kurtarma.</li>","ch_known":"Bilinen sınırlar: yeni yazılan .ydd dosyaları oyunda yalnızca test paketiyle kanıtlandı, bir GTA V kurulumundan içe aktarma test edilmedi ve Windows build'i yeni. Önce bir test sunucusunda dene.","dc_title":"Soruların mı var? Discord'a katıl","dc_sub":"Unlimited Cloth ve Unlimited'ın geri kalanı için destek, hata bildirimleri ve fikirler.","dc_btn":"Unlimited Discord'u aç","f_lic":"© 2026 Unlimited Reforge · MIT lisansı","f_rock":"Programla birlikte gelen freemode ped'ler Rockstar Games varlıklarından türetilmiştir. Unlimited Reforge'un Rockstar Games veya Cfx.re ile hiçbir bağlantısı yoktur.","ss_btn":"Sitede ara","ss_ph":"Sitede ara…","ss_none":"Hiçbir şey bulunamadı. Başka bir kelime dene.","ss_more":"{n} sonuç daha. Daraltmak için daha fazla yaz.","ss_close":"Aramayı kapat"},"cn":{"meta_title":"Unlimited Cloth：FiveM 服装与纹身制作工具","meta_desc":"Unlimited Cloth 是一款适用于 Windows 和 Linux 的免费桌面程序，可将 GTA V freemode 服装和纹身制作成 FiveM 可用的资源：资源包构建、工作室修复工具、带动画的 3D 预览以及纹身制作。","langlabel":"语言","theme_light":"切换到浅色模式","theme_dark":"切换到深色模式","nav_more":"更多","skip":"跳到正文","nav_what":"功能","nav_dl":"下载","nav_install":"安装","nav_start":"快速上手","nav_clothes":"服装","nav_tattoos":"纹身","nav_studio":"工作室","nav_faq":"常见问题","nav_changelog":"更新日志","h_badge":"免费 · MIT · Windows 和 Linux · 版本 1.0.0","h_title":"FiveM 服装与纹身，可直接串流","h_sub":"Unlimited Cloth 将 GTA V freemode 服装和纹身制作成 FiveM 可用的资源。导入单件服装或整个 addon 资源包，在工作室中修复，在带动画的 freemode ped 身上试穿，然后构建出完整的资源和 .zip。写入的每个文件都会被读回并检查。","h_dl":"下载 1.0.0","h_start":"快速上手","h_note":"无需浏览器标签页、网络端口，也无需 Blender、Python 或 CodeWalker。由 Unlimited Reforge 制作。","alt_studio":"Studio 标签页：穿短上衣和皮裤的女性 freemode ped，右侧是修复工具","w_title":"功能","w_sub":"一个程序完成全部工作，从零散文件到可以直接 <code>ensure</code> 的资源。","w1_t":"服装资源包构建","w1_d":"为 <code>mp_m_freemode_01</code> 和 <code>mp_f_freemode_01</code> 制作 component 和 prop，自动编号，按游戏限制检查，并写出 <code>fxmanifest.lua</code>、<code>stream/</code>、<code>.ymt</code> 和商店 <code>.meta</code>，另附一个 .zip。","w2_t":"工作室修复工具","w2_d":"从身体复制权重、推出身体、贴合与收缩包裹、LOD、着色器、prop、头发替代款、鞋跟、布料物理和贴图工具。每项操作都可以撤销。","w3_t":"3D 预览与动画","w3_d":"带皮肤和你的服装的 freemode ped、31 种姿势和动画，以及<b>显示穿模</b>：用红色标出身体穿出的位置、深度和对应的骨骼。","w4_t":"纹身制作","w4_d":"输入 PNG，输出 512×512 DXT5 .ytd。在 3D 中或 UV 方框里按区域、按身体放置每个纹身，并获得 overlay XML 以及适用于 qb、esx 和 illenium-appearance 的现成列表。","w5_t":"保护你的文件","w5_d":"修复操作在项目文件夹中的副本上进行，原始文件永远不会被修改。任何东西都不会被永久删除：旧的构建会移到系统回收站。","w6_t":"项目与语言","w6_d":"纯 JSON 项目（<code>.ucloth</code>），使用相对路径，在 Windows 和 Linux 上都能打开；自动保存用于崩溃恢复，支持撤销和重做。程序支持 12 种语言。","c_clip":"步行动画中的显示穿模","c_tat":"在 3D 中放置的纹身","c_build":"构建：计划和读回检查","d_title":"下载","d_sub":"版本 1.0.0。所有文件和发布说明都在 GitHub 发布页面上。","d_win_d":"安装程序：选择文件夹，创建快捷方式，可在“应用”中卸载。","d_deb_d":"Debian、Ubuntu、Mint、Pop!_OS 及其他使用 apt 的系统。","d_app_d":"单个文件，可在大多数发行版上运行，无需安装。","d_all":"所有版本","d_note":"预览所用的 freemode ped 随程序附带，无需另外下载任何东西。","i_title":"安装","i_win_steps":"<li>运行 <code>Unlimited-Cloth-Setup-1.0.0.exe</code>。</li><li>选择安装文件夹。程序会创建桌面和开始菜单快捷方式。</li><li>以后可在 设置 → 应用 中卸载。</li>","i_win_warn":"<b>“Windows 已保护你的电脑”/ 未知发布者。</b>安装程序使用 Unlimited Reforge 自己的证书签名，Windows 暂时还不认识它，因此 Microsoft SmartScreen 可能会在首次运行时拦截。点击<b>更多信息</b>，确认文件来自发布页面，然后点击<b>仍要运行</b>。","i_deb":"<b>.deb</b>（Debian、Ubuntu 等）：","i_app":"<b>AppImage</b>：设为可执行后运行。","i_fuse":"如果 AppImage 在 Ubuntu 22.04 或更新版本上无法启动，请安装 FUSE 2：<code>sudo apt install libfuse2</code>（24.04 上为 <code>libfuse2t64</code>）。","i_where_t":"文件保存位置","i_where_d":"设置、自动保存和你自己的 ped：Windows 上在 <code>%APPDATA%\\Unlimited Cloth</code>，Linux 上在 <code>~/.config/Unlimited Cloth</code>。构建出的资源默认放在 <code>Documents/Unlimited Cloth/build</code>，除非你选择其他文件夹。","s_title":"快速上手","s1_t":"首次运行设置","s1_d":"程序以英文启动，并引导你设置语言、偏好、文件夹、ped 以及新项目的默认值。你可以跳过，之后通过 <b>?</b> → <b>重新运行设置</b> 再次运行。","s2_t":"用测试内容试一试","s2_d":"在服装标签页上点击<b>测试服装</b>。你会得到每种身体各一件测试上衣和一顶通用帽子，均由程序自己生成，这样你可以在使用自己的文件之前试用所有工具。","s3_t":"导入你的服装","s3_d":"<b>+ 导入文件</b>支持 <code>.ydd</code>、<code>.ytd</code>、<code>.yld</code>、Sollumz/CodeWalker <code>.ydd.xml</code>、<code>.glb</code>、<code>.obj</code>、<code>.blend</code> 和 <code>.png</code>。<b>文件夹 / 资源包</b>可导入整个文件夹或现有的 addon 资源包。","s4_t":"身体、槽位和贴图","s4_d":"为每件服装选择身体（男性、女性或两者）、component 或 prop 槽位，以及最多 26 个贴图变体（a–z）。列表中的 <b>!</b> 表示还缺少某些内容。","s5_t":"先检查，再构建","s5_d":"在构建标签页上点击<b>检查（计划）</b>，在写入任何内容之前查看每个文件、编号和限制。然后点击<b>全部构建</b>。结果会被读回并检查。","s6_t":"在服务器上","s6_d":"将资源文件夹复制到 <code>resources/</code>，并添加到 <code>server.cfg</code>。新资源包请先在测试服务器上试用，再放到正式服务器上。","cl_title":"服装构建","cl_sub":"服装标签页存放列表；构建标签页写出资源。","cl1_t":"编号","cl1_l":"<li>列表中的顺序就是编号：留空表示使用该槽位中下一个空闲编号。</li><li>固定编号能让已保存的服装搭配始终指向同一件服装。如果两件服装要求同一个编号，第一件保留它，另一件获得下一个空闲编号，计划中会注明。</li><li>同一类 drawable 超过 255 个后，其余的会放入第二个合集（<code>&lt;collection&gt;2</code>）。</li><li>最高编号以下的空缺会用不可见的占位模型填补，因为游戏从 000 开始往上读取。</li>","cl2_t":"检查的限制","cl2_l":"<li>每个槽位和身体 255 个 drawable，每件服装 26 个贴图（a–z）。</li><li>服务器游戏版本的 ped 串流槽位。</li><li>商店条目、文件名长度（小于 128 字节）、小写文件名。</li><li>缺少槽位、身体或贴图的服装会被视为错误，绝不会靠猜测处理。</li>","cl3_t":"写出的内容","cl3_d":"<code>fxmanifest.lua</code>、包含模型、贴图和布料物理的 <code>stream/</code>、每种身体一个 <code>.ymt</code> 和一个商店 <code>.meta</code>、第一人称模型（<code>_1.ydd</code>）、头发替换（<code>pedalternatevariations.meta</code>）、鞋跟高度，以及该文件夹的 <code>.zip</code>。","cl4_t":"重新构建现有资源包","cl4_d":"用<b>文件夹 / 资源包</b>导入已构建的资源包，即可重命名其合集或合并资源包。标志、音效配置、鞋跟高度、prop 头发、头发替换和合集名称都会从其 <code>.ymt</code> 和 <code>.meta</code> 文件中恢复。","t_title":"纹身","t1_t":"制作与放置","t1_l":"<li><b>+ 纹身 (PNG)</b>：每张图片都会变成一个 512×512 DXT5 <code>.ytd</code>。也可以使用现成的 <code>.ytd</code>；构建时其中的贴图会使用纹身的 Id。</li><li>选择身体区域，然后分别在男性和女性身体上放置纹身：在 3D 中直接放在 ped 上，或在<b>UV 方框</b>中（拖动以移动，滚动鼠标滚轮以缩放）。</li><li>Id 就是哈希名称。留空时使用文件名。</li>","t2_t":"写出的内容","t2_l":"<li>overlay XML 和带有 <code>PED_OVERLAY_FILE</code> 的 <code>fxmanifest.lua</code>。</li><li>可选的 <code>shop_tattoo.meta</code>（只有原版游戏的纹身店会读取它）。</li><li>可选的菜单列表，位于 <code>exports/</code>：qb（<code>AllTattoos.json</code>）、esx（<code>Config.TattooList</code>）和 illenium-appearance。较新版本的 illenium-appearance 会自行从 overlay 文件中找到纹身，因此该列表默认关闭。</li>","t_box":"请给纹身资源单独起一个名字。如果纹身资源和服装资源会落在同一个文件夹里，程序会拒绝构建，因为构建其中一个会把另一个移到回收站。","st_title":"工作室工具","st_sub":"操作在项目文件夹中的模型副本上进行。每项操作都可以用 Ctrl+Z 撤销，包括文件。失败的操作会把文件恢复原样。","st_group":"分组","st_tools":"工具","st_g_weights":"权重","st_r_weights":"从身体复制权重 · 平滑权重 · 修正权重 · 同步接缝权重","st_g_fit":"贴合与造型","st_r_fit":"推出身体 · 膨胀 / 收缩 · 贴合身体 · 收缩包裹到身体 · 下摆离地 · 左右镜像 · 对齐袖子 · 收窄袖子 · 应用移动 / 旋转 / 缩放","st_g_mesh":"网格","st_r_mesh":"修复法线 · 焊接接缝 · 闭合开口 · 闭合缝隙 · 实体化（向内） · 重写整个文件","st_g_lod":"细节层级","st_r_lod":"生成 LOD · 为 LOD 赋权重 · 减少三角面","st_g_special":"Prop、头发、鞋跟、物理","st_r_special":"转为 prop · 头发替代款 · 鞋跟姿势 · 鞋跟骨骼 · 生成布料物理 (.yld) · 重新绑定布料物理 · 裁剪未用贴图","st_g_shader":"着色器","st_r_shader":"27 种 ped 着色器，每种都附有用途说明。","st_g_tex":"贴图","st_r_tex":"+ 从 PNG（DXT1/DXT5，带 mipmap）· 重新着色 → 新变体 · 从 PNG 替换 · 导出为 PNG · 法线 + 高光贴图 (PNG)","st_g_export":"导出模型","st_r_export":"Sollumz / CodeWalker XML · .obj（Blender 等）","p_intro":"构建标签页上有一个 <code>subdir_file_mapping</code> 复选框。勾选后，服装资源的 <code>fxmanifest.lua</code> 会加入这一行：","p_list":"<li><b>默认关闭。</b>加上这一行后，没有该策略的服务器会直接拒绝启动该资源。</li><li><b>不加这一行</b>时，缺少该策略的服务器会加载资源包，但不显示任何服装，控制台里也没有任何提示。10 个槽位及以下的服务器会自动获得该策略；超过 10 个槽位则需要 Element Club Argentum（或更高级别）订阅。</li><li>当你的服务器超过 10 个槽位且拥有该策略时，<b>请勾选</b>，这样缺少策略时会显示明确的启动错误，而不是服装不可见。10 个槽位及以下的服务器请保持关闭。</li><li>关闭时，构建计划会提醒你。这一行是否必要尚未在游戏中得到证实，请在你自己的服务器上测试。</li>","q1":"它是免费的吗？","a1":"是的。Unlimited Cloth 免费且基于 MIT 许可证开源，由 Unlimited Reforge 制作。","q2":"我需要 GTA V、Blender 或 CodeWalker 吗？","a2":"不需要。程序自己读写游戏格式，预览用的 freemode ped 也随程序附带。你也可以在Ped标签页上改用自己游戏中的文件（可选）。","q3":"它适用于哪些服装菜单？","a3":"服装资源是普通的 addon 资源包，因此任何读取 addon 服装的菜单都能显示它。对于纹身，程序会为 qb、esx 和 illenium-appearance 写出列表。请对照你所用菜单的版本核对字段名称。","q4":"它会修改我的原始文件吗？","a4":"不会。修复操作在项目文件夹中的副本上进行，挡路的东西（例如旧的构建）会移到系统回收站。任何东西都不会被永久删除。","q5":"我的服装在游戏中不显示","a5":"<li>检查服务器有多少个槽位，以及 <a href=\"#policy\">subdir_file_mapping</a> 策略。</li><li>确认资源已启动（<code>ensure</code>），并且服务器的游戏版本与构建标签页上选择的一致。</li><li>在构建标签页上使用<b>检查现有资源包…</b>读回该文件夹。</li>","q6":"为什么 Windows 会提示未知发布者？","a6":"安装程序使用 Unlimited Reforge 自己的证书签名，而不是向证书颁发机构购买的证书，因此 Windows 暂时还不认识这个发布者。如何通过 SmartScreen，请参阅<a href=\"#install\">安装</a>。","q7":"在哪里获得帮助？","a7":"问题、错误报告和建议请发到 <a href=\"https://discord.gg/uaASPkghXu\" rel=\"noopener\">Unlimited Discord</a>。本程序没有电子邮件地址。","ch_title":"更新日志","ch_first":"首个版本","ch_list":"<li>服装资源包构建：导入 .ydd/.ytd/.yld、整个 addon 资源包、.ydd.xml、.glb、.obj 和 .blend；编号、限制检查、超过 255 时使用第二个合集、.zip。</li><li>重新构建资源包时保留其标志、音效、鞋跟、prop 头发、头发替换和合集名称。</li><li>工作室提供权重、贴合、网格、LOD、prop、头发、鞋跟和布料物理的修复操作，27 种着色器、贴图工具以及 Sollumz/.obj 导出；每项操作都可撤销和重做。</li><li>3D 预览，含 31 种姿势和动画以及穿模检查。</li><li>纹身制作：支持 3D 和 UV 放置、overlay XML、shop_tattoo.meta，以及适用于 qb、esx 和 illenium-appearance 的列表。</li><li>每个构建出的文件都会被读回：模型（含往返测试）、贴图、.ymt（component 和 prop）、商店 meta、挂载的数据文件以及引擎自身的资源包检查。</li><li>内置 freemode ped；你自己的游戏文件是可选的，只补充你提供的部分。</li><li>首次运行设置、12 种语言、自动保存和崩溃恢复。</li>","ch_known":"已知限制：新写出的 .ydd 文件目前只用测试资源包在游戏中验证过，从 GTA V 安装目录导入尚未测试，Windows 版本也是新的。请先在测试服务器上测试。","dc_title":"有问题？加入 Discord","dc_sub":"Unlimited Cloth 及 Unlimited 其他产品的支持、错误报告和建议。","dc_btn":"打开 Unlimited Discord","f_lic":"© 2026 Unlimited Reforge · MIT 许可证","f_rock":"内置的 freemode ped 源自 Rockstar Games 的资源。Unlimited Reforge 与 Rockstar Games 或 Cfx.re 没有任何关联。","ss_btn":"搜索本站","ss_ph":"搜索本站…","ss_none":"没有找到结果，请换个词试试。","ss_more":"还有 {n} 条结果，输入更多内容以缩小范围。","ss_close":"关闭搜索"},"ta":{"meta_title":"Unlimited Cloth: FiveM ஆடை, டாட்டூ கருவி","meta_desc":"Unlimited Cloth என்பது Windows, Linux-க்கான இலவச டெஸ்க்டாப் நிரல். இது GTA V freemode ஆடைகளையும் டாட்டூக்களையும் FiveM-க்குத் தயார் செய்கிறது: pack builder, studio சரிசெய்யும் கருவிகள், அனிமேஷனுடன் 3D முன்னோட்டம், டாட்டூ builder.","langlabel":"மொழி","theme_light":"ஒளி பயன்முறைக்கு மாறு","theme_dark":"இருள் பயன்முறைக்கு மாறு","nav_more":"மேலும்","skip":"உள்ளடக்கத்துக்குச் செல்","nav_what":"அம்சங்கள்","nav_dl":"பதிவிறக்கம்","nav_install":"நிறுவல்","nav_start":"தொடங்குதல்","nav_clothes":"ஆடைகள்","nav_tattoos":"டாட்டூக்கள்","nav_studio":"Studio","nav_faq":"கேள்விகள்","nav_changelog":"மாற்றங்கள்","h_badge":"இலவசம் · MIT · Windows, Linux · பதிப்பு 1.0.0","h_title":"FiveM ஆடைகளும் டாட்டூக்களும், stream செய்யத் தயார்","h_sub":"Unlimited Cloth, GTA V freemode ஆடைகளையும் டாட்டூக்களையும் FiveM-க்குத் தயார் செய்கிறது. ஆடைகளையோ முழு addon pack-களையோ இறக்குமதி செய்து, studio-வில் சரிசெய்து, அசையும் freemode ped-இல் அணிவித்துப் பார்த்து, முழுமையான resource-ஐயும் .zip-ஐயும் build செய்யுங்கள். எழுதப்படும் ஒவ்வொரு கோப்பும் மீண்டும் படித்துச் சரிபார்க்கப்படும்.","h_dl":"1.0.0 பதிவிறக்கு","h_start":"தொடங்குதல்","h_note":"உலாவி tab, network port, Blender, Python, CodeWalker எதுவும் தேவையில்லை. உருவாக்கியது Unlimited Reforge.","alt_studio":"Studio tab: crop top மற்றும் தோல் கால்சட்டை அணிந்த பெண் freemode ped, வலப்புறம் சரிசெய்யும் கருவிகள்","w_title":"இது என்ன செய்கிறது","w_sub":"தனித்தனிக் கோப்புகள் முதல் <code>ensure</code> செய்யக்கூடிய resource வரை, முழு வேலைக்கும் ஒரே நிரல்.","w1_t":"ஆடை pack builder","w1_d":"<code>mp_m_freemode_01</code>, <code>mp_f_freemode_01</code>-க்கான components, props: தானாக எண்ணிடப்பட்டு, கேமின் வரம்புகளுக்கு எதிராகச் சரிபார்க்கப்பட்டு, <code>fxmanifest.lua</code>, <code>stream/</code>, <code>.ymt</code>, shop <code>.meta</code> ஆக எழுதப்படும்; கூடவே ஒரு .zip.","w2_t":"Studio சரிசெய்யும் கருவிகள்","w2_d":"உடலிலிருந்து weights நகலெடுத்தல், உடலிலிருந்து வெளியே தள்ளுதல், fit, shrinkwrap, LOD-கள், shaders, props, முடி மாற்று வடிவங்கள், ஹீல்ஸ், துணி இயற்பியல், texture கருவிகள். ஒவ்வொரு செயலையும் செயல்தவிர்க்கலாம்.","w3_t":"3D முன்னோட்டம், அனிமேஷன்கள்","w3_d":"தோலுடனும் உங்கள் ஆடைகளுடனும் freemode ped, 31 போஸ்கள், அனிமேஷன்கள், மேலும் <b>கிளிப்பிங்கைக் காட்டு</b>: உடல் எங்கே வெளியே தெரிகிறது, எவ்வளவு ஆழம், எந்த bone-இல் என்பதைச் சிவப்பில் காட்டும்.","w4_t":"டாட்டூ builder","w4_d":"PNG உள்ளே, 512×512 DXT5 .ytd வெளியே. ஒவ்வொரு டாட்டூவையும் மண்டலம், உடல் வாரியாக 3D-யிலோ UV சதுரத்திலோ வையுங்கள்; overlay XML-ஐயும் qb, esx, illenium-appearance-க்கான தயார் பட்டியல்களையும் பெறுங்கள்.","w5_t":"உங்கள் கோப்புகள் பாதுகாப்பாக","w5_d":"சரிசெய்யும் செயல்கள் திட்டக் கோப்புறையில் உள்ள நகலில் நடக்கும்; உங்கள் அசல் கோப்பு ஒருபோதும் மாறாது. எதுவும் நிரந்தரமாக நீக்கப்படாது: பழைய build கணினியின் குப்பைத்தொட்டிக்குச் செல்லும்.","w6_t":"திட்டங்கள், மொழிகள்","w6_d":"சாதாரண JSON திட்டங்கள் (<code>.ucloth</code>), Windows, Linux இரண்டிலும் திறக்கும் relative paths உடன்; crash-க்குப் பின் மீட்க autosave, undo, redo. நிரல் 12 மொழிகளில் கிடைக்கிறது.","c_clip":"நடை அனிமேஷனில் கிளிப்பிங்கைக் காட்டு","c_tat":"3D-யில் வைக்கப்பட்ட டாட்டூ","c_build":"Build: திட்டமும் மீள்வாசிப்புச் சரிபார்ப்பும்","d_title":"பதிவிறக்கம்","d_sub":"பதிப்பு 1.0.0. எல்லாக் கோப்புகளும் வெளியீட்டுக் குறிப்புகளுடன் GitHub release பக்கத்தில் உள்ளன.","d_win_d":"Installer: கோப்புறையைத் தேர்ந்தெடுங்கள், shortcuts கிடைக்கும், Apps-இல் uninstall செய்யலாம்.","d_deb_d":"Debian, Ubuntu, Mint, Pop!_OS, மற்ற apt கணினிகள்.","d_app_d":"நிறுவல் இல்லாமல் பெரும்பாலான distributions-இல் இயங்கும் ஒரே கோப்பு.","d_all":"எல்லா வெளியீடுகளும்","d_note":"முன்னோட்டத்துக்கான freemode peds நிரலுடனே வருகின்றன; வேறு எதையும் பதிவிறக்க வேண்டியதில்லை.","i_title":"நிறுவல்","i_win_steps":"<li><code>Unlimited-Cloth-Setup-1.0.0.exe</code>-ஐ இயக்குங்கள்.</li><li>நிறுவல் கோப்புறையைத் தேர்ந்தெடுங்கள். Desktop, Start menu shortcuts உருவாக்கப்படும்.</li><li>பின்னர் அமைப்புகள் → பயன்பாடுகள் (Settings → Apps) இல் uninstall செய்யலாம்.</li>","i_win_warn":"<b>\"Windows உங்கள் PC-ஐப் பாதுகாத்தது\" (Windows protected your PC) / அறியப்படாத வெளியீட்டாளர்.</b> Installer, Unlimited Reforge-இன் சொந்தச் சான்றிதழால் கையொப்பமிடப்பட்டுள்ளது; Windows-க்கு அது இன்னும் தெரியாது, எனவே முதல் முறை Microsoft SmartScreen அதைத் தடுக்கலாம். <b>மேலும் தகவல் (More info)</b> என்பதைக் கிளிக் செய்து, கோப்பு release பக்கத்திலிருந்து வந்ததுதான் என உறுதிசெய்து, பின் <b>எப்படியும் இயக்கு (Run anyway)</b> என்பதைக் கிளிக் செய்யுங்கள்.","i_deb":"<b>.deb</b> (Debian, Ubuntu போன்றவை):","i_app":"<b>AppImage</b>: இயக்கக்கூடியதாக்கி இயக்குங்கள்.","i_fuse":"Ubuntu 22.04 அல்லது புதியதில் AppImage தொடங்கவில்லை என்றால், FUSE 2-ஐ நிறுவுங்கள்: <code>sudo apt install libfuse2</code> (24.04-இல் <code>libfuse2t64</code>).","i_where_t":"கோப்புகள் எங்கே சேமிக்கப்படுகின்றன","i_where_d":"அமைப்புகள், autosave, உங்கள் சொந்த peds: Windows-இல் <code>%APPDATA%\\Unlimited Cloth</code>, Linux-இல் <code>~/.config/Unlimited Cloth</code>. வேறு கோப்புறையைத் தேர்ந்தெடுக்காவிட்டால், build செய்த resources <code>Documents/Unlimited Cloth/build</code>-க்குச் செல்லும்.","s_title":"தொடங்குதல்","s1_t":"முதல் இயக்க அமைப்பு","s1_d":"நிரல் ஆங்கிலத்தில் தொடங்கி, மொழி, விருப்பங்கள், கோப்புறைகள், peds, புதிய திட்டங்களின் இயல்புநிலைகள் வழியாக உங்களை அழைத்துச் செல்லும். இதைத் தவிர்த்து, பின்னர் <b>?</b> → <b>அமைப்பை மீண்டும் இயக்கு</b> மூலம் மீண்டும் இயக்கலாம்.","s2_t":"சோதனை உள்ளடக்கத்துடன் முயலுங்கள்","s2_d":"ஆடைகள் tab-இல் <b>சோதனை ஆடைகள்</b> அழுத்துங்கள். ஒவ்வொரு உடலுக்கும் ஒரு சோதனை மேலாடையும், இரண்டுக்கும் ஒரு தொப்பியும் கிடைக்கும்; இவற்றை நிரலே உருவாக்குகிறது. உங்கள் கோப்புகளுக்கு முன் எல்லாக் கருவிகளையும் முயலலாம்.","s3_t":"உங்கள் ஆடைகளை இறக்குமதி செய்யுங்கள்","s3_d":"<b>+ கோப்புகளை இறக்குமதி செய்</b> ஏற்பவை: <code>.ydd</code>, <code>.ytd</code>, <code>.yld</code>, Sollumz/CodeWalker <code>.ydd.xml</code>, <code>.glb</code>, <code>.obj</code>, <code>.blend</code>, <code>.png</code>. <b>கோப்புறை / pack</b> முழுக் கோப்புறையையோ இருக்கும் addon pack-ஐயோ ஏற்கும்.","s4_t":"உடல், slot, textures","s4_d":"ஒவ்வொரு ஆடைக்கும் உடல் (ஆண், பெண் அல்லது இரண்டும்), component அல்லது prop slot, அதிகபட்சம் 26 texture வகைகள் (a–z) தேர்ந்தெடுங்கள். பட்டியலில் <b>!</b> இருந்தால் ஏதோ இன்னும் இல்லை என்று பொருள்.","s5_t":"சரிபார், பிறகு build","s5_d":"Build tab-இல் <b>சரிபார் (திட்டம்)</b> அழுத்தி, எதுவும் எழுதப்படும் முன் ஒவ்வொரு கோப்பு, எண், வரம்பையும் பாருங்கள். பிறகு <b>அனைத்தையும் build செய்</b> அழுத்துங்கள். முடிவு மீண்டும் படித்துச் சரிபார்க்கப்படும்.","s6_t":"சர்வரில்","s6_d":"Resource கோப்புறைகளை <code>resources/</code>-க்கு நகலெடுத்து <code>server.cfg</code>-இல் சேருங்கள். புதிய pack-ஐ live சர்வரில் போடும் முன் சோதனை சர்வரில் முயலுங்கள்.","cl_title":"ஆடை builder","cl_sub":"ஆடைகள் tab-இல் பட்டியல் உள்ளது; Build tab resource-ஐ எழுதுகிறது.","cl1_t":"எண்கள்","cl1_l":"<li>பட்டியலில் உள்ள வரிசையே எண்: காலியாக இருந்தால் அந்த slot-இல் அடுத்த இலவச எண்.</li><li>நிலையான எண் வைத்தால், சேமித்த outfits அதே ஆடையையே குறிக்கும். இரண்டு ஆடைகள் ஒரே எண்ணைக் கேட்டால், முதலாவது அதை வைத்துக்கொள்ளும், மற்றது அடுத்த இலவச எண்ணைப் பெறும்; திட்டம் இதைச் சொல்லும்.</li><li>ஒரே வகையில் 255 drawables-க்கு மேல் போனால், மீதி இரண்டாவது தொகுப்புக்குச் செல்லும் (<code>&lt;collection&gt;2</code>).</li><li>கேம் 000-இலிருந்து மேல்நோக்கிப் படிப்பதால், உயர்ந்த எண்ணுக்குக் கீழே உள்ள இடைவெளி கண்ணுக்குத் தெரியாத dummy-ஆல் நிரப்பப்படும்.</li>","cl2_t":"சரிபார்க்கும் வரம்புகள்","cl2_l":"<li>ஒவ்வொரு slot, உடலுக்கும் 255 drawables; ஒவ்வொரு ஆடைக்கும் 26 textures (a–z).</li><li>சர்வரின் game build-க்கான ped streaming slots.</li><li>Shop entries, கோப்புப் பெயர் நீளம் (128 bytes-க்குக் கீழ்), சிறிய எழுத்துப் பெயர்கள்.</li><li>Slot, உடல் அல்லது texture இல்லாத ஆடை பிழையாகும்; அது ஒருபோதும் ஊகிக்கப்படாது.</li>","cl3_t":"என்ன எழுதப்படும்","cl3_d":"<code>fxmanifest.lua</code>, models, textures, துணி இயற்பியலுடன் <code>stream/</code>, ஒவ்வொரு உடலுக்கும் ஒரு <code>.ymt</code>, ஒரு shop <code>.meta</code>, first-person models (<code>_1.ydd</code>), முடி மாற்றங்கள் (<code>pedalternatevariations.meta</code>), ஹீல் உயரங்கள், கோப்புறையின் <code>.zip</code>.","cl4_t":"இருக்கும் pack-ஐ மீண்டும் build செய்தல்","cl4_d":"Build செய்த pack-ஐ <b>கோப்புறை / pack</b> மூலம் இறக்குமதி செய்து, அதன் தொகுப்பின் பெயரை மாற்றலாம் அல்லது pack-களை இணைக்கலாம். Flags, audio profiles, ஹீல் உயரங்கள், prop முடி, முடி மாற்றங்கள், தொகுப்புப் பெயர் ஆகியவை அதன் <code>.ymt</code>, <code>.meta</code> கோப்புகளிலிருந்து திரும்பக் கிடைக்கும்.","t_title":"டாட்டூக்கள்","t1_t":"உருவாக்கி வைத்தல்","t1_l":"<li><b>+ டாட்டூ (PNG)</b>: ஒவ்வொரு படமும் 512×512 DXT5 <code>.ytd</code> ஆகிறது. தயாரான <code>.ytd</code>-உம் வேலை செய்யும்; build-இல் அதனுள் உள்ள texture டாட்டூவின் Id-ஐப் பெறும்.</li><li>உடல் மண்டலத்தைத் தேர்ந்தெடுத்து, டாட்டூவை ஆண், பெண் உடல்களில் தனித்தனியாக வையுங்கள்: ped மீது 3D-யில், அல்லது <b>UV சதுரம்</b>-இல் (நகர்த்த இழுங்கள், அளவு மாற்ற mouse wheel).</li><li>Id என்பது hash பெயர். காலியாக இருந்தால் கோப்புப் பெயர் பயன்படும்.</li>","t2_t":"என்ன எழுதப்படும்","t2_l":"<li>Overlay XML, <code>PED_OVERLAY_FILE</code> உடன் <code>fxmanifest.lua</code>.</li><li>விருப்பத்தேர்வாக <code>shop_tattoo.meta</code> (அடிப்படை கேமின் டாட்டூ கடை மட்டுமே இதைப் படிக்கும்).</li><li>விருப்பத்தேர்வாக <code>exports/</code>-இல் மெனு பட்டியல்கள்: qb (<code>AllTattoos.json</code>), esx (<code>Config.TattooList</code>), illenium-appearance. புதிய illenium-appearance பதிப்புகள் overlay கோப்பிலிருந்தே டாட்டூக்களைத் தாமாகக் கண்டறியும், எனவே அந்தப் பட்டியல் இயல்பாக அணைக்கப்பட்டுள்ளது.</li>","t_box":"டாட்டூ resource-க்குத் தனிப் பெயர் கொடுங்கள். டாட்டூ, ஆடை resources ஒரே கோப்புறையில் விழுந்தால் நிரல் build செய்ய மறுக்கும், ஏனெனில் ஒன்றை build செய்தால் மற்றது குப்பைத்தொட்டிக்குப் போகும்.","st_title":"Studio கருவிகள்","st_sub":"செயல்கள் திட்டக் கோப்புறையில் உள்ள model நகலில் நடக்கும். ஒவ்வொரு செயலையும் Ctrl+Z மூலம், கோப்புகள் உட்பட, செயல்தவிர்க்கலாம். தோல்வியடையும் செயல் கோப்பை முன்பு இருந்தபடியே திருப்பி வைக்கும்.","st_group":"குழு","st_tools":"கருவிகள்","st_g_weights":"Weights","st_r_weights":"உடலிலிருந்து weights நகலெடு · Weights-ஐ மென்மையாக்கு · Weights-ஐ சரியாக்கு · Seam weights-ஐ ஒத்திசை","st_g_fit":"பொருத்தம் மற்றும் வடிவம்","st_r_fit":"உடலிலிருந்து வெளியே தள்ளு · பெரிதாக்கு / சுருக்கு · உடலுக்குப் பொருத்து · உடலுக்கு shrinkwrap · விளிம்பைத் தரைக்கு மேல் · இடம்/வலம் mirror · கைகளை சீரமை · கைகளைக் குறுக்கு · நகர்த்து / சுழற்று / அளவிடு பயன்படுத்து","st_g_mesh":"Mesh","st_r_mesh":"Normals-ஐ சரிசெய் · Seams-ஐ weld செய் · திறப்புகளை மூடு · இடைவெளிகளை மூடு · Solidify (உள்புறம்) · முழுக் கோப்பையும் மீண்டும் எழுது","st_g_lod":"விவர நிலை (LOD)","st_r_lod":"LOD-கள் உருவாக்கு · LOD-களுக்கு weights இடு · முக்கோணங்களைக் குறை","st_g_special":"Props, முடி, ஹீல்ஸ், இயற்பியல்","st_r_special":"Prop ஆக மாற்று · முடி மாற்று வடிவம் · ஹீல் போஸ் · ஹீல் bones · துணி இயற்பியல் உருவாக்கு (.yld) · துணி இயற்பியலை மீண்டும் bind செய் · பயன்படாத texture-ஐ வெட்டு","st_g_shader":"Shader","st_r_shader":"27 ped shaders, ஒவ்வொன்றும் எதற்கு என்ற குறிப்புடன்.","st_g_tex":"Textures","st_r_tex":"+ PNG இலிருந்து (mipmaps உடன் DXT1/DXT5) · மறு நிறமிடு → புதிய வகை · PNG இலிருந்து மாற்று · PNG ஆக export செய் · Normal + spec maps (PNG)","st_g_export":"மாடலை export செய்","st_r_export":"Sollumz / CodeWalker XML · .obj (Blender போன்றவை)","p_intro":"Build tab-இல் <code>subdir_file_mapping</code> checkbox உள்ளது. அது இயக்கத்தில் இருந்தால், ஆடை resource-இன் <code>fxmanifest.lua</code>-இல் இந்த வரி சேர்க்கப்படும்:","p_list":"<li><b>இயல்பாக அணைக்கப்பட்டுள்ளது.</b> இந்த வரி இருந்தால், policy இல்லாத சர்வர் resource-ஐத் தொடங்கவே மறுக்கும்.</li><li><b>வரி இல்லாவிட்டால்</b>, policy இல்லாத சர்வர் pack-ஐ ஏற்றும், ஆனால் ஆடைகள் எதுவும் தெரியாது, console-இலும் எதுவும் வராது. 10 அல்லது குறைவான slots உள்ள சர்வருக்கு policy தானாகக் கிடைக்கும்; அதற்கு மேல் Element Club Argentum (அல்லது மேல்) subscription உடன் வரும்.</li><li>உங்கள் சர்வரில் 10-க்கு மேல் slots இருந்து policy-யும் இருந்தால் <b>இதை இயக்குங்கள்</b>; அப்போது policy இல்லாதது, கண்ணுக்குத் தெரியாத ஆடைகளாக அல்லாமல், தெளிவான தொடக்கப் பிழையாகத் தெரியும். 10 அல்லது குறைவான slots உள்ள சர்வரில் அணைத்தே வையுங்கள்.</li><li>அணைக்கப்பட்டிருக்கும்போது build திட்டம் நினைவூட்டும். இந்த வரி தேவையா என்பது கேமில் இன்னும் நிரூபிக்கப்படவில்லை, எனவே உங்கள் சர்வரில் சோதியுங்கள்.</li>","q1":"இது இலவசமா?","a1":"ஆம். Unlimited Cloth இலவசமானது, MIT உரிமத்தின் கீழ் திறந்த மூலமானது; உருவாக்கியது Unlimited Reforge.","q2":"GTA V, Blender அல்லது CodeWalker தேவையா?","a2":"இல்லை. நிரல் கேம் formats-ஐத் தானே படித்து எழுதுகிறது; முன்னோட்டத்துக்கான freemode peds அதனுடனே வருகின்றன. விரும்பினால் Peds tab-இல் உங்கள் சொந்த கேம் கோப்புகளைப் பயன்படுத்தலாம்.","q3":"எந்த ஆடை மெனுக்களுடன் வேலை செய்யும்?","a3":"ஆடை resource ஒரு சாதாரண addon pack, எனவே addon ஆடைகளைப் படிக்கும் எந்த மெனுவும் அதைக் காட்டும். டாட்டூக்களுக்கு நிரல் qb, esx, illenium-appearance-க்கான பட்டியல்களை எழுதுகிறது. புலப் பெயர்களை உங்கள் மெனு பதிப்புடன் சரிபாருங்கள்.","q4":"என் அசல் கோப்புகளை மாற்றுமா?","a4":"இல்லை. சரிசெய்யும் செயல்கள் திட்டக் கோப்புறையில் உள்ள நகலில் நடக்கும்; வழியில் இருக்கும் எதுவும் (உதா. பழைய build) கணினியின் குப்பைத்தொட்டிக்குச் செல்லும். எதுவும் நிரந்தரமாக நீக்கப்படாது.","q5":"என் ஆடைகள் கேமில் தெரியவில்லை","a5":"<li>சர்வரில் எத்தனை slots உள்ளன என்பதையும் <a href=\"#policy\">subdir_file_mapping</a> policy-யையும் சரிபாருங்கள்.</li><li>Resource தொடங்கப்பட்டுள்ளதா (<code>ensure</code>), சர்வரின் game build Build tab-இல் தேர்ந்தெடுத்ததுதானா என உறுதிசெய்யுங்கள்.</li><li>கோப்புறையை மீண்டும் படிக்க Build tab-இல் <b>இருக்கும் pack-ஐ சரிபார்…</b> பயன்படுத்துங்கள்.</li>","q6":"அறியப்படாத வெளியீட்டாளர் என்று Windows ஏன் எச்சரிக்கிறது?","a6":"Installer, சான்றிதழ் நிறுவனத்திடம் வாங்கியதால் அல்ல, Unlimited Reforge-இன் சொந்தச் சான்றிதழால் கையொப்பமிடப்பட்டுள்ளது; எனவே Windows-க்கு வெளியீட்டாளர் இன்னும் தெரியாது. SmartScreen-ஐக் கடப்பது எப்படி என்பதற்கு <a href=\"#install\">நிறுவல்</a> பாருங்கள்.","q7":"உதவி எங்கே கிடைக்கும்?","a7":"கேள்விகள், பிழைகள், யோசனைகளை <a href=\"https://discord.gg/uaASPkghXu\" rel=\"noopener\">Unlimited Discord</a>-இல் பகிருங்கள். நிரலுக்கு மின்னஞ்சல் முகவரி இல்லை.","ch_title":"மாற்றங்கள்","ch_first":"முதல் வெளியீடு","ch_list":"<li>ஆடை pack builder: .ydd/.ytd/.yld, முழு addon packs, .ydd.xml, .glb, .obj, .blend இறக்குமதி; எண்ணிடல், வரம்புச் சரிபார்ப்பு, 255-க்கு மேல் இரண்டாவது தொகுப்பு, .zip.</li><li>Pack-ஐ மீண்டும் build செய்யும்போது அதன் flags, audio, ஹீல்ஸ், prop முடி, முடி மாற்றங்கள், தொகுப்புப் பெயர் காக்கப்படும்.</li><li>Weights, fit, mesh, LOD-கள், props, முடி, ஹீல்ஸ், துணி இயற்பியலுக்கான சரிசெய்யும் செயல்களுடன் Studio, 27 shaders, texture கருவிகள், Sollumz/.obj export; ஒவ்வொரு செயலுக்கும் undo, redo.</li><li>31 போஸ்கள், அனிமேஷன்கள், clipping சரிபார்ப்புடன் 3D முன்னோட்டம்.</li><li>3D, UV வைப்பு, overlay XML, shop_tattoo.meta, qb, esx, illenium-appearance பட்டியல்களுடன் டாட்டூ builder.</li><li>Build செய்த ஒவ்வொரு கோப்பும் மீண்டும் படிக்கப்படும்: models (round trip உடன்), textures, .ymt (components, props), shop meta, mount செய்த data files, engine-இன் சொந்த pack சரிபார்ப்புகள்.</li><li>உள்ளிணைந்த freemode peds; உங்கள் சொந்த கேம் கோப்புகள் விருப்பத்தேர்வு, நீங்கள் தருவதை மட்டுமே நிரப்பும்.</li><li>முதல் இயக்க அமைப்பு, 12 மொழிகள், autosave, crash மீட்பு.</li>","ch_known":"அறிந்த வரம்புகள்: புதிதாக எழுதப்பட்ட .ydd கோப்புகள் சோதனை pack உடன் மட்டுமே கேமில் நிரூபிக்கப்பட்டுள்ளன, GTA V நிறுவலிலிருந்து இறக்குமதி சோதிக்கப்படவில்லை, Windows build புதியது. முதலில் சோதனை சர்வரில் சோதியுங்கள்.","dc_title":"கேள்விகளா? Discord-இல் சேருங்கள்","dc_sub":"Unlimited Cloth, மற்ற Unlimited கருவிகளுக்கான ஆதரவு, பிழை அறிக்கைகள், யோசனைகள்.","dc_btn":"Unlimited Discord-ஐத் திற","f_lic":"© 2026 Unlimited Reforge · MIT உரிமம்","f_rock":"உள்ளிணைந்த freemode peds, Rockstar Games assets-இலிருந்து பெறப்பட்டவை. Unlimited Reforge, Rockstar Games அல்லது Cfx.re உடன் தொடர்புடையது அல்ல.","ss_btn":"தளத்தில் தேடு","ss_ph":"தளத்தில் தேடு…","ss_none":"எதுவும் கிடைக்கவில்லை. வேறு சொல்லை முயற்சிக்கவும்.","ss_more":"இன்னும் {n} முடிவுகள். குறைக்க மேலும் தட்டச்சு செய்யவும்.","ss_close":"தேடலை மூடு"}};
